export type PaymentType = 'Supplier' | 'Payroll';

export type PaymentStatus = 'awaiting-approval' | 'awaiting-second-approval' | 'prepared-by-you';

export type PaymentFlag =
  | 'possible-duplicate'
  | 'new-beneficiary'
  | 'bank-details-changed'
  | 'above-usual-amount'
  | 'four-eyes-required'
  | 'own-payment';

export interface Approver {
  readonly id: string;
  readonly name: string;
  readonly role: string;
  readonly organisation: string;
}

export interface CutOff {
  readonly currency: CurrencyCode;
  readonly label: string;
  readonly time: string;
  readonly zone: string;
  readonly londonEquivalent: string;
  readonly minutesRemaining: number;
  readonly remainingLabel: string;
  readonly urgency: 'critical' | 'warning' | 'normal';
}

export interface Payment {
  readonly id: string;
  readonly reference: string;
  readonly beneficiary: string;
  readonly country: string;
  readonly bankName: string;
  readonly accountMasked: string;
  readonly debitAccountMasked: string;
  readonly currency: CurrencyCode;
  readonly amount: number;
  readonly amountFormatted: string;
  readonly usdEquivalentFormatted: string;
  readonly valueDate: string;
  readonly type: PaymentType;
  readonly preparedBy: string;
  readonly preparedAt: string;
  readonly status: PaymentStatus;
  readonly approvalsRequired: 1 | 2;
  readonly approvalsReceived: 0 | 1;
  readonly firstApprover?: string;
  readonly flags: readonly PaymentFlag[];
  readonly duplicateOf?: string;
  readonly note?: string;
