import { useMemo, useState } from "react";
import {
  Banner,
  BannerContent,
  Button,
  Card,
  Checkbox,
  Dialog,
  DialogActions,
  DialogContent,
  DialogHeader,
  Divider,
  FlowLayout,
  FormField,
  FormFieldLabel,
  GridItem,
  GridLayout,
  H1,
  H2,
  H3,
  Label,
  ListBox,
  MultilineInput,
  Option,
  SplitLayout,
  StackLayout,
  StatusIndicator,
  Text,
  ToggleButton,
  ToggleButtonGroup,
} from "@salt-ds/core";
import {
  approver,
  asOf,
  cutOffs,
  flagLabels,
  fourEyesThreshold,
  payments,
  type Payment,
  type PaymentFlag,
} from "./data";

type Decision = "approved" | "first-approval" | "held";
type Filter = "all" | "GBP" | "EUR" | "USD" | "flagged";

const riskFlags: PaymentFlag[] = [
  "possible-duplicate",
  "new-beneficiary",
  "bank-details-changed",
  "above-usual-amount",
];

function cutOffFor(p: Payment) {
  return cutOffs.find((c) => c.currency === p.currency)!;
}

function lastFour(masked: string) {
  return `••••${masked.replace(/[^0-9]/g, "").slice(-4)}`;
}

function DetailRow({ label, value }: { label: string; value: string }) {
  return (
    <StackLayout gap={0}>
      <Label color="secondary">{label}</Label>
      <Text>{value}</Text>
    </StackLayout>
  );
}

export default function UrgentPaymentApprovals() {
  const [filter, setFilter] = useState<Filter>("all");
  const [selectedId, setSelectedId] = useState<string>("p2");
  const [decisions, setDecisions] = useState<Record<string, Decision>>({});
  const [checked, setChecked] = useState<Record<string, boolean>>({});
  const [confirmOpen, setConfirmOpen] = useState(false);
  const [holdOpen, setHoldOpen] = useState(false);
  const [holdReason, setHoldReason] = useState("");
  const [holdReasons, setHoldReasons] = useState<Record<string, string>>({});
  const [lastAction, setLastAction] = useState<string | null>(null);

  const sorted = useMemo(
    () =>
      [...payments].sort(
        (a, b) =>
          cutOffFor(a).minutesRemaining - cutOffFor(b).minutesRemaining ||
          b.flags.length - a.flags.length,
      ),
    [],
  );

  const visible = useMemo(
    () =>
      sorted.filter((p) => {
        if (filter === "all") return true;
        if (filter === "flagged")
          return p.flags.some((f) => riskFlags.includes(f));
        return p.currency === filter;
      }),
    [sorted, filter],
  );

  const selected = payments.find((p) => p.id === selectedId) ?? payments[0];
  const cutOff = cutOffFor(selected);
  const decision = decisions[selected.id];
  const hasRisk = selected.flags.some((f) => riskFlags.includes(f));
  const isOwn = selected.status === "prepared-by-you";
  const needsCheck = hasRisk && !checked[selected.id];
  const duplicate = selected.duplicateOf
    ? payments.find((p) => p.id === selected.duplicateOf)
    : undefined;

  const pendingCount = payments.filter(
    (p) => !decisions[p.id] && p.status !== "prepared-by-you",
  ).length;

  const statusText = (p: Payment): string => {
    const d = decisions[p.id];
    if (d === "approved") return "Released";
    if (d === "first-approval") return "Awaiting second approver";
    if (d === "held") return "On hold";
    if (p.status === "prepared-by-you") return "Prepared by you";
    if (p.status === "awaiting-second-approval")
      return p.approvalsReceived === 1
        ? "Needs your second approval"
        : "Needs 2 approvals";
    return "Awaiting approval";
  };

  const statusKind = (
    p: Payment,
  ): "success" | "info" | "warning" | "error" => {
    const d = decisions[p.id];
    if (d === "approved") return "success";
    if (d === "first-approval") return "info";
    if (d === "held") return "warning";
    if (p.flags.some((f) => riskFlags.includes(f))) return "error";
    if (p.status === "prepared-by-you") return "info";
    return "warning";
  };

  const approveWouldRelease =
    selected.approvalsRequired === 1 || selected.approvalsReceived === 1;

  const handleApprove = () => {
    const next: Decision = approveWouldRelease ? "approved" : "first-approval";
    setDecisions((d) => ({ ...d, [selected.id]: next }));
    setLastAction(
      next === "approved"
        ? `${selected.reference} released: ${selected.amountFormatted} to ${selected.beneficiary}.`
        : `${selected.reference} approved by you. A second approver must release it.`,
    );
    setConfirmOpen(false);
  };

  const handleHold = () => {
    setDecisions((d) => ({ ...d, [selected.id]: "held" }));
    setHoldReasons((r) => ({ ...r, [selected.id]: holdReason }));
    setLastAction(`${selected.reference} put on hold.`);
    setHoldReason("");
    setHoldOpen(false);
  };

  const handleUndo = () => {
    setDecisions((d) => {
      const next = { ...d };
      delete next[selected.id];
      return next;
    });
    setLastAction(null);
  };

  return (
    <StackLayout gap={3} padding={3}>
      <SplitLayout
        align="end"
        startItem={
          <StackLayout gap={1}>
            <H1>Approvals</H1>
            <Text color="secondary">
              {pendingCount} urgent payments waiting for {approver.name} · As of{" "}
              {asOf.date}, {asOf.time} London
            </Text>
          </StackLayout>
        }
        endItem={
          <FlowLayout gap={2} aria-label="Cut-offs today">
            {cutOffs.map((c) => (
              <StatusIndicator
                key={c.currency}
                status={c.urgency === "critical" ? "warning" : "info"}
              >
                <Text>
                  <strong>{c.label}</strong> {c.time} {c.zone} ·{" "}
                  {c.remainingLabel}
                </Text>
              </StatusIndicator>
            ))}
          </FlowLayout>
        }
      />

      {lastAction && (
        <Banner status="success">
          <BannerContent>{lastAction}</BannerContent>
        </Banner>
      )}

      <GridLayout columns={{ xs: 1, md: 12 }} gap={3}>
        <GridItem colSpan={{ xs: 1, md: 5 }}>
          <Card>
            <StackLayout gap={2}>
              <SplitLayout
                startItem={<H2 styleAs="h3">Payments</H2>}
                endItem={
                  <Text color="secondary">
                    {visible.length} shown
                  </Text>
                }
              />
              <ToggleButtonGroup
                aria-label="Filter payments"
                value={filter}
                onChange={(e) =>
                  setFilter(
                    (e.currentTarget as HTMLButtonElement).value as Filter,
                  )
                }
              >
                <ToggleButton value="all">All</ToggleButton>
                <ToggleButton value="GBP">GBP</ToggleButton>
                <ToggleButton value="EUR">EUR</ToggleButton>
                <ToggleButton value="USD">USD</ToggleButton>
                <ToggleButton value="flagged">Flagged</ToggleButton>
              </ToggleButtonGroup>
              <ListBox
                aria-label="Urgent payments"
                selected={[selected.id]}
                onSelectionChange={(_e, newSelected) => {
                  if (newSelected[0]) setSelectedId(newSelected[0] as string);
                }}
              >
                {visible.map((p) => (
                  <Option key={p.id} value={p.id}>
                    <StackLayout gap={0}>
                      <SplitLayout
                        startItem={<Text>{p.beneficiary}</Text>}
                        endItem={<Text>{p.amountFormatted}</Text>}
                      />
                      <SplitLayout
                        startItem={
                          <Text styleAs="label" color="secondary">
                            {p.reference} · {lastFour(p.accountMasked)} ·{" "}
                            {cutOffFor(p).remainingLabel}
                          </Text>
                        }
                        endItem={
                          <StatusIndicator status={statusKind(p)}>
                            <Text styleAs="label">{statusText(p)}</Text>
                          </StatusIndicator>
                        }
                      />
                    </StackLayout>
                  </Option>
                ))}
              </ListBox>
              {visible.length === 0 && (
                <Text color="secondary">No payments match this filter.</Text>
              )}
            </StackLayout>
          </Card>
        </GridItem>

        <GridItem colSpan={{ xs: 1, md: 7 }}>
          <Card>
            <StackLayout gap={3}>
              <StackLayout gap={1}>
                <SplitLayout
                  startItem={<H2>{selected.beneficiary}</H2>}
                  endItem={
                    <StatusIndicator status={statusKind(selected)}>
                      <Text>{statusText(selected)}</Text>
                    </StatusIndicator>
                  }
                />
                <Text styleAs="h2">{selected.amountFormatted}</Text>
                <Text color="secondary">
                  {selected.reference} · {selected.type} · Value date{" "}
                  {selected.valueDate} · {cutOff.label} {cutOff.time}{" "}
                  {cutOff.zone} ({cutOff.remainingLabel})
                </Text>
              </StackLayout>

              <StackLayout gap={2}>
                <H3>Beneficiary account</H3>
                <GridLayout columns={{ xs: 1, sm: 2 }} gap={2}>
                  <DetailRow label="Account" value={selected.accountMasked} />
                  <DetailRow label="Bank" value={selected.bankName} />
                  <DetailRow label="Country" value={selected.country} />
                  <DetailRow
                    label="Debit account"
                    value={lastFour(selected.debitAccountMasked)}
                  />
                  <DetailRow
                    label="USD equivalent"
                    value={selected.usdEquivalentFormatted}
                  />
                  <DetailRow
                    label="Prepared by"
                    value={`${selected.preparedBy}, ${selected.preparedAt} London`}
                  />
                </GridLayout>
              </StackLayout>

              <Divider />

              <StackLayout gap={2}>
                <H3>Flags</H3>
                {selected.flags.length === 0 ? (
                  <StatusIndicator status="success">
                    <Text>No flags. {selected.note ?? ""}</Text>
                  </StatusIndicator>
                ) : (
                  selected.flags.map((f) => (
                    <Banner
                      key={f}
                      status={
                        f === "possible-duplicate" ||
                        f === "bank-details-changed"
                          ? "error"
                          : f === "own-payment" || f === "four-eyes-required"
                            ? "info"
                            : "warning"
                      }
                    >
                      <BannerContent>
                        <StackLayout gap={0}>
                          <Text>
                            <strong>{flagLabels[f]}</strong>
                          </Text>
                          {f === "four-eyes-required" && (
                            <Text>
                              Payments over {fourEyesThreshold} need two
                              approvers.
                              {selected.firstApprover
                                ? ` First approval: ${selected.firstApprover}.`
                                : " No approvals yet."}
                            </Text>
                          )}
                          {f === "possible-duplicate" && duplicate && (
                            <Text>
                              Matches {duplicate.reference} prepared by{" "}
                              {duplicate.preparedBy}, {duplicate.preparedAt}.{" "}
                              <Button
                                appearance="transparent"
                                onClick={() => setSelectedId(duplicate.id)}
                              >
                                View {duplicate.reference}
                              </Button>
                            </Text>
                          )}
                        </StackLayout>
                      </BannerContent>
                    </Banner>
                  ))
                )}
                {selected.flags.length > 0 && selected.note && (
                  <Text color="secondary">{selected.note}</Text>
                )}
                {decision === "held" && holdReasons[selected.id] && (
                  <Text>Hold reason: {holdReasons[selected.id]}</Text>
                )}
              </StackLayout>

              {hasRisk && !decision && !isOwn && (
                <Checkbox
                  label="I've checked the beneficiary account and flags above"
                  checked={!!checked[selected.id]}
                  onChange={(e) =>
                    setChecked((c) => ({
                      ...c,
                      [selected.id]: e.target.checked,
                    }))
                  }
                />
              )}

              <Divider />

              <SplitLayout
                startItem={
                  <Text color="secondary">
                    {isOwn
                      ? "You can't release a payment you prepared."
                      : decision
                        ? "Decision recorded."
                        : approveWouldRelease
                          ? "Approving releases this payment."
                          : "Approving records the first of two approvals."}
                  </Text>
                }
                endItem={
                  <FlowLayout gap={1}>
                    {decision ? (
                      <Button appearance="bordered" onClick={handleUndo}>
                        Undo
                      </Button>
                    ) : (
                      <>
                        <Button
                          appearance="bordered"
                          disabled={isOwn}
                          onClick={() => setHoldOpen(true)}
                        >
                          Hold
                        </Button>
                        <Button
                          sentiment="accented"
                          disabled={isOwn || needsCheck}
                          onClick={() => setConfirmOpen(true)}
                        >
                          {approveWouldRelease ? "Approve and release" : "Approve"}
                        </Button>
                      </>
                    )}
                  </FlowLayout>
                }
              />
            </StackLayout>
          </Card>
        </GridItem>
      </GridLayout>

      <Dialog open={confirmOpen} onOpenChange={setConfirmOpen}>
        <DialogHeader header={`Approve ${selected.reference}?`} />
        <DialogContent>
          <StackLayout gap={1}>
            <Text>
              {selected.amountFormatted} to {selected.beneficiary}
            </Text>
            <Text>
              {selected.bankName} · {selected.accountMasked}
            </Text>
            <Text color="secondary">
              {approveWouldRelease
                ? `Released before the ${cutOff.label} at ${cutOff.time} ${cutOff.zone}.`
                : "A second approver must release this payment."}
            </Text>
          </StackLayout>
        </DialogContent>
        <DialogActions>
          <Button appearance="bordered" onClick={() => setConfirmOpen(false)}>
            Cancel
          </Button>
          <Button sentiment="accented" onClick={handleApprove}>
            Approve
          </Button>
        </DialogActions>
      </Dialog>

      <Dialog open={holdOpen} onOpenChange={setHoldOpen}>
        <DialogHeader header={`Hold ${selected.reference}`} />
        <DialogContent>
          <FormField>
            <FormFieldLabel>Reason for hold</FormFieldLabel>
            <MultilineInput
              value={holdReason}
              onChange={(e) =>
                setHoldReason(
                  (e.target as unknown as HTMLTextAreaElement).value,
                )
              }
            />
          </FormField>
        </DialogContent>
        <DialogActions>
          <Button appearance="bordered" onClick={() => setHoldOpen(false)}>
            Cancel
          </Button>
          <Button sentiment="accented" onClick={handleHold}>
            Put on hold
          </Button>
        </DialogActions>
      </Dialog>
    </StackLayout>
  );
}

