import { useEffect, useMemo, useState } from "react";
import {
  Banner,
  BannerContent,
  Button,
  Card,
  Checkbox,
  Dialog,
  DialogActions,
  DialogContent,
  DialogHeader,
  Display3,
  Divider,
  FlexLayout,
  FormField,
  FormFieldLabel,
  H1,
  H2,
  H3,
  Label,
  LinearProgress,
  StackLayout,
  StatusIndicator,
  Text,
} from "@salt-ds/core";
import { ChevronLeftIcon, ChevronRightIcon } from "@salt-ds/icons";
import {
  approver,
  asOf,
  cutOffs,
  flagLabels,
  fourEyesThreshold,
  payments,
  type CurrencyCode,
  type Payment,
} from "./data";

type Decision = "approved" | "held" | "skipped";

const currencyOrder: CurrencyCode[] = ["GBP", "EUR", "USD"];

const last4 = (masked: string) => masked.replace(/\s/g, "").slice(-4);

const formatAmount = (currency: string, amount: number) =>
  `${currency} ${amount.toLocaleString("en-GB", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  })}`;

const formatCountdown = (seconds: number) => {
  if (seconds <= 0) return "Cut-off passed";
  const h = Math.floor(seconds / 3600);
  const m = Math.floor((seconds % 3600) / 60);
  const s = seconds % 60;
  return `${h}h ${String(m).padStart(2, "0")}m ${String(s).padStart(2, "0")}s left`;
};

const isOwn = (p: Payment) => p.status === "prepared-by-you";

// Maya's approval releases the payment only if it is the final approval needed.
const completesApproval = (p: Payment) =>
  p.approvalsRequired - p.approvalsReceived <= 1;

const flagStatus = (flag: string): "warning" | "error" | "info" => {
  if (flag === "possible-duplicate" || flag === "bank-details-changed") return "error";
  if (flag === "four-eyes-required" || flag === "own-payment") return "info";
  return "warning";
};

export default function UrgentApprovalsReview() {
  const queue = useMemo(
    () =>
      [...payments].sort((a, b) => {
        const ca = cutOffs.find((c) => c.currency === a.currency)?.minutesRemaining ?? 0;
        const cb = cutOffs.find((c) => c.currency === b.currency)?.minutesRemaining ?? 0;
        if (ca !== cb) return ca - cb;
        return b.amount - a.amount;
      }),
    []
  );

  const [index, setIndex] = useState(0);
  const [decisions, setDecisions] = useState<Record<string, Decision>>({});
  const [checked, setChecked] = useState<Record<string, boolean>>({});
  const [released, setReleased] = useState<string[]>([]);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [lastReleaseCount, setLastReleaseCount] = useState(0);
  const [elapsed, setElapsed] = useState(0);

  useEffect(() => {
    const id = setInterval(() => setElapsed((e) => e + 1), 1000);
    return () => clearInterval(id);
  }, []);

  const atSummary = index >= queue.length;
  const current = atSummary ? undefined : queue[index];

  const reviewedCount = queue.filter((p) => decisions[p.id] && decisions[p.id] !== "skipped").length;

  const readyToRelease = queue.filter(
    (p) => decisions[p.id] === "approved" && completesApproval(p) && !released.includes(p.id)
  );
  const awaitingOther = queue.filter(
    (p) => decisions[p.id] === "approved" && !completesApproval(p)
  );

  const readyTotals = currencyOrder
    .map((cur) => {
      const items = readyToRelease.filter((p) => p.currency === cur);
      return {
        currency: cur,
        count: items.length,
        total: items.reduce((s, p) => s + p.amount, 0),
      };
    })
    .filter((t) => t.count > 0);

  const decide = (p: Payment, d: Decision) => {
    setDecisions((prev) => ({ ...prev, [p.id]: d }));
    setIndex((i) => i + 1);
  };

  const undo = (id: string) => {
    setDecisions((prev) => {
      const next = { ...prev };
      delete next[id];
      return next;
    });
  };

  const goTo = (id: string) => {
    const i = queue.findIndex((p) => p.id === id);
    if (i >= 0) setIndex(i);
  };

  const releaseNow = () => {
    setLastReleaseCount(readyToRelease.length);
    setReleased((prev) => [...prev, ...readyToRelease.map((p) => p.id)]);
    setDialogOpen(false);
  };

  const decisionLabel = (p: Payment): string => {
    const d = decisions[p.id];
    if (released.includes(p.id)) return "Released";
    if (d === "approved") return completesApproval(p) ? "Approved, ready to release" : "Approved, awaiting second approver";
    if (d === "held") return "On hold";
    if (d === "skipped") return "Skipped";
    return "Not reviewed";
  };

  const decisionStatus = (p: Payment): "success" | "warning" | "info" => {
    const d = decisions[p.id];
    if (released.includes(p.id) || d === "approved") return "success";
    if (d === "held") return "warning";
    return "info";
  };

  const renderCard = (p: Payment) => {
    const cutOff = cutOffs.find((c) => c.currency === p.currency);
    const own = isOwn(p);
    const accountChecked = !!checked[p.id];
    const decided = decisions[p.id];
    const isReleased = released.includes(p.id);
    const duplicate = p.duplicateOf ? queue.find((q) => q.id === p.duplicateOf) : undefined;
    const approveLabel = completesApproval(p)
      ? "Approve"
      : `Approve (1 of ${p.approvalsRequired})`;

    return (
      <Card accent="top" aria-labelledby={`title-${p.id}`}>
        <StackLayout gap={2}>
          <FlexLayout justify="space-between" align="center" wrap gap={1}>
            <Text styleAs="label" color="secondary">
              {p.reference} · {p.type}
            </Text>
            <FlexLayout gap={1} align="center">
              <StatusIndicator
                aria-hidden
                status={cutOff?.urgency === "critical" ? "warning" : "info"}
              />
              <Text styleAs="label">
                {cutOff?.label} {cutOff?.time} {cutOff?.zone}
              </Text>
            </FlexLayout>
          </FlexLayout>

          <StackLayout gap={0.5}>
            <H2 id={`title-${p.id}`} styleAs="h3">
              {p.beneficiary}
            </H2>
            <Display3>{p.amountFormatted}</Display3>
            {p.currency !== "USD" && (
              <Text color="secondary">≈ {p.usdEquivalentFormatted}</Text>
            )}
          </StackLayout>

          {decided && (
            <FlexLayout gap={1} align="center">
              <StatusIndicator aria-hidden status={decisionStatus(p)} />
              <Text>{decisionLabel(p)}</Text>
            </FlexLayout>
          )}

          {p.flags.length > 0 && (
            <StackLayout gap={1}>
              {p.flags.map((flag) => (
                <Banner key={flag} status={flagStatus(flag)}>
                  <BannerContent>
                    <StackLayout gap={0.5}>
                      <Text>
                        <strong>{flagLabels[flag]}</strong>
                      </Text>
                      {flag === p.flags[0] && p.note && <Text>{p.note}</Text>}
                      {flag === "four-eyes-required" && (
                        <Text>
                          Payments over {fourEyesThreshold} need two approvers.{" "}
                          {p.firstApprover
                            ? `${p.firstApprover} has approved.`
                            : "No approvals yet."}
                        </Text>
                      )}
                    </StackLayout>
                  </BannerContent>
                </Banner>
              ))}
              {duplicate && (
                <Button
                  appearance="bordered"
                  sentiment="neutral"
                  onClick={() => goTo(duplicate.id)}
                >
                  Compare with {duplicate.reference}
                </Button>
              )}
            </StackLayout>
          )}
          {p.flags.length === 0 && p.note && <Text color="secondary">{p.note}</Text>}

          <Divider />

          <StackLayout gap={1}>
            <H3 styleAs="h4">Beneficiary account</H3>
            <StackLayout gap={0.5}>
              <Label color="secondary">Account</Label>
              <Text>{p.accountMasked}</Text>
            </StackLayout>
            <StackLayout gap={0.5}>
              <Label color="secondary">Bank</Label>
              <Text>
                {p.bankName}, {p.country}
              </Text>
            </StackLayout>
            <FormField>
              <FormFieldLabel>Account check</FormFieldLabel>
              <Checkbox
                label={`I've checked the beneficiary account ••••${last4(p.accountMasked)}`}
                checked={accountChecked}
                disabled={own || isReleased}
                onChange={(e) =>
                  setChecked((prev) => ({ ...prev, [p.id]: e.target.checked }))
                }
              />
            </FormField>
          </StackLayout>

          <Divider />

          <StackLayout gap={1}>
            <H3 styleAs="h4">Payment details</H3>
            <FlexLayout gap={2} wrap>
              <StackLayout gap={0.5}>
                <Label color="secondary">Debit account</Label>
                <Text>••••{last4(p.debitAccountMasked)}</Text>
              </StackLayout>
              <StackLayout gap={0.5}>
                <Label color="secondary">Value date</Label>
                <Text>{p.valueDate}</Text>
              </StackLayout>
              <StackLayout gap={0.5}>
                <Label color="secondary">Prepared by</Label>
                <Text>
                  {p.preparedBy}, {p.preparedAt.split(", ")[1]} London
                </Text>
              </StackLayout>
              <StackLayout gap={0.5}>
                <Label color="secondary">Approvals</Label>
                <Text>
                  {p.approvalsReceived} of {p.approvalsRequired}
                </Text>
              </StackLayout>
            </FlexLayout>
          </StackLayout>

          <Divider />

          {own && (
            <Text color="secondary">
              You can't approve a payment you prepared. Skip it so another approver can release it.
            </Text>
          )}
          {!own && !accountChecked && !isReleased && (
            <Text color="secondary">Check the beneficiary account to enable approval.</Text>
          )}

          {isReleased ? (
            <Text>This payment has been released.</Text>
          ) : decided ? (
            <FlexLayout gap={1} wrap>
              <Button appearance="bordered" sentiment="neutral" onClick={() => undo(p.id)}>
                Undo decision
              </Button>
              <Button sentiment="accented" onClick={() => setIndex((i) => i + 1)}>
                Next payment
              </Button>
            </FlexLayout>
          ) : (
            <StackLayout gap={1}>
              <Button
                sentiment="accented"
                disabled={own || !accountChecked}
                onClick={() => decide(p, "approved")}
              >
                {approveLabel}
              </Button>
              <FlexLayout gap={1}>
                <Button
                  appearance="bordered"
                  sentiment="neutral"
                  disabled={own}
                  style={{ flex: 1 }}
                  onClick={() => decide(p, "held")}
                >
                  Hold
                </Button>
                <Button
                  appearance="transparent"
                  sentiment="neutral"
                  style={{ flex: 1 }}
                  onClick={() => decide(p, "skipped")}
                >
                  Skip
                </Button>
              </FlexLayout>
            </StackLayout>
          )}
        </StackLayout>
      </Card>
    );
  };

  const renderSummary = () => (
    <Card accent="top">
      <StackLayout gap={2}>
        <H2 styleAs="h3">Review complete</H2>
        <Text>
          You've been through all {queue.length} payments. Return to anything you skipped or held
          before cut-off.
        </Text>
        <StackLayout gap={1}>
          {queue.map((p) => (
            <FlexLayout key={p.id} justify="space-between" align="center" gap={1} wrap>
              <StackLayout gap={0}>
                <Text>{p.beneficiary}</Text>
                <Text styleAs="label" color="secondary">
                  {p.amountFormatted}
                </Text>
              </StackLayout>
              <FlexLayout gap={1} align="center">
                <StatusIndicator aria-hidden status={decisionStatus(p)} />
                <Text styleAs="label">{decisionLabel(p)}</Text>
                <Button
                  appearance="transparent"
                  sentiment="neutral"
                  onClick={() => goTo(p.id)}
                  aria-label={`Open ${p.beneficiary} ${p.reference}`}
                >
                  Open
                </Button>
              </FlexLayout>
            </FlexLayout>
          ))}
        </StackLayout>
        <Button appearance="bordered" sentiment="neutral" onClick={() => setIndex(0)}>
          Back to first payment
        </Button>
      </StackLayout>
    </Card>
  );

  return (
    <FlexLayout justify="center">
      <StackLayout
        gap={2}
        style={{ flex: 1, maxWidth: "calc(var(--salt-size-base) * 20)" }}
      >
        <StackLayout gap={0.5}>
          <H1>Urgent approvals</H1>
          <Text color="secondary">
            {approver.name} · {asOf.date}, as of {asOf.time} London
          </Text>
        </StackLayout>

        {lastReleaseCount > 0 && (
          <Banner status="success">
            <BannerContent>
              {lastReleaseCount} payment{lastReleaseCount === 1 ? "" : "s"} released to the bank.
            </BannerContent>
          </Banner>
        )}

        <StackLayout gap={1}>
          <FlexLayout justify="space-between" align="center">
            <Button
              appearance="transparent"
              sentiment="neutral"
              aria-label="Previous payment"
              disabled={index === 0}
              onClick={() => setIndex((i) => Math.max(0, i - 1))}
            >
              <ChevronLeftIcon aria-hidden />
            </Button>
            <Text aria-live="polite">
              {atSummary ? "Summary" : `Payment ${index + 1} of ${queue.length}`} ·{" "}
              {reviewedCount} reviewed
            </Text>
            <Button
              appearance="transparent"
              sentiment="neutral"
              aria-label="Next payment"
              disabled={atSummary}
              onClick={() => setIndex((i) => Math.min(queue.length, i + 1))}
            >
              <ChevronRightIcon aria-hidden />
            </Button>
          </FlexLayout>
          <LinearProgress
            aria-label="Review progress"
            value={(reviewedCount / queue.length) * 100}
          />
        </StackLayout>

        {current ? renderCard(current) : renderSummary()}

        <Card
          variant="secondary"
          style={{ position: "sticky", bottom: 0 }}
          aria-label="Batch release"
        >
          <StackLayout gap={1}>
            <FlexLayout gap={2} wrap justify="space-between">
              {cutOffs.map((c) => {
                const secs = c.minutesRemaining * 60 - elapsed;
                return (
                  <StackLayout key={c.currency} gap={0}>
                    <FlexLayout gap={0.5} align="center">
                      <StatusIndicator
                        aria-hidden
                        status={c.urgency === "critical" ? "warning" : "info"}
                      />
                      <Text styleAs="label">
                        {c.currency} · {c.time} {c.zone}
                      </Text>
                    </FlexLayout>
                    <Text styleAs="label" color="secondary">
                      {formatCountdown(secs)}
                    </Text>
                  </StackLayout>
                );
              })}
            </FlexLayout>
            <Divider variant="secondary" />
            <FlexLayout justify="space-between" align="center" gap={1} wrap>
              <StackLayout gap={0}>
                <Text>
                  <strong>{readyToRelease.length} ready to release</strong>
                </Text>
                {readyTotals.length > 0 ? (
                  readyTotals.map((t) => (
                    <Text key={t.currency} styleAs="label" color="secondary">
                      {t.count} × {formatAmount(t.currency, t.total)}
                    </Text>
                  ))
                ) : (
                  <Text styleAs="label" color="secondary">
                    Approve payments to add them to the batch
                  </Text>
                )}
                {awaitingOther.length > 0 && (
                  <Text styleAs="label" color="secondary">
                    {awaitingOther.length} awaiting a second approver
                  </Text>
                )}
              </StackLayout>
              <Button
                sentiment="accented"
                disabled={readyToRelease.length === 0}
                onClick={() => setDialogOpen(true)}
              >
                Release {readyToRelease.length}
              </Button>
            </FlexLayout>
          </StackLayout>
        </Card>

        <Dialog open={dialogOpen} onOpenChange={setDialogOpen}>
          <DialogHeader header={`Release ${readyToRelease.length} payments`} />
          <DialogContent>
            <StackLayout gap={1}>
              <Text>These payments will be sent to the bank now. You can't recall them here.</Text>
              {readyToRelease.map((p) => (
                <FlexLayout key={p.id} justify="space-between" gap={1}>
                  <Text>
                    {p.beneficiary} ••••{last4(p.accountMasked)}
                  </Text>
                  <Text>{p.amountFormatted}</Text>
                </FlexLayout>
              ))}
              <Divider />
              {readyTotals.map((t) => (
                <FlexLayout key={t.currency} justify="space-between">
                  <Text>
                    <strong>{t.currency} total</strong>
                  </Text>
                  <Text>
                    <strong>{formatAmount(t.currency, t.total)}</strong>
                  </Text>
                </FlexLayout>
              ))}
            </StackLayout>
          </DialogContent>
          <DialogActions>
            <Button appearance="bordered" sentiment="neutral" onClick={() => setDialogOpen(false)}>
              Cancel
            </Button>
            <Button sentiment="accented" onClick={releaseNow}>
              Release payments
            </Button>
          </DialogActions>
        </Dialog>
      </StackLayout>
    </FlexLayout>
  );
}

