  Text,
} from "@salt-ds/core";
import { ChevronDownIcon, ChevronUpIcon, CloseIcon } from "@salt-ds/icons";
import {
  approver,
  asOf,
  cutOffs,
  flagLabels,
  fourEyesThreshold,
  payments,
  type CurrencyCode,
  type CutOff,
  type Payment,
  type PaymentFlag,
} from "./data";

type RowState = "pending" | "checked" | "released" | "first-approved" | "rejected";
type StatusKind = "error" | "warning" | "info" | "success";

const flagStatus: Record<PaymentFlag, StatusKind> = {
  "possible-duplicate": "error",
  "bank-details-changed": "error",
  "above-usual-amount": "warning",
  "new-beneficiary": "warning",
  "four-eyes-required": "info",
  "own-payment": "info",
};

const urgencyStatus: Record<CutOff["urgency"], StatusKind> = {
  critical: "error",
  warning: "warning",
  normal: "info",
};

const formatAmount = (currency: CurrencyCode, n: number) =>
  `${currency} ${n.toLocaleString("en-GB", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;

const formatCountdown = (secs: number) => {
  if (secs <= 0) return "Cut-off passed";
  const h = Math.floor(secs / 3600);
  const m = Math.floor((secs % 3600) / 60);
  const s = secs % 60;
  return `${h}h ${String(m).padStart(2, "0")}m ${String(s).padStart(2, "0")}s left`;
};

const formatShortCountdown = (secs: number) => {
  if (secs <= 0) return "Cut-off passed";
  const h = Math.floor(secs / 3600);
  const m = Math.floor((secs % 3600) / 60);
  return `${h}h ${String(m).padStart(2, "0")}m left`;
};

const isFlagged = (p: Payment) => p.flags.length > 0;
const isOwn = (p: Payment) => p.flags.includes("own-payment");
const isDone = (s: RowState) => s === "released" || s === "first-approved" || s === "rejected";

const doneLabel: Record<string, string> = {
  released: "Released",
  "first-approved": "Approved, awaiting second approver",
  rejected: "Rejected",
};

function Status({ status, children }: { status: StatusKind; children: ReactNode }) {
  return (
    <FlexLayout gap={0.75} align="center" wrap={false}>
      <StatusIndicator status={status} aria-hidden />
      <Text styleAs="label">{children}</Text>
    </FlexLayout>
  );
}

export default function UrgentPaymentApprovals() {
  const [elapsed, setElapsed] = useState(0);
  const [rowState, setRowState] = useState<Record<string, RowState>>(() =>
    Object.fromEntries(payments.map((p) => [p.id, "pending" as RowState])),
  );
  const [selected, setSelected] = useState<Set<string>>(new Set());
  const [expanded, setExpanded] = useState<Set<string>>(new Set());
  const [reviewId, setReviewId] = useState<string | null>(null);
  const [confirmIds, setConfirmIds] = useState<string[] | null>(null);
  const [message, setMessage] = useState<string | null>(null);

  useEffect(() => {
    const t = setInterval(() => setElapsed((e) => e + 1), 1000);
    return () => clearInterval(t);
  }, []);

  const groups = useMemo(
    () =>
      [...cutOffs]
        .sort((a, b) => a.minutesRemaining - b.minutesRemaining)
        .map((c) => ({ cutOff: c, items: payments.filter((p) => p.currency === c.currency) })),
    [],
  );

  const canSelect = (p: Payment) => {
    const s = rowState[p.id];
    if (isDone(s) || isOwn(p)) return false;
    return !isFlagged(p) || s === "checked";
  };

  const toggle = (id: string) =>
    setSelected((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });

  const toggleExpanded = (id: string) =>
    setExpanded((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });

  const selectAllReady = (items: Payment[]) =>
    setSelected((prev) => {
      const next = new Set(prev);
      items.filter(canSelect).forEach((p) => next.add(p.id));
      return next;
    });

  const markChecked = (id: string) => {
    setRowState((s) => ({ ...s, [id]: "checked" }));
    setSelected((prev) => new Set(prev).add(id));
    setReviewId(null);
  };

  const reject = (id: string) => {
    const p = payments.find((x) => x.id === id);
    setRowState((s) => ({ ...s, [id]: "rejected" }));
    setSelected((prev) => {
      const next = new Set(prev);
      next.delete(id);
      return next;
    });
    setReviewId(null);
    if (p) setMessage(`${p.reference} to ${p.beneficiary} rejected and returned to ${p.preparedBy}.`);
  };

  const release = (ids: string[]) => {
    const updates: Record<string, RowState> = {};
    let released = 0;
    let first = 0;
    ids.forEach((id) => {
      const p = payments.find((x) => x.id === id);
      if (!p) return;
      if (p.approvalsRequired === 2 && p.approvalsReceived === 0) {
        updates[id] = "first-approved";
        first += 1;
      } else {
        updates[id] = "released";
        released += 1;
      }
    });
    setRowState((s) => ({ ...s, ...updates }));
    setSelected((prev) => {
      const next = new Set(prev);
      ids.forEach((id) => next.delete(id));
      return next;
    });
    setConfirmIds(null);
    setReviewId(null);
    const parts: string[] = [];
    if (released) parts.push(`${released} payment${released > 1 ? "s" : ""} released`);
    if (first) parts.push(`${first} approved and sent for a second approval`);
    setMessage(`${parts.join("; ")} at ${asOf.time} London.`);
  };

  const reviewPayment = payments.find((p) => p.id === reviewId) ?? null;
  const confirmPayments = (confirmIds ?? [])
    .map((id) => payments.find((p) => p.id === id))
    .filter((p): p is Payment => Boolean(p));

  const totalOutstanding = payments.filter((p) => !isDone(rowState[p.id])).length;
  const toCheck = payments.filter(
    (p) => isFlagged(p) && !isOwn(p) && rowState[p.id] === "pending",
  ).length;

  const needsCheck = (p: Payment) => isFlagged(p) && !isOwn(p) && rowState[p.id] === "pending";

  const rowStatus = (p: Payment): { status: StatusKind; label: string } => {
    const s = rowState[p.id];
    if (isDone(s)) return { status: s === "rejected" ? "error" : "success", label: doneLabel[s] };
    if (isOwn(p)) return { status: "info", label: "Prepared by you: can't release" };
    if (needsCheck(p)) {
      const primary = p.flags.find((f) => flagStatus[f] === "error") ?? p.flags[0];
      const more = p.flags.length > 1 ? ` +${p.flags.length - 1}` : "";
      return { status: flagStatus[primary], label: `Check: ${flagLabels[primary]}${more}` };
    }
    if (s === "checked") return { status: "success", label: "Checked by you" };
    if (p.approvalsRequired === 2 && p.approvalsReceived === 1)
      return { status: "success", label: "Ready: final approval" };
    return { status: "success", label: "Ready to release" };
  };

  const detailFields = (p: Payment): [string, string][] => [
    ["Beneficiary account", p.accountMasked],
    ["Beneficiary bank", `${p.bankName}, ${p.country}`],
    ["Reference", p.reference],
    ["Type", p.type],
    ["Debit account", p.debitAccountMasked],
    ["USD equivalent", p.usdEquivalentFormatted],
    ["Value date", p.valueDate],
    ["Prepared by", `${p.preparedBy}, ${p.preparedAt} London`],
    [
      "Approvals",
      `${p.approvalsReceived} of ${p.approvalsRequired}${p.firstApprover ? ` (${p.firstApprover})` : ""}`,
    ],
  ];

  const renderRow = (p: Payment, cutOff: CutOff, secs: number) => {
    const s = rowState[p.id];
    const open = expanded.has(p.id);
    const st = rowStatus(p);
    const detailsId = `details-${p.id}`;
    return [
      <TR key={p.id}>
        <TD>
          <Checkbox
            checked={selected.has(p.id)}
            disabled={!canSelect(p)}
            onChange={() => toggle(p.id)}
            inputProps={{ "aria-label": `Select ${p.beneficiary}, ${p.amountFormatted}` }}
          />
        </TD>
        <TD>
          <Text>{p.beneficiary}</Text>
        </TD>
        <TD style={{ textAlign: "right" }}>
          <Text>{p.amountFormatted}</Text>
        </TD>
        <TD>
          <StackLayout gap={0}>
            <Text>
              {cutOff.time} {cutOff.zone}
            </Text>
            {!isDone(s) && (
              <Text color="secondary" styleAs="label">
                {formatShortCountdown(secs)}
              </Text>
            )}
          </StackLayout>
        </TD>
        <TD>
          <Status status={st.status}>{st.label}</Status>
        </TD>
        <TD>
          <Button
            appearance="transparent"
            aria-label={`${open ? "Hide" : "Show"} details for ${p.beneficiary}, ${p.amountFormatted}`}
            aria-expanded={open}
            aria-controls={open ? detailsId : undefined}
            onClick={() => toggleExpanded(p.id)}
          >
            {open ? <ChevronUpIcon aria-hidden /> : <ChevronDownIcon aria-hidden />}
          </Button>
        </TD>
      </TR>,
      open ? (
        <TR key={`${p.id}-details`} id={detailsId}>
          <TD colSpan={6}>
            <StackLayout gap={1.5} padding={1}>
              {p.flags.length > 0 && (
                <StackLayout gap={0.5}>
                  {p.flags.map((f) => (
                    <Status key={f} status={flagStatus[f]}>
                      {flagLabels[f]}
                    </Status>
                  ))}
                </StackLayout>
              )}
              {p.note && <Text>{p.note}</Text>}
              <GridLayout columns={{ xs: 1, sm: 2, md: 3 }} gap={1}>
                {detailFields(p).map(([k, v]) => (
                  <GridItem key={k}>
                    <StackLayout gap={0}>
                      <Text styleAs="label" color="secondary">
                        {k}
                      </Text>
                      <Text>{v}</Text>
                    </StackLayout>
                  </GridItem>
                ))}
              </GridLayout>
              <FlexLayout gap={1}>
                <Button
                  appearance={needsCheck(p) ? "solid" : "bordered"}
                  sentiment={needsCheck(p) ? "accented" : "neutral"}
                  onClick={() => setReviewId(p.id)}
                  aria-label={`${needsCheck(p) ? "Check" : "View"} ${p.reference} to ${p.beneficiary}`}
                >
                  {needsCheck(p) ? "Check" : "View"}
                </Button>
              </FlexLayout>
            </StackLayout>
          </TD>
        </TR>
      ) : null,
    ];
  };

  const sectionRow = (key: string, label: string) => (
    <TR key={key}>
      <TD colSpan={6}>
        <Text styleAs="label" color="secondary">
          {label}
        </Text>
      </TD>
    </TR>
  );

  return (
    <StackLayout gap={3}>
      <StackLayout gap={1}>
        <H1>Approvals</H1>
        <Text color="secondary">
          Urgent payments for {asOf.date}, ordered by cut-off. In each currency, flagged payments are pinned
          to the top so you check them first. Payments over {fourEyesThreshold} need four-eyes approval.
        </Text>
        <Text>
          {totalOutstanding} payments outstanding · {toCheck} to check · Signed in as {approver.name}
        </Text>
      </StackLayout>

      {message && (
        <Banner status="success">
          <BannerContent>{message}</BannerContent>
          <BannerActions>
            <Button aria-label="Dismiss message" appearance="transparent" onClick={() => setMessage(null)}>
              <CloseIcon aria-hidden />
            </Button>
          </BannerActions>
        </Banner>
      )}

      <GridLayout columns={{ xs: 1, md: 3 }} gap={2}>
        {groups.map(({ cutOff, items }) => {
          const secs = cutOff.minutesRemaining * 60 - elapsed;
          const open = items.filter((p) => !isDone(rowState[p.id]));
          const flaggedOpen = open.filter(needsCheck);
          return (
            <GridItem key={cutOff.currency}>
              <Card>
                <StackLayout gap={1}>
                  <Text styleAs="label" color="secondary">
                    {cutOff.label} · {cutOff.time} {cutOff.zone}
                    {cutOff.zone !== "London" ? ` (${cutOff.londonEquivalent})` : ""}
                  </Text>
                  <Display3>{formatCountdown(secs)}</Display3>
                  <Status status={urgencyStatus[cutOff.urgency]}>
                    {cutOff.urgency === "critical"
                      ? "Closes soonest: release first"
                      : cutOff.urgency === "warning"
                        ? "Closing soon"
                        : "Time available"}
                  </Status>
                  <Text>
                    {open.length} to release · {flaggedOpen.length} to check
                  </Text>
                </StackLayout>
              </Card>
            </GridItem>
          );
        })}
      </GridLayout>

      {groups.map(({ cutOff, items }) => {
        const secs = cutOff.minutesRemaining * 60 - elapsed;
        const flagged = items.filter((p) => isFlagged(p) && !isDone(rowState[p.id]));
        const clean = items.filter((p) => !isFlagged(p) && !isDone(rowState[p.id]));
        const done = items.filter((p) => isDone(rowState[p.id]));
        const groupSelected = items.filter((p) => selected.has(p.id));
        const selTotal = groupSelected.reduce((sum, p) => sum + p.amount, 0);
        return (
          <StackLayout key={cutOff.currency} gap={1}>
            <FlexLayout justify="space-between" align="center" wrap gap={1}>
              <StackLayout gap={0.5}>
                <H2>
                  {cutOff.currency} payments · cut-off {cutOff.time} {cutOff.zone}
                </H2>
                <Status status={urgencyStatus[cutOff.urgency]}>{formatCountdown(secs)}</Status>
              </StackLayout>
              <FlexLayout gap={1} wrap>
                <Button appearance="bordered" onClick={() => selectAllReady(items)}>
                  Select all ready
                </Button>
                <Button
                  sentiment="accented"
                  disabled={groupSelected.length === 0}
                  onClick={() => setConfirmIds(groupSelected.map((p) => p.id))}
                >
                  {groupSelected.length === 0
                    ? `Release ${cutOff.currency}`
                    : `Release ${groupSelected.length} · ${formatAmount(cutOff.currency, selTotal)}`}
                </Button>
              </FlexLayout>
            </FlexLayout>
            <TableContainer>
              <Table>
                <caption>
                  {cutOff.currency} payments due before {cutOff.time} {cutOff.zone}. Flagged payments are listed
                  first. Open a row's details for account, reference and preparer.
                </caption>
                <THead>
                  <TR>
                    <TH>Select</TH>
                    <TH>Payee</TH>
                    <TH style={{ textAlign: "right" }}>Amount</TH>
                    <TH>Cut-off</TH>
                    <TH>Status</TH>
                    <TH>Details</TH>
                  </TR>
                </THead>
                <TBody>
                  {flagged.length > 0 &&
                    sectionRow(`${cutOff.currency}-f`, `Check first · ${flagged.length} flagged`)}
                  {flagged.map((p) => renderRow(p, cutOff, secs))}
                  {clean.length > 0 &&
                    sectionRow(`${cutOff.currency}-c`, `Ready to release · ${clean.length} with no issues`)}
                  {clean.map((p) => renderRow(p, cutOff, secs))}
                  {done.length > 0 && sectionRow(`${cutOff.currency}-d`, `Done · ${done.length}`)}
                  {done.map((p) => renderRow(p, cutOff, secs))}
                </TBody>
              </Table>
            </TableContainer>
          </StackLayout>
        );
      })}

      <Dialog open={reviewPayment !== null} onOpenChange={(o) => !o && setReviewId(null)} size="medium">
        {reviewPayment && (
          <>
            <DialogHeader header={`${reviewPayment.beneficiary} · ${reviewPayment.amountFormatted}`} />
            <DialogContent>
              <StackLayout gap={2}>
                {reviewPayment.flags.length > 0 && (
                  <StackLayout gap={0.5}>
                    {reviewPayment.flags.map((f) => (
                      <Status key={f} status={flagStatus[f]}>
                        {flagLabels[f]}
                      </Status>
                    ))}
                  </StackLayout>
                )}
                {reviewPayment.note && <Text>{reviewPayment.note}</Text>}
                <H3>Payment details</H3>
                <GridLayout columns={2} gap={1}>
                  {[
                    ["Reference", reviewPayment.reference],
                    ["Beneficiary account", reviewPayment.accountMasked],
                    ["Beneficiary bank", `${reviewPayment.bankName}, ${reviewPayment.country}`],
                    ["Debit account", reviewPayment.debitAccountMasked],
                    ["Amount", reviewPayment.amountFormatted],
                    ["USD equivalent", reviewPayment.usdEquivalentFormatted],
                    ["Value date", reviewPayment.valueDate],
                    ["Type", reviewPayment.type],
                    ["Prepared by", `${reviewPayment.preparedBy}, ${reviewPayment.preparedAt} London`],
                    [
                      "Approvals",
                      `${reviewPayment.approvalsReceived} of ${reviewPayment.approvalsRequired}${
                        reviewPayment.firstApprover ? ` (${reviewPayment.firstApprover})` : ""
                      }`,
                    ],
                  ].map(([k, v]) => (
                    <GridItem key={k}>
                      <StackLayout gap={0}>
                        <Text styleAs="label" color="secondary">
                          {k}
                        </Text>
                        <Text>{v}</Text>
                      </StackLayout>
                    </GridItem>
                  ))}
                </GridLayout>
                {reviewPayment.duplicateOf && (
                  <Text color="secondary">
                    Compare with {payments.find((p) => p.id === reviewPayment.duplicateOf)?.reference}, prepared
                    by {payments.find((p) => p.id === reviewPayment.duplicateOf)?.preparedBy}. Reject one if it
                    is a duplicate.
                  </Text>
                )}
              </StackLayout>
            </DialogContent>
            <DialogActions>
              <Button appearance="transparent" onClick={() => setReviewId(null)}>
                Close
              </Button>
              {!isOwn(reviewPayment) && !isDone(rowState[reviewPayment.id]) && (
                <>
                  <Button appearance="bordered" onClick={() => reject(reviewPayment.id)}>
                    Reject
                  </Button>
                  {needsCheck(reviewPayment) ? (
                    <Button sentiment="accented" onClick={() => markChecked(reviewPayment.id)}>
                      Mark as checked
                    </Button>
                  ) : (
                    <Button sentiment="accented" onClick={() => setConfirmIds([reviewPayment.id])}>
                      {reviewPayment.approvalsRequired === 2 && reviewPayment.approvalsReceived === 0
                        ? "Approve"
                        : "Release"}
                    </Button>
                  )}
                </>
              )}
            </DialogActions>
          </>
        )}
      </Dialog>

      <Dialog open={confirmIds !== null} onOpenChange={(o) => !o && setConfirmIds(null)} size="small">
        <DialogHeader header="Release payments" />
        <DialogContent>
          <StackLayout gap={1}>
            {confirmPayments.map((p) => (
              <FlexLayout key={p.id} justify="space-between" gap={1}>
                <Text>
                  {p.beneficiary} ••••{p.accountMasked.slice(-4)}
                </Text>
                <Text>{p.amountFormatted}</Text>
              </FlexLayout>
            ))}
            {confirmPayments.some((p) => p.approvalsRequired === 2 && p.approvalsReceived === 0) && (
              <Status status="info">
                Payments that need four-eyes approval go to a second approver before release.
              </Status>
            )}
          </StackLayout>
        </DialogContent>
        <DialogActions>
          <Button appearance="bordered" onClick={() => setConfirmIds(null)}>
            Cancel
          </Button>
          <Button sentiment="accented" onClick={() => release(confirmIds ?? [])}>
            Confirm release
          </Button>
        </DialogActions>
      </Dialog>
    </StackLayout>
  );
}

