export type CurrencyCode = 'GBP' | 'EUR' | 'USD';

export type PaymentType = 'Supplier' | 'Payroll';

export type PaymentStatus = 'awaiting-approval' | 'awaiting-second-approval' | 'prepared-by-you';

export type PaymentFlag =
  | 'possible-duplicate'
  | 'new-beneficiary'
  | 'bank-details-changed'
  | 'above-usual-amount'
  | 'four-eyes-required'
  | 'own-payment';

export interface Approver {
  readonly id: string;
  readonly name: string;
  readonly role: string;
  readonly organisation: string;
}

export interface CutOff {
  readonly currency: CurrencyCode;
  readonly label: string;
  readonly time: string;
  readonly zone: string;
  readonly londonEquivalent: string;
  readonly minutesRemaining: number;
  readonly remainingLabel: string;
  readonly urgency: 'critical' | 'warning' | 'normal';
}

export interface Payment {
  readonly id: string;
  readonly reference: string;
  readonly beneficiary: string;
  readonly country: string;
  readonly bankName: string;
  readonly accountMasked: string;
  readonly debitAccountMasked: string;
  readonly currency: CurrencyCode;
  readonly amount: number;
  readonly amountFormatted: string;
  readonly usdEquivalentFormatted: string;
  readonly valueDate: string;
  readonly type: PaymentType;
  readonly preparedBy: string;
  readonly preparedAt: string;
  readonly status: PaymentStatus;
  readonly approvalsRequired: 1 | 2;
  readonly approvalsReceived: 0 | 1;
  readonly firstApprover?: string;
  readonly flags: readonly PaymentFlag[];
  readonly duplicateOf?: string;
  readonly note?: string;
}

export interface CurrencyTotal {
  readonly currency: CurrencyCode;
  readonly count: number;
  readonly totalFormatted: string;
}

export const approver: Approver = {
  id: 'per_1wc1e5d5uygyg22q',
  name: 'Maya Lindqvist',
  role: 'Treasury payments approver',
  organisation: 'Corporate treasury, Halvorsen Industrial Ltd',
};

export const asOf = {
  date: '16 Oct 2026',
  time: '13:47',
  zone: 'Europe/London',
} as const;

export const fourEyesThreshold = 'USD 1,000,000.00';

export const cutOffs: readonly CutOff[] = [
  { currency: 'GBP', label: 'GBP cut-off', time: '15:00', zone: 'London', londonEquivalent: '15:00 London', minutesRemaining: 73, remainingLabel: '1h 13m left', urgency: 'critical' },
  { currency: 'EUR', label: 'EUR cut-off', time: '15:00', zone: 'London', londonEquivalent: '15:00 London', minutesRemaining: 73, remainingLabel: '1h 13m left', urgency: 'critical' },
  { currency: 'USD', label: 'USD cut-off', time: '14:00', zone: 'New York', londonEquivalent: '19:00 London', minutesRemaining: 313, remainingLabel: '5h 13m left', urgency: 'normal' },
];

export const payments: readonly Payment[] = [
  {
    id: 'p1', reference: 'PAY-261016-0412', beneficiary: 'Hartwell Components Ltd', country: 'United Kingdom', bankName: 'Northern Counties Bank',
    accountMasked: 'GB** **** **** **** **** 4821', debitAccountMasked: 'GB** **** **** **** **** 0097',
    currency: 'GBP', amount: 48250, amountFormatted: 'GBP 48,250.00', usdEquivalentFormatted: 'USD 62,725.00', valueDate: '16 Oct 2026',
    type: 'Supplier', preparedBy: 'Tom Ashby', preparedAt: '16 Oct 2026, 09:12', status: 'awaiting-approval', approvalsRequired: 1, approvalsReceived: 0, flags: [],
  },
  {
    id: 'p2', reference: 'PAY-261016-0418', beneficiary: 'Nordvik Stål AB', country: 'Sweden', bankName: 'Svenska Handelsbanken Nord',
    accountMasked: 'SE** **** **** **** **** 7730', debitAccountMasked: 'GB** **** **** **** **** 0105',
    currency: 'EUR', amount: 212400, amountFormatted: 'EUR 212,400.00', usdEquivalentFormatted: 'USD 246,384.00', valueDate: '16 Oct 2026',
    type: 'Supplier', preparedBy: 'Priya Nair', preparedAt: '16 Oct 2026, 09:20', status: 'awaiting-approval', approvalsRequired: 1, approvalsReceived: 0,
    flags: ['possible-duplicate'], duplicateOf: 'p3', note: 'Same beneficiary, amount and value date as PAY-261016-0431.',
  },
  {
    id: 'p3', reference: 'PAY-261016-0431', beneficiary: 'Nordvik Stål AB', country: 'Sweden', bankName: 'Svenska Handelsbanken Nord',
    accountMasked: 'SE** **** **** **** **** 7730', debitAccountMasked: 'GB** **** **** **** **** 0105',
    currency: 'EUR', amount: 212400, amountFormatted: 'EUR 212,400.00', usdEquivalentFormatted: 'USD 246,384.00', valueDate: '16 Oct 2026',
    type: 'Supplier', preparedBy: 'Tom Ashby', preparedAt: '16 Oct 2026, 10:41', status: 'awaiting-approval', approvalsRequired: 1, approvalsReceived: 0,
    flags: ['possible-duplicate'], duplicateOf: 'p2', note: 'Same beneficiary, amount and value date as PAY-261016-0418.',
