import { type ReactElement, type SyntheticEvent, Fragment, useMemo, useState } from "react";
import {
  Button,
  FlexLayout,
  FormField,
  FormFieldLabel,
  H2,
  StackLayout,
  StatusIndicator,
  Table,
  TableContainer,
  TBody,
  TD,
  TH,
  THead,
  Text,
  ToggleButton,
  ToggleButtonGroup,
  TR,
} from "@salt-ds/core";
import {
  onboardingCases,
  ownerOrder,
  snapshot,
  type ActionOwner,
  type ItemStatus,
  type MissingItem,
  type OnboardingCase,
} from "./data";

type Status = "error" | "warning" | "info" | "success";

interface Row {
  item: MissingItem;
  kase: OnboardingCase;
}

const MONTHS: Record<string, number> = {
  Jan: 0, Feb: 1, Mar: 2, Apr: 3, May: 4, Jun: 5, Jul: 6, Aug: 7, Sep: 8, Oct: 9, Nov: 10, Dec: 11,
};

function toTime(d: string): number {
  const [day, mon, year] = d.split(" ");
  return new Date(Number(year), MONTHS[mon] ?? 0, Number(day)).getTime();
}

function slaInfo(days: number): { status: Status; text: string } {
  if (days < 0) return { status: "error", text: `${Math.abs(days)} ${Math.abs(days) === 1 ? "day" : "days"} over SLA` };
  if (days === 0) return { status: "error", text: "Due today" };
  if (days <= 2) return { status: "warning", text: `${days} ${days === 1 ? "day" : "days"} left` };
  return { status: "info", text: `${days} days left` };
}

function itemStatusIndicator(s: ItemStatus): Status {
  switch (s) {
    case "Overdue":
      return "error";
    case "Not requested":
      return "warning";
    case "Requested":
      return "info";
    default:
      return "success";
  }
}

function chaseWho(row: Row): string {
  const { item, kase } = row;
  switch (item.owner) {
    case "Client":
      return item.analystMayContactClient
        ? kase.clientName
        : `Via banker ${kase.relationshipBanker}`;
    case "Relationship banker":
      return kase.relationshipBanker;
    case "Compliance":
      return "Compliance screening team";
    case "Second analyst":
      return "Second analyst queue";
    default:
      return "You (KYC analyst)";
  }
}

const COLS = 7;

export default function OwnerBlockerTable(): ReactElement {
  const [ownerFilter, setOwnerFilter] = useState<string>("All");
  const [expanded, setExpanded] = useState<Set<string>>(new Set());

  const rows: Row[] = useMemo(
    () => onboardingCases.flatMap((kase) => kase.missing.map((item) => ({ item, kase }))),
    [],
  );

  const groups = useMemo(() => {
    return ownerOrder
      .map((owner: ActionOwner) => {
        const list = rows
          .filter((r) => r.item.owner === owner)
          .sort(
            (a, b) =>
              a.kase.daysRemaining - b.kase.daysRemaining ||
              toTime(a.item.dueOn) - toTime(b.item.dueOn),
          );
        return { owner, list };
      })
      .filter((g) => g.list.length > 0);
  }, [rows]);

  const visible = ownerFilter === "All" ? groups : groups.filter((g) => g.owner === ownerFilter);

  const onFilter = (e: SyntheticEvent<HTMLButtonElement>) => {
    setOwnerFilter(e.currentTarget.value);
  };

  const toggle = (id: string) => {
    setExpanded((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  };

  const overSla = rows.filter((r) => r.kase.daysRemaining < 0).length;

  return (
    <StackLayout gap={3}>
      <StackLayout gap={1}>
        <H2>Who needs to act</H2>
        <Text color="secondary">
          {rows.length} missing items across {onboardingCases.length} cases · {overSla} on cases past the{" "}
          {snapshot.slaDays}-day SLA · As of {snapshot.asOf}, cut-off {snapshot.cutOff}
        </Text>
      </StackLayout>

      <FormField>
        <FormFieldLabel>Show owner</FormFieldLabel>
        <ToggleButtonGroup onChange={onFilter} value={ownerFilter}>
          <ToggleButton value="All">All ({rows.length})</ToggleButton>
          {groups.map((g) => (
            <ToggleButton key={g.owner} value={g.owner}>
              {g.owner} ({g.list.length})
            </ToggleButton>
          ))}
        </ToggleButtonGroup>
      </FormField>

      <TableContainer>
        <Table>
          <caption>
            <Text styleAs="label" color="secondary">
              Missing items grouped by the party who must act, sorted by case SLA days left
            </Text>
          </caption>
          <THead>
            <TR>
              <TH>Missing item</TH>
              <TH>Chase</TH>
              <TH>Case</TH>
              <TH>Case SLA</TH>
              <TH>Item due</TH>
              <TH>Request status</TH>
              <TH>
                <Text styleAs="label">Details</Text>
              </TH>
            </TR>
          </THead>
          {visible.map((g) => {
            const worst = g.list[0].kase.daysRemaining;
            const worstSla = slaInfo(worst);
            return (
              <TBody key={g.owner}>
                <TR>
                  <TH colSpan={COLS} scope="rowgroup">
                    <FlexLayout gap={2} align="center" wrap>
                      <Text styleAs="h4">{g.owner}</Text>
                      <Text color="secondary">
                        {g.list.length} {g.list.length === 1 ? "item" : "items"}
                      </Text>
                      <FlexLayout gap={0.75} align="center">
                        <StatusIndicator status={worstSla.status} aria-hidden />
                        <Text color="secondary">Most urgent: {worstSla.text}</Text>
                      </FlexLayout>
                    </FlexLayout>
                  </TH>
                </TR>
                {g.list.map((row) => {
                  const { item, kase } = row;
                  const sla = slaInfo(kase.daysRemaining);
                  const isOpen = expanded.has(item.id);
                  const detailId = `${item.id}-detail`;
                  return (
                    <Fragment key={item.id}>
                      <TR>
                        <TD>
                          <Text>{item.label}</Text>
                        </TD>
                        <TD>
                          <StackLayout gap={0}>
                            <Text>{chaseWho(row)}</Text>
                            {!item.analystMayContactClient && item.owner !== "KYC analyst" && (
                              <Text styleAs="label" color="secondary">
                                Do not contact client directly
                              </Text>
                            )}
                          </StackLayout>
                        </TD>
                        <TD>
                          <StackLayout gap={0}>
                            <Text>{kase.clientName}</Text>
                            <Text styleAs="label" color="secondary">
                              {kase.id} · {kase.risk} risk
                            </Text>
                          </StackLayout>
                        </TD>
                        <TD>
                          <FlexLayout gap={0.75} align="center">
                            <StatusIndicator status={sla.status} aria-hidden />
                            <Text>{sla.text}</Text>
                          </FlexLayout>
                          <Text styleAs="label" color="secondary">
                            SLA {kase.slaDueOn}
                          </Text>
                        </TD>
                        <TD>
                          <Text>{item.dueOn}</Text>
                        </TD>
                        <TD>
                          <FlexLayout gap={0.75} align="center">
                            <StatusIndicator status={itemStatusIndicator(item.status)} aria-hidden />
                            <Text>{item.status}</Text>
                          </FlexLayout>
                        </TD>
                        <TD>
                          <Button
                            appearance="transparent"
                            aria-expanded={isOpen}
                            aria-controls={isOpen ? detailId : undefined}
                            aria-label={`${isOpen ? "Hide" : "Show"} details for ${item.label}, ${kase.clientName}`}
                            onClick={() => toggle(item.id)}
                          >
                            {isOpen ? "Hide" : "Show"}
                          </Button>
                        </TD>
                      </TR>
                      {isOpen && (
                        <TR id={detailId}>
                          <TD colSpan={COLS}>
                            <FlexLayout gap={3} wrap padding={1}>
                              <StackLayout gap={0}>
                                <Text styleAs="label" color="secondary">Note</Text>
                                <Text>{item.note}</Text>
                              </StackLayout>
                              <StackLayout gap={0}>
                                <Text styleAs="label" color="secondary">Requested on</Text>
                                <Text>{item.requestedOn ?? "Not yet requested"}</Text>
                              </StackLayout>
                              <StackLayout gap={0}>
                                <Text styleAs="label" color="secondary">Evidence</Text>
                                <Text>{item.evidenceRef ?? "None recorded"}</Text>
                              </StackLayout>
                              <StackLayout gap={0}>
                                <Text styleAs="label" color="secondary">Relationship banker</Text>
                                <Text>{kase.relationshipBanker}</Text>
                              </StackLayout>
                              <StackLayout gap={0}>
                                <Text styleAs="label" color="secondary">Proposed</Text>
                                <Text>{kase.proposedFacility}</Text>
                              </StackLayout>
                              <StackLayout gap={0}>
                                <Text styleAs="label" color="secondary">Case opened</Text>
                                <Text>
                                  {kase.openedOn} · {kase.daysOpen} days open · {kase.jurisdiction}
                                </Text>
                              </StackLayout>
                            </FlexLayout>
                          </TD>
                        </TR>
                      )}
                    </Fragment>
                  );
                })}
              </TBody>
            );
          })}
        </Table>
      </TableContainer>
    </StackLayout>
  );
}

