export type ActionOwner = 'Client' | 'Relationship banker' | 'Compliance' | 'Second analyst' | 'KYC analyst';
export type RiskRating = 'Low' | 'Medium' | 'High';
export type ItemStatus = 'Not requested' | 'Requested' | 'Received - in review' | 'Overdue';

export interface MissingItem {
  readonly id: string;
  readonly label: string;
  readonly owner: ActionOwner;
  readonly status: ItemStatus;
  readonly requestedOn: string | null;
  readonly dueOn: string;
  readonly analystMayContactClient: boolean;
  readonly evidenceRef: string | null;
  readonly note: string;
}

export interface OnboardingCase {
  readonly id: string;
  readonly clientName: string;
  readonly jurisdiction: string;
  readonly risk: RiskRating;
  readonly openedOn: string;
  readonly slaDueOn: string;
  readonly daysOpen: number;
  readonly daysRemaining: number;
  readonly relationshipBanker: string;
  readonly proposedAccount: string;
  readonly proposedFacility: string;
  readonly missing: readonly MissingItem[];
}

export interface OnboardingSnapshot {
  readonly asOf: string;
  readonly cutOff: string;
  readonly slaDays: number;
}

export const snapshot: OnboardingSnapshot = {
  asOf: '16 Oct 2026',
  cutOff: '16:00 GMT',
  slaDays: 10,
};

export const ownerOrder: readonly ActionOwner[] = ['Client', 'Relationship banker', 'Compliance', 'Second analyst', 'KYC analyst'];

