  {
    id: 'OBC-26-04181',
    clientName: 'Halvorsen Marine Logistics Ltd',
    jurisdiction: 'United Kingdom',
    risk: 'High',
    openedOn: '7 Oct 2026',
    slaDueOn: '17 Oct 2026',
    daysOpen: 9,
    daysRemaining: 1,
    relationshipBanker: 'Priya Raman',
    proposedAccount: 'GB** **** **** 4417 82',
    proposedFacility: 'GBP 2,500,000 trade facility',
    missing: [
      { id: 'OBC-26-04181-A', label: 'Ultimate beneficial owner declaration (signed)', owner: 'Client', status: 'Requested', requestedOn: '9 Oct 2026', dueOn: '15 Oct 2026', analystMayContactClient: true, evidenceRef: null, note: 'Chased by email on 14 Oct 2026; no reply.' },
      { id: 'OBC-26-04181-B', label: 'Second analyst approval for high-risk rating', owner: 'Second analyst', status: 'Not requested', requestedOn: null, dueOn: '16 Oct 2026', analystMayContactClient: false, evidenceRef: null, note: 'Waiting on UBO declaration before review can start.' },
    ],
  },
  {
    id: 'OBC-26-04203',
    clientName: 'Brightwater Foods GmbH',
    jurisdiction: 'Germany',
    risk: 'Medium',
    openedOn: '12 Oct 2026',
    slaDueOn: '22 Oct 2026',
    daysOpen: 4,
    daysRemaining: 6,
    relationshipBanker: 'Lukas Meyer',
    proposedAccount: 'DE** **** **** **** 2093 05',
