import { useMemo, useState } from "react";
import {
  Badge,
  Banner,
  BannerContent,
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogHeader,
  Divider,
  FlexLayout,
  FlowLayout,
  FormField,
  FormFieldHelperText,
  FormFieldLabel,
  H2,
  H3,
  H4,
  Input,
  Label,
  MultilineInput,
  NavigationItem,
  StackLayout,
  StatusIndicator,
  Table,
  TBody,
  TD,
  TH,
  THead,
  TR,
  Text,
  ToggleButton,
  ToggleButtonGroup,
} from "@salt-ds/core";
import {
  onboardingCases,
  ownerOrder,
  snapshot,
  type ItemStatus,
  type MissingItem,
  type OnboardingCase,
} from "./data";

type DisplayStatus = ItemStatus | "Cleared";

interface ItemState {
  status: DisplayStatus;
  evidenceRef: string | null;
  requestedOn: string | null;
  reason?: string;
  approver?: string;
}

interface AuditEntry {
  id: number;
  caseId: string;
  text: string;
}

type CaseFilter = "all" | "overdue" | "soon";

const statusTone = (s: DisplayStatus): "error" | "warning" | "info" | "success" => {
  switch (s) {
    case "Overdue":
      return "error";
    case "Not requested":
      return "warning";
    case "Cleared":
      return "success";
    default:
      return "info";
  }
};

const slaText = (days: number): string => {
  if (days < 0) return `${Math.abs(days)} ${Math.abs(days) === 1 ? "day" : "days"} past SLA`;
  if (days === 0) return "SLA due today";
  return `${days} ${days === 1 ? "day" : "days"} left`;
};

const maskAccount = (acct: string): string => {
  const digits = acct.replace(/[^0-9]/g, "");
  return `••••${digits.slice(-4)}`;
};

export default function OnboardingCaseChecklist() {
  const sortedCases = useMemo(
    () => [...onboardingCases].sort((a, b) => a.daysRemaining - b.daysRemaining),
    []
  );
  const [filter, setFilter] = useState<CaseFilter>("all");
  const [selectedId, setSelectedId] = useState<string>(sortedCases[0].id);
  const [itemState, setItemState] = useState<Record<string, ItemState>>(() => {
    const init: Record<string, ItemState> = {};
    onboardingCases.forEach((c) =>
      c.missing.forEach((m) => {
        init[m.id] = { status: m.status, evidenceRef: m.evidenceRef, requestedOn: m.requestedOn };
      })
    );
    return init;
  });
  const [audit, setAudit] = useState<AuditEntry[]>([]);
  const [clearing, setClearing] = useState<MissingItem | null>(null);
  const [reason, setReason] = useState("");
  const [evidence, setEvidence] = useState("");
  const [approver, setApprover] = useState("");

  const openCount = (c: OnboardingCase) =>
    c.missing.filter((m) => itemState[m.id].status !== "Cleared").length;

  const visibleCases = sortedCases.filter((c) => {
    if (filter === "overdue") return c.daysRemaining < 0;
    if (filter === "soon") return c.daysRemaining >= 0 && c.daysRemaining <= 3;
    return true;
  });

  const selected = sortedCases.find((c) => c.id === selectedId) ?? sortedCases[0];
  const openItems = selected.missing.filter((m) => itemState[m.id].status !== "Cleared");
  const caseAudit = audit.filter((a) => a.caseId === selected.id);
  const needsSecondApproval = selected.risk === "High";

  const addAudit = (text: string) =>
    setAudit((prev) => [{ id: prev.length + 1, caseId: selected.id, text }, ...prev]);

  const markRequested = (m: MissingItem) => {
    setItemState((prev) => ({
      ...prev,
      [m.id]: { ...prev[m.id], status: "Requested", requestedOn: snapshot.asOf },
    }));
    addAudit(`${snapshot.asOf}: requested "${m.label}" from ${m.owner}.`);
  };

  const openClear = (m: MissingItem) => {
    setClearing(m);
    setReason("");
    setEvidence(itemState[m.id].evidenceRef ?? "");
    setApprover("");
  };

  const requiresApprover = clearing?.owner === "Second analyst";
  const canConfirm =
    reason.trim().length > 0 &&
    evidence.trim().length > 0 &&
    (!requiresApprover || approver.trim().length > 0);

  const confirmClear = () => {
    if (!clearing || !canConfirm) return;
    setItemState((prev) => ({
      ...prev,
      [clearing.id]: {
        ...prev[clearing.id],
        status: "Cleared",
        evidenceRef: evidence.trim(),
        reason: reason.trim(),
        approver: requiresApprover ? approver.trim() : undefined,
      },
    }));
    addAudit(
      `${snapshot.asOf}: cleared "${clearing.label}" with evidence ${evidence.trim()}. Reason: ${reason.trim()}${
        requiresApprover ? `. Approved by ${approver.trim()}` : ""
      }.`
    );
    setClearing(null);
  };

  const ownerCounts = ownerOrder
    .map((o) => ({ owner: o, count: openItems.filter((m) => m.owner === o).length }))
    .filter((o) => o.count > 0);

  return (
    <FlexLayout gap={3} align="start" wrap>
      <StackLayout gap={2} style={{ width: "calc(var(--salt-size-base) * 10)", flex: "none" }}>
        <StackLayout gap={0.5}>
          <H2 styleAs="h3">Onboarding cases</H2>
          <Text color="secondary" styleAs="label">
            As of {snapshot.asOf}, {snapshot.cutOff} cut-off · {snapshot.slaDays}-day SLA
          </Text>
        </StackLayout>
        <ToggleButtonGroup
          aria-label="Filter cases"
          value={filter}
          onChange={(e) => setFilter(e.currentTarget.value as CaseFilter)}
        >
          <ToggleButton value="all">All</ToggleButton>
          <ToggleButton value="overdue">Past SLA</ToggleButton>
          <ToggleButton value="soon">Due ≤ 3 days</ToggleButton>
        </ToggleButtonGroup>
        <nav aria-label="Onboarding cases">
          <StackLayout
            as="ul"
            gap="var(--salt-spacing-fixed-100)"
            style={{ listStyle: "none", paddingLeft: 0, margin: 0 }}
          >
            {visibleCases.length === 0 && (
              <li>
                <Text color="secondary">No cases match this filter.</Text>
              </li>
            )}
            {visibleCases.map((c) => {
              const open = openCount(c);
              return (
                <li key={c.id}>
                  <NavigationItem
                    href={`#${c.id}`}
                    orientation="vertical"
                    active={c.id === selected.id}
                    onClick={(e) => {
                      e.preventDefault();
                      setSelectedId(c.id);
                    }}
                  >
                    <StackLayout gap={0} as="span">
                      <Text as="span">{c.clientName}</Text>
                      <Text as="span" styleAs="label" color="secondary">
                        {c.id} · {c.risk} risk · {slaText(c.daysRemaining)}
                      </Text>
                    </StackLayout>
                    <Badge value={open} aria-label={`${open} open items`} />
                  </NavigationItem>
                </li>
              );
            })}
          </StackLayout>
        </nav>
      </StackLayout>

      <Divider orientation="vertical" />

      <StackLayout gap={3} style={{ flex: 1, minWidth: 0 }} id={selected.id}>
        <StackLayout gap={1}>
          <FlexLayout justify="space-between" align="baseline" wrap gap={1}>
            <H3 styleAs="h2">{selected.clientName}</H3>
            <FlexLayout gap={1} align="center">
              <StatusIndicator
                aria-hidden
                status={selected.daysRemaining < 0 ? "error" : selected.daysRemaining <= 2 ? "warning" : "info"}
              />
              <Text>
                SLA {selected.slaDueOn} · {slaText(selected.daysRemaining)}
              </Text>
            </FlexLayout>
          </FlexLayout>
          <FlowLayout gap={3}>
            <StackLayout gap={0}>
              <Label color="secondary">Case</Label>
              <Text>{selected.id}</Text>
            </StackLayout>
            <StackLayout gap={0}>
              <Label color="secondary">Jurisdiction</Label>
              <Text>{selected.jurisdiction}</Text>
            </StackLayout>
            <StackLayout gap={0}>
              <Label color="secondary">Risk</Label>
              <Text>{selected.risk}</Text>
            </StackLayout>
            <StackLayout gap={0}>
              <Label color="secondary">Relationship banker</Label>
              <Text>{selected.relationshipBanker}</Text>
            </StackLayout>
            <StackLayout gap={0}>
              <Label color="secondary">Proposed account</Label>
              <Text>{maskAccount(selected.proposedAccount)}</Text>
            </StackLayout>
            <StackLayout gap={0}>
              <Label color="secondary">Facility</Label>
              <Text>{selected.proposedFacility}</Text>
            </StackLayout>
          </FlowLayout>
        </StackLayout>

        {needsSecondApproval && (
          <Banner status="warning">
            <BannerContent>
              High-risk client: a second analyst must approve before this case can close.
            </BannerContent>
          </Banner>
        )}

        <StackLayout gap={1}>
          <H4>Who needs to act</H4>
          {ownerCounts.length === 0 ? (
            <FlexLayout gap={1} align="center">
              <StatusIndicator aria-hidden status="success" />
              <Text>All items cleared and evidenced. Ready for case decision.</Text>
            </FlexLayout>
          ) : (
            <FlowLayout gap={3}>
              {ownerCounts.map((o) => (
                <Text key={o.owner}>
                  {o.owner}: {o.count} open {o.count === 1 ? "item" : "items"}
                </Text>
              ))}
            </FlowLayout>
          )}
        </StackLayout>

        <StackLayout gap={1}>
          <H4>Missing items checklist</H4>
          <Table>
            <THead>
              <TR>
                <TH>Item</TH>
                <TH>Owner</TH>
                <TH>Status</TH>
                <TH>Requested / due</TH>
                <TH>Evidence</TH>
                <TH>Actions</TH>
              </TR>
            </THead>
            <TBody>
              {selected.missing.map((m) => {
                const st = itemState[m.id];
                const cleared = st.status === "Cleared";
                const noContact = !m.analystMayContactClient && (m.owner === "Client" || m.owner === "Compliance");
                return (
                  <TR key={m.id}>
                    <TD>
                      <StackLayout gap={0.5}>
                        <Text>{m.label}</Text>
                        <Text styleAs="label" color="secondary">
                          {cleared && st.reason ? `Reason: ${st.reason}` : m.note}
                        </Text>
                        {cleared && st.approver && (
                          <Text styleAs="label" color="secondary">
                            Approved by {st.approver}
                          </Text>
                        )}
                        {noContact && !cleared && (
                          <Text styleAs="label" color="warning">
                            Do not contact the client about this item.
                          </Text>
                        )}
                      </StackLayout>
                    </TD>
                    <TD>{m.owner}</TD>
                    <TD>
                      <FlexLayout gap={1} align="center" wrap={false}>
                        <StatusIndicator aria-hidden status={statusTone(st.status)} />
                        <Text>{st.status}</Text>
                      </FlexLayout>
                    </TD>
                    <TD>
                      <StackLayout gap={0}>
                        <Text styleAs="label">Requested: {st.requestedOn ?? "—"}</Text>
                        <Text styleAs="label">Due: {m.dueOn}</Text>
                      </StackLayout>
                    </TD>
                    <TD>
                      <Text>{st.evidenceRef ?? "None yet"}</Text>
                    </TD>
                    <TD>
                      {cleared ? (
                        <Text color="secondary">Recorded</Text>
                      ) : (
                        <FlexLayout gap={1} wrap>
                          {st.status === "Not requested" && (
                            <Button
                              sentiment="neutral"
                              appearance="bordered"
                              onClick={() => markRequested(m)}
                              aria-label={`Mark requested: ${m.label}`}
                            >
                              Mark requested
                            </Button>
                          )}
                          <Button
                            sentiment="accented"
                            onClick={() => openClear(m)}
                            aria-label={`Clear with evidence: ${m.label}`}
                          >
                            Clear
                          </Button>
                        </FlexLayout>
                      )}
                    </TD>
                  </TR>
                );
              })}
            </TBody>
          </Table>
        </StackLayout>

        <StackLayout gap={1}>
          <H4>Audit trail this session</H4>
          {caseAudit.length === 0 ? (
            <Text color="secondary">No actions recorded on this case yet.</Text>
          ) : (
            <StackLayout as="ul" gap={0.5} style={{ paddingLeft: "var(--salt-spacing-300)", margin: 0 }}>
              {caseAudit.map((a) => (
                <li key={a.id}>
                  <Text>{a.text}</Text>
                </li>
              ))}
            </StackLayout>
          )}
        </StackLayout>
      </StackLayout>

      <Dialog open={clearing !== null} onOpenChange={(open) => !open && setClearing(null)}>
        <DialogHeader header="Clear item with evidence" />
        <DialogContent>
          <StackLayout gap={2}>
            <Text>
              {clearing?.label} · {selected.clientName} ({selected.id})
            </Text>
            <FormField necessity="required">
              <FormFieldLabel>Evidence reference</FormFieldLabel>
              <Input
                value={evidence}
                onChange={(e) => setEvidence((e.target as HTMLInputElement).value)}
                placeholder="e.g. DOC-30921"
              />
              <FormFieldHelperText>Document, screening or report ID stored for audit.</FormFieldHelperText>
            </FormField>
            <FormField necessity="required">
              <FormFieldLabel>Reason for decision</FormFieldLabel>
              <MultilineInput
                value={reason}
                onChange={(e) => setReason((e.target as unknown as HTMLTextAreaElement).value)}
              />
            </FormField>
            {requiresApprover && (
              <FormField necessity="required">
                <FormFieldLabel>Approving second analyst</FormFieldLabel>
                <Input
                  value={approver}
                  onChange={(e) => setApprover((e.target as HTMLInputElement).value)}
                />
                <FormFieldHelperText>Must be a different analyst from you.</FormFieldHelperText>
              </FormField>
            )}
          </StackLayout>
        </DialogContent>
        <DialogActions>
          <Button appearance="transparent" onClick={() => setClearing(null)}>
            Cancel
          </Button>
          <Button sentiment="accented" disabled={!canConfirm} onClick={confirmClear}>
            Record and clear
          </Button>
        </DialogActions>
      </Dialog>
    </FlexLayout>
  );
}

