import { useMemo, useState, type SyntheticEvent } from "react";
import {
  Banner,
  BannerContent,
  Button,
  Card,
  Dialog,
  DialogActions,
  DialogContent,
  DialogHeader,
  Display2,
  Display3,
  Divider,
  Dropdown,
  FlexLayout,
  FlowLayout,
  FormField,
  FormFieldHelperText,
  FormFieldLabel,
  GridLayout,
  H1,
  H2,
  H3,
  MultilineInput,
  Option,
  StackLayout,
  StatusIndicator,
  Table,
  TableContainer,
  TBody,
  TD,
  TH,
  THead,
  Text,
  ToggleButton,
  ToggleButtonGroup,
  TR,
} from "@salt-ds/core";
import {
  cashAccounts,
  currencyTotals,
  positionMeta,
  sweepReasonCodes,
  sweepSuggestions,
  type CashAccount,
  type PositionStatus,
  type SweepSuggestion,
} from "./data";

type Filter = "all" | PositionStatus;

const mask = (n: string) => `••••${n.replace(/\D/g, "").slice(-4)}`;

const statusLabel: Record<PositionStatus, string> = {
  short: "Short",
  "in-range": "In range",
  surplus: "Surplus",
};

const statusIndicator: Record<PositionStatus, "error" | "info" | "success"> = {
  short: "error",
  "in-range": "info",
  surplus: "success",
};

const accountById = (id: string) => cashAccounts.find((a) => a.id === id);

const StatusCell = ({ status }: { status: PositionStatus }) => (
  <FlexLayout gap={1} align="center">
    <StatusIndicator status={statusIndicator[status]} aria-hidden />
    <Text>{statusLabel[status]}</Text>
  </FlexLayout>
);

export default function CashPosition() {
  const [filter, setFilter] = useState<Filter>("all");
  const [queued, setQueued] = useState<Record<string, string>>({});
  const [flagged, setFlagged] = useState<Record<string, boolean>>({});
  const [activeSweep, setActiveSweep] = useState<SweepSuggestion | null>(null);
  const [reason, setReason] = useState<string[]>([]);
  const [otherText, setOtherText] = useState("");
  const [submitted, setSubmitted] = useState(false);

  const shortfalls = useMemo(
    () =>
      cashAccounts
        .filter((a) => a.status === "short")
        .map((a) => ({ account: a, coverage: a.balance / a.minimumTarget }))
        .sort((x, y) => x.coverage - y.coverage),
    [],
  );

  const rows = useMemo(
    () =>
      cashAccounts
        .filter((a) => filter === "all" || a.status === filter)
        .slice()
        .sort((x, y) => x.gap / x.minimumTarget - y.gap / y.minimumTarget),
    [filter],
  );

  const isOther = reason[0]?.startsWith("Other") ?? false;
  const reasonError = submitted && reason.length === 0;
  const otherError = submitted && isOther && otherText.trim().length === 0;

  const openSweep = (s: SweepSuggestion) => {
    setActiveSweep(s);
    setReason([]);
    setOtherText("");
    setSubmitted(false);
  };

  const closeSweep = () => setActiveSweep(null);

  const confirmSweep = () => {
    setSubmitted(true);
    if (!activeSweep || reason.length === 0) return;
    if (isOther && otherText.trim().length === 0) return;
    const text = isOther ? `Other: ${otherText.trim()}` : reason[0];
    setQueued((q) => ({ ...q, [activeSweep.toAccountId]: text }));
    setActiveSweep(null);
  };

  const onFilterChange = (event: SyntheticEvent<HTMLButtonElement>) => {
    setFilter(event.currentTarget.value as Filter);
  };

  const sweepFrom = activeSweep ? accountById(activeSweep.fromAccountId) : undefined;
  const sweepTo = activeSweep ? accountById(activeSweep.toAccountId) : undefined;

  const renderShortfallAction = (account: CashAccount) => {
    const suggestion = sweepSuggestions.find((s) => s.toAccountId === account.id);
    if (queued[account.id]) {
      return (
        <StackLayout gap={0.5}>
          <FlexLayout gap={1} align="center">
            <StatusIndicator status="success" aria-hidden />
            <Text>Sweep queued for funding desk</Text>
          </FlexLayout>
          <Text styleAs="label" color="secondary">
            Reason: {queued[account.id]}
          </Text>
        </StackLayout>
      );
    }
    if (account.viewOnly) {
      return (
        <StackLayout gap={1}>
          <FlexLayout gap={1} align="center">
            <StatusIndicator status="warning" aria-hidden />
            <Text styleAs="label">
              View only: {account.entity} must fund this account
            </Text>
          </FlexLayout>
          <Button
            appearance="bordered"
            sentiment="neutral"
            onClick={() => setFlagged((f) => ({ ...f, [account.id]: !f[account.id] }))}
          >
            {flagged[account.id] ? "Flagged to entity treasury" : "Flag to entity treasury"}
          </Button>
        </StackLayout>
      );
    }
    if (suggestion) {
      const from = accountById(suggestion.fromAccountId);
      return (
        <StackLayout gap={1}>
          <Text styleAs="label" color="secondary">
            Suggested: {suggestion.amountFormatted} from {from?.entity} {from ? mask(from.maskedNumber) : ""}
          </Text>
          <Button sentiment="accented" onClick={() => openSweep(suggestion)}>
            Review sweep
          </Button>
        </StackLayout>
      );
    }
    return (
      <StackLayout gap={1}>
        <Text styleAs="label" color="secondary">
          No {account.currency} surplus in view to sweep. Arrange short-term funding.
        </Text>
        <Button
          appearance="bordered"
          sentiment="neutral"
          onClick={() => setFlagged((f) => ({ ...f, [account.id]: !f[account.id] }))}
        >
          {flagged[account.id] ? "Sent to funding desk" : "Send to funding desk"}
        </Button>
      </StackLayout>
    );
  };

  return (
    <StackLayout gap={3}>
      <StackLayout gap={1}>
        <H1>Cash position</H1>
        <Text color="secondary">
          {positionMeta.groupName} · As at {positionMeta.asOf} · Showing {positionMeta.shownAccounts} of{" "}
          {positionMeta.totalAccounts} accounts
        </Text>
      </StackLayout>

      <Banner status="info">
        <BannerContent>
          {positionMeta.dataLagNote} Every sweep needs an audit reason. View-only subsidiary accounts can't be swept from this page.
        </BannerContent>
      </Banner>

      <StackLayout gap={2} as="section" aria-labelledby="shortfalls-heading">
        <FlexLayout justify="space-between" align="baseline" wrap>
          <H2 id="shortfalls-heading">
            {shortfalls.length} accounts below funding minimum
          </H2>
          <Text styleAs="label" color="secondary">
            Ranked by share of minimum covered, lowest first
          </Text>
        </FlexLayout>
        <GridLayout columns={{ xs: 1, sm: 2, lg: 4 }} gap={2}>
          {shortfalls.map(({ account, coverage }, index) => (
            <Card key={account.id}>
              <StackLayout gap={2}>
                <StackLayout gap={0.5}>
                  <FlexLayout gap={1} align="center">
                    <Text styleAs="label" color="secondary">
                      #{index + 1}
                    </Text>
                    <StatusIndicator status="error" aria-hidden />
                    <Text styleAs="label">Short · {Math.round(coverage * 100)}% of minimum</Text>
                  </FlexLayout>
                  <H3>{account.entity}</H3>
                  <Text styleAs="label" color="secondary">
                    {account.accountName} {mask(account.maskedNumber)} · {account.bank}
                  </Text>
                </StackLayout>
                <StackLayout gap={0.5}>
                  <Text styleAs="label" color="secondary">
                    Shortfall to fund
                  </Text>
                  <Display3>
                    {account.currency} {account.gapFormatted.replace("-", "")}
                  </Display3>
                  <Text styleAs="label" color="secondary">
                    Balance {account.balanceFormatted} · Minimum {account.minimumTargetFormatted}
                  </Text>
                  <Text styleAs="label">Sweep cut-off {account.sweepCutOff}</Text>
                </StackLayout>
                <Divider variant="tertiary" />
                {renderShortfallAction(account)}
              </StackLayout>
            </Card>
          ))}
        </GridLayout>
      </StackLayout>

      <StackLayout gap={2} as="section" aria-labelledby="currency-heading">
        <H2 id="currency-heading">Group total by currency</H2>
        <FlowLayout gap={3} align="end">
          <StackLayout gap={0.5}>
            <Text styleAs="label" color="secondary">
              Group total ({positionMeta.reportingCurrency} equivalent, {positionMeta.totalAccounts} accounts)
            </Text>
            <Display2>{positionMeta.groupTotalFormatted}</Display2>
          </StackLayout>
        </FlowLayout>
        <GridLayout columns={{ xs: 1, sm: 3, lg: 6 }} gap={2}>
          {currencyTotals.map((t) => {
            const netShort = t.netGapFormatted.startsWith("-");
            return (
              <Card key={t.currency}>
                <StackLayout gap={1}>
                  <Text styleAs="label" color="secondary">
                    {t.currency} · {t.accountCount} {t.accountCount === 1 ? "account" : "accounts"}
                  </Text>
                  <Text styleAs="h3">{t.totalFormatted}</Text>
                  <Text styleAs="label">
                    Net vs minimum: {t.currency} {t.netGapFormatted}
                  </Text>
                  <FlexLayout gap={1} align="center">
                    <StatusIndicator
                      status={netShort ? "error" : t.shortAccountCount > 0 ? "warning" : "success"}
                      aria-hidden
                    />
                    <Text styleAs="label">
                      {netShort
                        ? "Net short"
                        : t.shortAccountCount > 0
                          ? `${t.shortAccountCount} short account`
                          : "All funded"}
                    </Text>
                  </FlexLayout>
                </StackLayout>
              </Card>
            );
          })}
        </GridLayout>
      </StackLayout>

      <StackLayout gap={2} as="section" aria-labelledby="balances-heading">
        <FlexLayout justify="space-between" align="end" wrap gap={2}>
          <H2 id="balances-heading">Account balances</H2>
          <FormField style={{ width: "auto" }}>
            <FormFieldLabel>Show</FormFieldLabel>
            <ToggleButtonGroup value={filter} onChange={onFilterChange}>
              <ToggleButton value="all">All</ToggleButton>
              <ToggleButton value="short">Short</ToggleButton>
              <ToggleButton value="in-range">In range</ToggleButton>
              <ToggleButton value="surplus">Surplus</ToggleButton>
            </ToggleButtonGroup>
          </FormField>
        </FlexLayout>
        <TableContainer>
          <Table>
            <caption>
              {rows.length} accounts shown, as at {positionMeta.asOf}
            </caption>
            <THead>
              <TR>
                <TH>Entity and account</TH>
                <TH>Currency</TH>
                <TH style={{ textAlign: "right" }}>Balance</TH>
                <TH style={{ textAlign: "right" }}>Minimum</TH>
                <TH style={{ textAlign: "right" }}>Gap</TH>
                <TH>Status</TH>
                <TH>Access</TH>
                <TH>Updated</TH>
                <TH>Cut-off</TH>
              </TR>
            </THead>
            <TBody>
              {rows.map((a) => (
                <TR key={a.id}>
                  <TD>
                    <StackLayout gap={0}>
                      <Text>{a.entity}</Text>
                      <Text styleAs="label" color="secondary">
                        {a.accountName} {mask(a.maskedNumber)}
                      </Text>
                    </StackLayout>
                  </TD>
                  <TD>{a.currency}</TD>
                  <TD style={{ textAlign: "right" }}>{a.balanceFormatted}</TD>
                  <TD style={{ textAlign: "right" }}>{a.minimumTargetFormatted}</TD>
                  <TD style={{ textAlign: "right" }}>
                    {a.currency} {a.gapFormatted}
                  </TD>
                  <TD>
                    <StatusCell status={a.status} />
                  </TD>
                  <TD>{a.viewOnly ? "View only" : "Full"}</TD>
                  <TD>{a.lastUpdated.split(", ")[1]}</TD>
                  <TD>{a.sweepCutOff}</TD>
                </TR>
              ))}
            </TBody>
          </Table>
        </TableContainer>
      </StackLayout>

      <Dialog open={activeSweep !== null} onOpenChange={(o) => !o && closeSweep()} size="medium">
        <DialogHeader header="Review sweep" />
        <DialogContent>
          {activeSweep && sweepFrom && sweepTo && (
            <StackLayout gap={2}>
              <StackLayout gap={0.5}>
                <Text styleAs="label" color="secondary">
                  Amount
                </Text>
                <Display3>{activeSweep.amountFormatted}</Display3>
              </StackLayout>
              <GridLayout columns={2} gap={2}>
                <StackLayout gap={0.5}>
                  <Text styleAs="label" color="secondary">
                    From
                  </Text>
                  <Text>{sweepFrom.entity}</Text>
                  <Text styleAs="label">
                    {sweepFrom.accountName} {mask(sweepFrom.maskedNumber)}
                  </Text>
                </StackLayout>
                <StackLayout gap={0.5}>
                  <Text styleAs="label" color="secondary">
                    To
                  </Text>
                  <Text>{sweepTo.entity}</Text>
                  <Text styleAs="label">
                    {sweepTo.accountName} {mask(sweepTo.maskedNumber)}
                  </Text>
                </StackLayout>
                <StackLayout gap={0.5}>
                  <Text styleAs="label" color="secondary">
                    Value date
                  </Text>
                  <Text>{activeSweep.valueDate}</Text>
                </StackLayout>
                <StackLayout gap={0.5}>
                  <Text styleAs="label" color="secondary">
                    Cut-off
                  </Text>
                  <Text>{activeSweep.cutOff}</Text>
                </StackLayout>
              </GridLayout>
              <FormField necessity="required" validationStatus={reasonError ? "error" : undefined}>
                <FormFieldLabel>Audit reason</FormFieldLabel>
                <Dropdown
                  selected={reason}
                  onSelectionChange={(_e, next) => setReason(next)}
                  placeholder="Select a reason"
                >
                  {sweepReasonCodes.map((r) => (
                    <Option value={r} key={r} />
                  ))}
                </Dropdown>
                {reasonError && <FormFieldHelperText>Select an audit reason.</FormFieldHelperText>}
              </FormField>
              {isOther && (
                <FormField necessity="required" validationStatus={otherError ? "error" : undefined}>
                  <FormFieldLabel>Describe the reason</FormFieldLabel>
                  <MultilineInput
                    value={otherText}
                    onChange={(e) =>
                      setOtherText((e.target as unknown as HTMLTextAreaElement).value)
                    }
                  />
                  <FormFieldHelperText>
                    {otherError ? "Enter a reason for the audit trail." : "Recorded in the sweep audit trail."}
                  </FormFieldHelperText>
                </FormField>
              )}
            </StackLayout>
          )}
        </DialogContent>
        <DialogActions>
          <Button appearance="bordered" sentiment="accented" onClick={closeSweep}>
            Cancel
          </Button>
          <Button sentiment="accented" onClick={confirmSweep}>
            Queue sweep
          </Button>
        </DialogActions>
      </Dialog>
    </StackLayout>
  );
}

