import { useMemo, useState, type SyntheticEvent } from "react";
import {
  Banner,
  BannerContent,
  Button,
  Divider,
  Dropdown,
  FlexLayout,
  FormField,
  FormFieldHelperText,
  FormFieldLabel,
  GridItem,
  GridLayout,
  H1,
  H2,
  H3,
  Label,
  MultilineInput,
  Option,
  Panel,
  StackLayout,
  StatusIndicator,
  Table,
  TableContainer,
  TBody,
  TD,
  TFoot,
  TH,
  THead,
  Text,
  ToggleButton,
  ToggleButtonGroup,
  TR,
} from "@salt-ds/core";
import {
  cashAccounts,
  currencyTotals,
  positionMeta,
  sweepReasonCodes,
  sweepSuggestions,
  type CashAccount,
  type Currency,
  type PositionStatus,
} from "./data";

const CURRENCIES: Currency[] = ["GBP", "EUR", "USD", "SEK", "PLN", "CHF"];

const statusLabel: Record<PositionStatus, string> = {
  surplus: "Surplus",
  "in-range": "In range",
  short: "Short",
};

const statusIndicator: Record<PositionStatus, "success" | "info" | "error"> = {
  surplus: "success",
  "in-range": "info",
  short: "error",
};

const mask = (masked: string) => `••••${masked.replace(/\D/g, "").slice(-4)}`;

const accountById = (id: string) => cashAccounts.find((a) => a.id === id);

function DetailRow({ label, value }: { label: string; value: string }) {
  return (
    <FlexLayout justify="space-between" gap={2}>
      <Text color="secondary">{label}</Text>
      <Text style={{ textAlign: "right" }}>{value}</Text>
    </FlexLayout>
  );
}

export default function CashPositionMatrix() {
  const [selectedId, setSelectedId] = useState<string>("acc-02");
  const [filter, setFilter] = useState<"all" | "short">("all");
  const [reasons, setReasons] = useState<Record<string, string>>({});
  const [notes, setNotes] = useState<Record<string, string>>({});
  const [submitted, setSubmitted] = useState<Record<string, string>>({});

  const entities = useMemo(() => {
    const list: string[] = [];
    cashAccounts.forEach((a) => {
      if (!list.includes(a.entity)) list.push(a.entity);
    });
    return list.filter(
      (e) =>
        filter === "all" ||
        cashAccounts.some((a) => a.entity === e && a.status === "short"),
    );
  }, [filter]);

  const shortAccounts = cashAccounts.filter((a) => a.status === "short");
  const selected = accountById(selectedId) as CashAccount;

  const sweep = sweepSuggestions.find(
    (s) => s.toAccountId === selectedId || s.fromAccountId === selectedId,
  );
  const fromAcc = sweep ? accountById(sweep.fromAccountId) : undefined;
  const toAcc = sweep ? accountById(sweep.toAccountId) : undefined;
  const sweepViewOnly = Boolean(fromAcc?.viewOnly || toAcc?.viewOnly);
  const reason = sweep ? reasons[sweep.id] ?? "" : "";
  const note = sweep ? notes[sweep.id] ?? "" : "";
  const needsNote = reason.startsWith("Other");
  const canSubmit = Boolean(reason) && (!needsNote || note.trim().length > 0);
  const sweepDone = sweep ? submitted[sweep.id] : undefined;

  const onFilterChange = (event: SyntheticEvent<HTMLButtonElement>) => {
    setFilter(event.currentTarget.value as "all" | "short");
  };

  return (
    <StackLayout gap={3}>
      <StackLayout gap={1}>
        <H1>Cash position</H1>
        <Text color="secondary">
          {positionMeta.groupName} · As at {positionMeta.asOf} · Showing{" "}
          {positionMeta.shownAccounts} of {positionMeta.totalAccounts} accounts
        </Text>
      </StackLayout>

      <Banner status="info">
        <BannerContent>
          {positionMeta.dataLagNote} Check the balance time on each account
          before you fund or sweep.
        </BannerContent>
      </Banner>

      <FlowLayout3
        groupTotal={positionMeta.groupTotalFormatted}
        reporting={positionMeta.reportingCurrency}
        shortCount={shortAccounts.length}
        shortCurrencies={Array.from(new Set(shortAccounts.map((a) => a.currency))).join(", ")}
        nextCutOff="14:30 CEST (PLN)"
      />

      <GridLayout columns={3} gap={3}>
        <GridItem colSpan={2}>
          <StackLayout gap={2}>
            <FlexLayout justify="space-between" align="end" wrap gap={2}>
              <StackLayout gap={0.5}>
                <H2>Funding gap by entity and currency</H2>
                <Text color="secondary">
                  Gap is balance minus minimum target. Select a cell to see the
                  account and its sweep.
                </Text>
              </StackLayout>
              <FormField>
                <FormFieldLabel>Show entities</FormFieldLabel>
                <ToggleButtonGroup value={filter} onChange={onFilterChange}>
                  <ToggleButton value="all">All</ToggleButton>
                  <ToggleButton value="short">
                    With shortfalls ({shortAccounts.length})
                  </ToggleButton>
                </ToggleButtonGroup>
              </FormField>
            </FlexLayout>

            <FlexLayout gap={3} wrap>
              {(["short", "in-range", "surplus"] as PositionStatus[]).map((s) => (
                <FlexLayout key={s} gap={1} align="center">
                  <StatusIndicator status={statusIndicator[s]} />
                  <Text>
                    {statusLabel[s]}
                    {s === "short"
                      ? " (below minimum target)"
                      : s === "surplus"
                        ? " (available to sweep)"
                        : " (above target, hold)"}
                  </Text>
                </FlexLayout>
              ))}
            </FlexLayout>

            <TableContainer>
              <Table>
                <caption>
                  Funding gap per account, entities against currencies
                </caption>
                <THead>
                  <TR>
                    <TH>Entity</TH>
                    {CURRENCIES.map((c) => (
                      <TH key={c}>{c}</TH>
                    ))}
                  </TR>
                </THead>
                <TBody>
                  {entities.map((entity) => (
                    <TR key={entity}>
                      <TH scope="row">{entity}</TH>
                      {CURRENCIES.map((c) => {
                        const acc = cashAccounts.find(
                          (a) => a.entity === entity && a.currency === c,
                        );
                        if (!acc) {
                          return (
                            <TD key={c}>
                              <Text color="secondary" aria-label="No account">
                                —
                              </Text>
                            </TD>
                          );
                        }
                        const isSelected = acc.id === selectedId;
                        const content = (
                          <StackLayout gap={0.5} align="start">
                            <Button
                              appearance={isSelected ? "bordered" : "transparent"}
                              sentiment={isSelected ? "accented" : "neutral"}
                              aria-pressed={isSelected}
                              aria-label={`${entity} ${c}: gap ${c} ${acc.gapFormatted}, ${statusLabel[acc.status]}${acc.viewOnly ? ", view only" : ""}`}
                              onClick={() => setSelectedId(acc.id)}
                            >
                              <StatusIndicator status={statusIndicator[acc.status]} />
                              {acc.gapFormatted}
                            </Button>
                            <Text styleAs="label" color="secondary">
                              {statusLabel[acc.status]}
                              {acc.viewOnly ? " · View only" : ""}
                            </Text>
                          </StackLayout>
                        );
                        if (acc.status === "short") {
                          return (
                            <TD
                              key={c}
                              style={{
                                background: "var(--salt-status-error-background)",
                              }}
                            >
                              {content}
                            </TD>
                          );
                        }
                        if (acc.status === "surplus") {
                          return (
                            <TD
                              key={c}
                              style={{
                                background: "var(--salt-status-success-background)",
                              }}
                            >
                              {content}
                            </TD>
                          );
                        }
                        return <TD key={c}>{content}</TD>;
                      })}
                    </TR>
                  ))}
                </TBody>
                <TFoot>
                  <TR>
                    <TH scope="row">All group accounts (net gap)</TH>
                    {CURRENCIES.map((c) => {
                      const t = currencyTotals.find((x) => x.currency === c);
                      if (!t) return <TD key={c}>—</TD>;
                      return (
                        <TD key={c}>
                          <StackLayout gap={0.5}>
                            <Text>{t.netGapFormatted}</Text>
                            <Text styleAs="label" color="secondary">
                              {t.totalFormatted}
                            </Text>
                            <Text styleAs="label" color="secondary">
                              {t.accountCount} accts · {t.shortAccountCount} short
                            </Text>
                          </StackLayout>
                        </TD>
                      );
                    })}
                  </TR>
                </TFoot>
              </Table>
            </TableContainer>
          </StackLayout>
        </GridItem>

        <GridItem>
          <Panel
            variant="secondary"
            style={{ padding: "var(--salt-spacing-300)" }}
            aria-labelledby="sweep-panel-heading"
          >
            <StackLayout gap={2}>
              <StackLayout gap={0.5}>
                <Label color="secondary">Selected account</Label>
                <H2 id="sweep-panel-heading">{selected.entity}</H2>
                <Text color="secondary">
                  {selected.accountName} · {mask(selected.maskedNumber)} ·{" "}
                  {selected.bank}
                </Text>
              </StackLayout>

              <FlexLayout gap={1} align="center">
                <StatusIndicator status={statusIndicator[selected.status]} />
                <Text>{statusLabel[selected.status]}</Text>
                {selected.viewOnly && <Text color="secondary">· View only</Text>}
              </FlexLayout>

              <StackLayout gap={1}>
                <DetailRow label="Balance" value={selected.balanceFormatted} />
                <DetailRow label="Minimum target" value={selected.minimumTargetFormatted} />
                <DetailRow
                  label="Gap"
                  value={`${selected.currency} ${selected.gapFormatted}`}
                />
                <DetailRow label="Balance as at" value={selected.lastUpdated} />
                <DetailRow label="Sweep cut-off" value={selected.sweepCutOff} />
              </StackLayout>

              <Divider />

              <H3>Suggested sweep</H3>
              {!sweep || !fromAcc || !toAcc ? (
                <Text color="secondary">
                  No sweep suggested for this account today.
                  {selected.status === "short"
                    ? " Arrange short-term funding with the funding desk."
                    : ""}
                </Text>
              ) : (
                <StackLayout gap={2}>
                  <StackLayout gap={1}>
                    <DetailRow
                      label="From"
                      value={`${fromAcc.entity} ${mask(fromAcc.maskedNumber)}`}
                    />
                    <DetailRow
                      label="To"
                      value={`${toAcc.entity} ${mask(toAcc.maskedNumber)}`}
                    />
                    <DetailRow label="Amount" value={sweep.amountFormatted} />
                    <DetailRow label="Value date" value={sweep.valueDate} />
                    <DetailRow label="Cut-off" value={sweep.cutOff} />
                  </StackLayout>

                  {sweepViewOnly && (
                    <Banner status="warning">
                      <BannerContent>
                        You can only view one of these accounts. The sweep goes
                        to the subsidiary treasurer as a request.
                      </BannerContent>
                    </Banner>
                  )}

                  {sweepDone ? (
                    <Banner status="success">
                      <BannerContent>
                        {sweepViewOnly ? "Sweep request sent" : "Sweep submitted"}:{" "}
                        {sweep.amountFormatted}. Audit reason: {sweepDone}.
                      </BannerContent>
                    </Banner>
                  ) : (
                    <StackLayout gap={2}>
                      <FormField necessity="required">
                        <FormFieldLabel>Audit reason</FormFieldLabel>
                        <Dropdown
                          placeholder="Select a reason"
                          selected={reason ? [reason] : []}
                          onSelectionChange={(_e, next) =>
                            setReasons((r) => ({ ...r, [sweep.id]: next[0] ?? "" }))
                          }
                        >
                          {sweepReasonCodes.map((code) => (
                            <Option key={code} value={code} />
                          ))}
                        </Dropdown>
                        <FormFieldHelperText>
                          Every sweep needs an audit reason.
                        </FormFieldHelperText>
                      </FormField>
                      {needsNote && (
                        <FormField necessity="required">
                          <FormFieldLabel>Reason details</FormFieldLabel>
                          <MultilineInput
                            value={note}
                            onChange={(e) => {
                              const value = (
                                e.target as unknown as HTMLTextAreaElement
                              ).value;
                              setNotes((n) => ({ ...n, [sweep.id]: value }));
                            }}
                          />
                        </FormField>
                      )}
                      <FlexLayout gap={1} justify="end">
                        <Button
                          sentiment="accented"
                          appearance="solid"
                          disabled={!canSubmit}
                          onClick={() =>
                            setSubmitted((s) => ({
                              ...s,
                              [sweep.id]: needsNote ? `Other: ${note.trim()}` : reason,
                            }))
                          }
                        >
                          {sweepViewOnly ? "Request sweep" : "Submit sweep"}
                        </Button>
                      </FlexLayout>
                    </StackLayout>
                  )}
                </StackLayout>
              )}
            </StackLayout>
          </Panel>
        </GridItem>
      </GridLayout>
    </StackLayout>
  );
}

function FlowLayout3({
  groupTotal,
  reporting,
  shortCount,
  shortCurrencies,
  nextCutOff,
}: {
  groupTotal: string;
  reporting: string;
  shortCount: number;
  shortCurrencies: string;
  nextCutOff: string;
}) {
  return (
    <GridLayout columns={3} gap={3}>
      <StackLayout gap={0.5}>
        <Label color="secondary">Group cash ({reporting} equivalent)</Label>
        <Text styleAs="h2">{groupTotal}</Text>
      </StackLayout>
      <StackLayout gap={0.5}>
        <Label color="secondary">Accounts below minimum target</Label>
        <FlexLayout gap={1} align="center">
          <StatusIndicator status="error" />
          <Text styleAs="h2">{shortCount} short</Text>
        </FlexLayout>
        <Text color="secondary">In {shortCurrencies}</Text>
      </StackLayout>
      <StackLayout gap={0.5}>
        <Label color="secondary">Earliest sweep cut-off today</Label>
        <Text styleAs="h2">{nextCutOff}</Text>
      </StackLayout>
    </GridLayout>
  );
}

