export type Currency = 'GBP' | 'EUR' | 'USD' | 'SEK' | 'PLN' | 'CHF';
export type PositionStatus = 'surplus' | 'in-range' | 'short';

export interface CashAccount {
  readonly id: string;
  readonly entity: string;
  readonly accountName: string;
  readonly maskedNumber: string;
  readonly bank: string;
  readonly currency: Currency;
  readonly balance: number;
  readonly balanceFormatted: string;
  readonly minimumTarget: number;
  readonly minimumTargetFormatted: string;
  readonly gap: number;
  readonly gapFormatted: string;
  readonly status: PositionStatus;
  readonly viewOnly: boolean;
  readonly lastUpdated: string;
  readonly sweepCutOff: string;
}

export interface CurrencyTotal {
  readonly currency: Currency;
  readonly accountCount: number;
  readonly totalFormatted: string;
  readonly netGapFormatted: string;
  readonly shortAccountCount: number;
}

export interface SweepSuggestion {
  readonly id: string;
  readonly fromAccountId: string;
  readonly toAccountId: string;
  readonly currency: Currency;
  readonly amount: number;
  readonly amountFormatted: string;
  readonly valueDate: string;
  readonly cutOff: string;
  readonly requiresReason: boolean;
}

export interface PositionMeta {
  readonly groupName: string;
  readonly asOf: string;
  readonly reportingCurrency: Currency;
  readonly groupTotalFormatted: string;
  readonly totalAccounts: number;
  readonly shownAccounts: number;
  readonly dataLagNote: string;
}

export const positionMeta: PositionMeta = {
  groupName: 'Calder & Finch Group',
  asOf: '16 Oct 2026, 08:47 BST',
  reportingCurrency: 'GBP',
  groupTotalFormatted: 'GBP 21,386,240.00',
  totalAccounts: 23,
  shownAccounts: 10,
  dataLagNote: 'Intraday balances may lag by up to 15 minutes.',
};

