import { useMemo, useState } from "react";
import {
  Banner,
  BannerActions,
  BannerContent,
  Button,
  Card,
  CardContent,
  Dialog,
  DialogActions,
  DialogContent,
  DialogHeader,
  Divider,
  FlexLayout,
  H1,
  H2,
  H3,
  StackLayout,
  StatusIndicator,
  Text,
} from "@salt-ds/core";
import { CloseIcon } from "@salt-ds/icons";
import {
  asOf,
  approver,
  cutOffs,
  fourEyesMessage,
  payments,
  type Payment,
  type PaymentStatus,
} from "./data";

type Indicator = "info" | "success" | "warning" | "error";

function formatRemaining(minutes: number): string {
  const h = Math.floor(minutes / 60);
  const m = minutes % 60;
  return `${h} h ${m} min left`;
}

function isActionable(p: Payment, status: PaymentStatus): boolean {
  return status === "Needs approval" && p.canApprove;
}

function statusView(p: Payment, status: PaymentStatus): { indicator: Indicator; text: string } {
  if (status === "Released") return { indicator: "success", text: "Released" };
  if (status === "Returned for repair") return { indicator: "error", text: "Returned for repair" };
  if (status === "Awaiting second approver")
    return { indicator: "info", text: "Awaiting second approver" };
  if (!p.canApprove) return { indicator: "info", text: "Needs approval · you created it" };
  if (p.flag) return { indicator: "warning", text: `Needs approval · ${p.flag}` };
  return { indicator: "warning", text: "Needs approval" };
}

function DetailRow({ label, value }: { label: string; value: string }) {
  return (
    <StackLayout gap={0}>
      <Text styleAs="label" color="secondary">
        {label}
      </Text>
      <Text>{value}</Text>
    </StackLayout>
  );
}

export default function UrgentApprovalsQueue() {
  const [overrides, setOverrides] = useState<Record<string, PaymentStatus>>({});
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [step, setStep] = useState<"review" | "confirm">("review");
  const [notice, setNotice] = useState<string | null>(null);

  const statusOf = (p: Payment): PaymentStatus => overrides[p.id] ?? p.status;

  const groups = useMemo(() => {
    const labels: { label: string; minutes: number; currencies: string[] }[] = [];
    [...cutOffs]
      .sort((a, b) => a.minutesRemaining - b.minutesRemaining)
      .forEach((c) => {
        const existing = labels.find((l) => l.label === c.label);
        if (existing) existing.currencies.push(c.currency);
        else labels.push({ label: c.label, minutes: c.minutesRemaining, currencies: [c.currency] });
      });
    return labels.map((g) => {
      const items = payments
        .filter((p) => p.cutOff === g.label)
        .sort((a, b) => {
          const sa = overrides[a.id] ?? a.status;
          const sb = overrides[b.id] ?? b.status;
          const ra = isActionable(a, sa) ? 0 : sa === "Needs approval" ? 1 : 2;
          const rb = isActionable(b, sb) ? 0 : sb === "Needs approval" ? 1 : 2;
          if (ra !== rb) return ra - rb;
          return b.usdEquivalent - a.usdEquivalent;
        });
      const actionCount = items.filter((p) => isActionable(p, overrides[p.id] ?? p.status)).length;
      return { ...g, items, actionCount };
    });
  }, [overrides]);

  const totalAction = groups.reduce((sum, g) => sum + g.actionCount, 0);
  const selected = payments.find((p) => p.id === selectedId) ?? null;
  const selectedStatus = selected ? statusOf(selected) : null;
  const selectedActionable = selected && selectedStatus ? isActionable(selected, selectedStatus) : false;

  const openReview = (id: string) => {
    setSelectedId(id);
    setStep("review");
  };

  const close = () => {
    setSelectedId(null);
    setStep("review");
  };

  const approve = (p: Payment) => {
    const next: PaymentStatus = p.requiresFourEyes ? "Awaiting second approver" : "Released";
    setOverrides((prev) => ({ ...prev, [p.id]: next }));
    setNotice(
      p.requiresFourEyes
        ? `You approved ${p.amount} to ${p.payee}. It now needs a second approver before release.`
        : `Released ${p.amount} to ${p.payee}.`,
    );
    close();
  };

  const returnForRepair = (p: Payment) => {
    setOverrides((prev) => ({ ...prev, [p.id]: "Returned for repair" }));
    setNotice(`Returned ${p.amount} to ${p.payee} for repair.`);
    close();
  };

  const handleApproveClick = () => {
    if (!selected) return;
    if (selected.requiresFourEyes) setStep("confirm");
    else approve(selected);
  };

  return (
    <StackLayout gap={3}>
      <StackLayout gap={1}>
        <H1>Approvals</H1>
        <Text color="secondary">
          As of {asOf} · {approver.name}
        </Text>
        <Text>
          <strong>{totalAction}</strong> payments need your action before cut-off
        </Text>
      </StackLayout>

      {notice && (
        <Banner status="success" role="status">
          <BannerContent>{notice}</BannerContent>
          <BannerActions>
            <Button aria-label="Dismiss" appearance="transparent" onClick={() => setNotice(null)}>
              <CloseIcon aria-hidden />
            </Button>
          </BannerActions>
        </Banner>
      )}

      {groups.map((g) => (
        <StackLayout gap={1} key={g.label} as="section">
          <StackLayout gap={0}>
            <H2>Cut-off {g.label}</H2>
            <Text color="secondary">
              {formatRemaining(g.minutes)} · {g.currencies.join(", ")} · {g.actionCount} need action
            </Text>
          </StackLayout>
          {g.items.map((p) => {
            const s = statusOf(p);
            const view = statusView(p, s);
            const actionable = isActionable(p, s);
            return (
              <Card key={p.id} accent={actionable ? "left" : undefined}>
                <CardContent>
                  <StackLayout gap={1}>
                    <FlexLayout justify="space-between" align="start" gap={1}>
                      <H3>{p.payee}</H3>
                      <Text>
                        <strong>{p.amount}</strong>
                      </Text>
                    </FlexLayout>
                    <FlexLayout justify="space-between" align="center" gap={1} wrap>
                      <StackLayout gap={0}>
                        <FlexLayout gap={1} align="center">
                          <StatusIndicator status={view.indicator} />
                          <Text>{view.text}</Text>
                        </FlexLayout>
                        <Text color="secondary">Cut-off {p.cutOff}</Text>
                      </StackLayout>
                      <Button
                        sentiment={actionable ? "accented" : "neutral"}
                        appearance={actionable ? "solid" : "bordered"}
                        onClick={() => openReview(p.id)}
                        aria-label={`${actionable ? "Review" : "View"} payment to ${p.payee}, ${p.amount}`}
                      >
                        {actionable ? "Review" : "View"}
                      </Button>
                    </FlexLayout>
                  </StackLayout>
                </CardContent>
              </Card>
            );
          })}
        </StackLayout>
      ))}

      <Dialog
        open={selected !== null}
        onOpenChange={(open) => {
          if (!open) close();
        }}
        size="small"
      >
        {selected && selectedStatus && step === "review" && (
          <>
            <DialogHeader header={selected.payee} />
            <DialogContent>
              <StackLayout gap={2}>
                <StackLayout gap={0}>
                  <Text styleAs="h2">{selected.amount}</Text>
                  <FlexLayout gap={1} align="center">
                    <StatusIndicator status={statusView(selected, selectedStatus).indicator} />
                    <Text>{statusView(selected, selectedStatus).text}</Text>
                  </FlexLayout>
                </StackLayout>
                {selected.flag && (
                  <Banner status="warning">
                    <BannerContent>
                      <strong>{selected.flag}.</strong> {selected.flagDetail}
                    </BannerContent>
                  </Banner>
                )}
                {selected.blockedReason && (
                  <Banner status="info">
                    <BannerContent>{selected.blockedReason}</BannerContent>
                  </Banner>
                )}
                {selected.requiresFourEyes && selectedActionable && (
                  <Banner status="info">
                    <BannerContent>Over USD 1,000,000: four-eyes approval applies.</BannerContent>
                  </Banner>
                )}
                <DetailRow label="Beneficiary account" value={selected.beneficiaryAccount} />
                <DetailRow label="Beneficiary bank" value={selected.beneficiaryBank} />
                <Divider variant="secondary" />
                <DetailRow label="Cut-off" value={selected.cutOff} />
                <DetailRow label="Value date" value={selected.valueDate} />
                <DetailRow label="Created by" value={selected.createdBy} />
                <DetailRow label="Reference" value={selected.id} />
              </StackLayout>
            </DialogContent>
            <DialogActions>
              <StackLayout gap={1} style={{ flex: "auto" }}>
                {selectedActionable ? (
                  <>
                    <Button sentiment="accented" onClick={handleApproveClick}>
                      {selected.requiresFourEyes ? "Approve…" : "Approve and release"}
                    </Button>
                    <Button
                      sentiment="neutral"
                      appearance="bordered"
                      onClick={() => returnForRepair(selected)}
                    >
                      Return for repair
                    </Button>
                    <Button sentiment="neutral" appearance="transparent" onClick={close}>
                      Cancel
                    </Button>
                  </>
                ) : (
                  <Button sentiment="neutral" appearance="bordered" onClick={close}>
                    Close
                  </Button>
                )}
              </StackLayout>
            </DialogActions>
          </>
        )}
        {selected && step === "confirm" && (
          <>
            <DialogHeader header="Confirm four-eyes approval" />
            <DialogContent>
              <StackLayout gap={2}>
                <Banner status="warning">
                  <BannerContent>
                    <strong>Four-eyes rule.</strong> {fourEyesMessage}
                  </BannerContent>
                </Banner>
                <DetailRow label="Payee" value={selected.payee} />
                <DetailRow label="Amount" value={selected.amount} />
                <DetailRow label="Beneficiary account" value={selected.beneficiaryAccount} />
                <DetailRow label="Cut-off" value={selected.cutOff} />
                <Text color="secondary">
                  The second approver must approve before {selected.cutOff} for same-day release.
                </Text>
              </StackLayout>
            </DialogContent>
            <DialogActions>
              <StackLayout gap={1} style={{ flex: "auto" }}>
                <Button sentiment="accented" onClick={() => approve(selected)}>
                  Confirm my approval
                </Button>
                <Button sentiment="neutral" appearance="bordered" onClick={() => setStep("review")}>
                  Back
                </Button>
              </StackLayout>
            </DialogActions>
          </>
        )}
      </Dialog>
    </StackLayout>
  );
}

