import { useMemo, useState, type SyntheticEvent } from "react";
import {
  Button,
  Divider,
  FlexLayout,
  FormField,
  FormFieldLabel,
  H2,
  StackLayout,
  StatusIndicator,
  Table,
  TableContainer,
  TBody,
  TD,
  TH,
  THead,
  Text,
  ToggleButton,
  ToggleButtonGroup,
  TR,
} from "@salt-ds/core";
import {
  onboardingCase,
  outstandingItems,
  type ItemStatus,
  type OutstandingItem,
  type OwnerRole,
} from "./data";

type Indicator = "info" | "error" | "warning" | "success";

const ownerOrder: OwnerRole[] = [
  "Onboarding analyst",
  "Client",
  "Relationship banker",
  "Sanctions desk",
  "Second analyst",
];

const ownerLabel: Record<OwnerRole, string> = {
  "Onboarding analyst": "Me",
  Client: "Client",
  "Relationship banker": "Relationship banker",
  "Sanctions desk": "Sanctions desk",
  "Second analyst": "Second analyst",
};

const statusIndicator: Record<ItemStatus | "Decision recorded", Indicator> = {
  "Not requested": "warning",
  Requested: "info",
  Received: "info",
  "Under review": "info",
  Rejected: "error",
  "Decision recorded": "success",
};

const prerequisiteIds = ["itm-01", "itm-02", "itm-03", "itm-05"];

type LocalStatus = ItemStatus | "Decision recorded";

export default function OutstandingItemsByOwner() {
  const [filter, setFilter] = useState<"all" | "blocking">("all");
  const [statuses, setStatuses] = useState<Record<string, LocalStatus>>(() =>
    Object.fromEntries(outstandingItems.map((i) => [i.id, i.status])),
  );
  const [requestedOn, setRequestedOn] = useState<Record<string, string | null>>(
    () => Object.fromEntries(outstandingItems.map((i) => [i.id, i.requestedOn])),
  );

  const onFilterChange = (event: SyntheticEvent<HTMLButtonElement>) => {
    setFilter(event.currentTarget.value as "all" | "blocking");
  };

  const isOpen = (item: OutstandingItem) =>
    statuses[item.id] !== "Decision recorded";

  const visible = useMemo(
    () =>
      outstandingItems.filter((i) => (filter === "blocking" ? i.blocksApproval : true)),
    [filter],
  );

  const groups = ownerOrder
    .map((owner) => ({ owner, items: visible.filter((i) => i.owner === owner) }))
    .filter((g) => g.items.length > 0);

  const openBlocking = outstandingItems.filter(
    (i) => i.blocksApproval && isOpen(i),
  ).length;
  const openTotal = outstandingItems.filter(isOpen).length;
  const prerequisitesCleared = prerequisiteIds.every(
    (id) => statuses[id] === "Decision recorded",
  );

  const markRequested = (id: string) => {
    setStatuses((s) => ({ ...s, [id]: "Requested" }));
    setRequestedOn((r) => ({ ...r, [id]: "15 Oct 2026" }));
  };
  const recordDecision = (id: string) =>
    setStatuses((s) => ({ ...s, [id]: "Decision recorded" }));

  const renderAction = (item: OutstandingItem) => {
    const status = statuses[item.id];
    if (status === "Decision recorded") {
      return <Text color="secondary">No action</Text>;
    }
    if (item.owner === "Onboarding analyst") {
      return (
        <Button
          sentiment="accented"
          appearance="solid"
          onClick={() => recordDecision(item.id)}
          aria-label={`Record decision and reason for ${item.check}`}
        >
          Record decision
        </Button>
      );
    }
    if (item.owner === "Second analyst") {
      return prerequisitesCleared ? (
        <Button
          appearance="bordered"
          onClick={() => markRequested(item.id)}
          aria-label={`Request approval from ${item.ownerName}`}
        >
          Request approval
        </Button>
      ) : (
        <Text color="secondary">Waiting on items 01, 02, 03, 05</Text>
      );
    }
    if (!item.analystMayContact) {
      return <Text color="secondary">Wait for desk</Text>;
    }
    if (status === "Not requested") {
      return (
        <Button
          appearance="bordered"
          onClick={() => markRequested(item.id)}
          aria-label={`Request ${item.check} from ${item.ownerName}`}
        >
          Request
        </Button>
      );
    }
    if (status === "Rejected") {
      return (
        <Button
          appearance="bordered"
          onClick={() => markRequested(item.id)}
          aria-label={`Re-request ${item.check} from ${item.ownerName}`}
        >
          Re-request
        </Button>
      );
    }
    if (status === "Received" || status === "Requested" || status === "Under review") {
      return (
        <Button
          appearance="transparent"
          onClick={() => recordDecision(item.id)}
          aria-label={`Mark ${item.check} as cleared`}
        >
          Mark cleared
        </Button>
      );
    }
    return null;
  };

  return (
    <StackLayout gap={3}>
      <StackLayout gap={1}>
        <H2>Outstanding items by owner</H2>
        <Text color="secondary">
          {onboardingCase.clientName} · {onboardingCase.caseId} ·{" "}
          {onboardingCase.legalEntityType}
        </Text>
      </StackLayout>

      <FlexLayout gap={3} wrap align="end" justify="space-between">
        <FlexLayout gap={3} wrap>
          <StackLayout gap={0.5}>
            <Text styleAs="label" color="secondary">
              Service level
            </Text>
            <Text>
              Day {onboardingCase.slaDay} of {onboardingCase.slaDays} · due{" "}
              {onboardingCase.slaDueOn}
            </Text>
          </StackLayout>
          <StackLayout gap={0.5}>
            <Text styleAs="label" color="secondary">
              Risk rating
            </Text>
            <FlexLayout gap={0.75} align="center">
              <StatusIndicator status="error" aria-hidden />
              <Text>
                {onboardingCase.riskRating}
                {onboardingCase.requiresSecondApproval ? " · second approval required" : ""}
              </Text>
            </FlexLayout>
          </StackLayout>
          <StackLayout gap={0.5}>
            <Text styleAs="label" color="secondary">
              Open items
            </Text>
            <Text>
              {openTotal} open · {openBlocking} block approval
            </Text>
          </StackLayout>
          <StackLayout gap={0.5}>
            <Text styleAs="label" color="secondary">
              Client reply cut-off
            </Text>
            <Text>{onboardingCase.clientReplyCutOff}</Text>
          </StackLayout>
        </FlexLayout>
        <FormField>
          <FormFieldLabel>Show</FormFieldLabel>
          <ToggleButtonGroup value={filter} onChange={onFilterChange}>
            <ToggleButton value="all">All items</ToggleButton>
            <ToggleButton value="blocking">Blocks approval</ToggleButton>
          </ToggleButtonGroup>
        </FormField>
      </FlexLayout>

      <Divider />

      <TableContainer>
        <Table>
          <caption>
            <Text styleAs="label" color="secondary">
              Outstanding items grouped by who must act
            </Text>
          </caption>
          <THead>
            <TR>
              <TH>What is missing</TH>
              <TH>Status</TH>
              <TH>Due</TH>
              <TH>Blocks approval</TH>
              <TH>Evidence</TH>
              <TH>Action</TH>
            </TR>
          </THead>
          {groups.map(({ owner, items }) => {
            const names = Array.from(new Set(items.map((i) => i.ownerName))).join(", ");
            const mayContact = items.every((i) => i.analystMayContact);
            const openCount = items.filter(isOpen).length;
            return (
              <TBody key={owner}>
                <TR>
                  <TH
                    colSpan={6}
                    scope="colgroup"
                    style={{ background: "var(--salt-container-secondary-background)" }}
                  >
                    <FlexLayout gap={2} wrap align="center" justify="space-between">
                      <StackLayout gap={0.25}>
                        <Text>
                          <strong>{ownerLabel[owner]}</strong> · {names}
                        </Text>
                        <Text color="secondary" styleAs="label">
                          {openCount} of {items.length} open
                        </Text>
                      </StackLayout>
                      <FlexLayout gap={0.75} align="center">
                        <StatusIndicator
                          status={mayContact ? "success" : "warning"}
                          aria-hidden
                        />
                        <Text styleAs="label">
                          {owner === "Onboarding analyst"
                            ? "Your action"
                            : mayContact
                              ? "You may contact"
                              : "Do not contact client about screening"}
                        </Text>
                      </FlexLayout>
                    </FlexLayout>
                  </TH>
                </TR>
                {items.map((item) => {
                  const status = statuses[item.id];
                  const req = requestedOn[item.id];
                  return (
                    <TR key={item.id}>
                      <TD>
                        <StackLayout gap={0.25}>
                          <Text styleAs="label" color="secondary">
                            {item.id.replace("itm-", "Item ")} · {item.check}
                          </Text>
                          <Text>{item.missing}</Text>
                          <Text styleAs="label" color="secondary">
                            Reason: {item.reason}
                          </Text>
                        </StackLayout>
                      </TD>
                      <TD>
                        <StackLayout gap={0.25}>
                          <FlexLayout gap={0.75} align="center">
                            <StatusIndicator status={statusIndicator[status]} aria-hidden />
                            <Text>{status}</Text>
                          </FlexLayout>
                          {req && status !== "Decision recorded" && (
                            <Text styleAs="label" color="secondary">
                              Requested {req}
                            </Text>
                          )}
                        </StackLayout>
                      </TD>
                      <TD>
                        <Text>{item.dueOn}</Text>
                      </TD>
                      <TD>
                        <Text>{item.blocksApproval ? "Yes" : "No"}</Text>
                      </TD>
                      <TD>
                        <Text color={item.evidenceRef ? "primary" : "secondary"}>
                          {item.evidenceRef ?? "None yet"}
                        </Text>
                      </TD>
                      <TD>{renderAction(item)}</TD>
                    </TR>
                  );
                })}
              </TBody>
            );
          })}
        </Table>
      </TableContainer>
    </StackLayout>
  );
}

