export type OwnerRole = 'Client' | 'Relationship banker' | 'Sanctions desk' | 'Second analyst' | 'Onboarding analyst';
export type ItemStatus = 'Not requested' | 'Requested' | 'Received' | 'Under review' | 'Rejected';
export type RiskRating = 'Low' | 'Medium' | 'High';

export interface OnboardingCase {
  readonly caseId: string;
  readonly clientName: string;
  readonly legalEntityType: string;
  readonly riskRating: RiskRating;
  readonly requiresSecondApproval: boolean;
  readonly openedOn: string;
  readonly slaDueOn: string;
  readonly slaDay: number;
  readonly slaDays: number;
  readonly clientReplyCutOff: string;
  readonly proposedAccount: string;
  readonly expectedAnnualTurnover: string;
  readonly assignedAnalyst: string;
}

export interface OutstandingItem {
  readonly id: string;
  readonly check: string;
  readonly missing: string;
  readonly owner: OwnerRole;
  readonly ownerName: string;
  readonly status: ItemStatus;
  readonly requestedOn: string | null;
  readonly dueOn: string;
  readonly blocksApproval: boolean;
  readonly analystMayContact: boolean;
  readonly reason: string;
  readonly evidenceRef: string | null;
}

export const onboardingCase: OnboardingCase = {
  caseId: 'KYC-2026-048213',
  clientName: 'Brightwater Logistics GmbH',
  legalEntityType: 'Private limited company (DE)',
