  requiresSecondApproval: true,
  openedOn: '07 Oct 2026',
  slaDueOn: '21 Oct 2026',
  slaDay: 7,
  slaDays: 10,
  clientReplyCutOff: '16 Oct 2026, 17:00 CET',
  proposedAccount: 'DE•• •••• •••• 4821 (EUR)',
  expectedAnnualTurnover: 'EUR 42,500,000.00',
  assignedAnalyst: 'Wei Chen',
