    evidenceRef: 'EV-48213-004',
  },
  {
    id: 'itm-02',
    check: 'Authority to act',
    missing: 'Certified board resolution naming account signatories',
    owner: 'Client',
    ownerName: 'Henrik Voss (CFO)',
    status: 'Not requested',
    requestedOn: null,
    dueOn: '16 Oct 2026, 17:00 CET',
    blocksApproval: true,
    analystMayContact: true,
    reason: 'Two signatories on the application are not listed in the registry.',
    evidenceRef: null,
  },
  {
    id: 'itm-03',
    check: 'Source of wealth',
    missing: 'Evidence of funds behind the EUR 6,200,000.00 opening deposit',
    owner: 'Relationship banker',
    ownerName: 'Priya Nair',
    status: 'Requested',
    requestedOn: '13 Oct 2026',
    dueOn: '17 Oct 2026, 12:00 CET',
    blocksApproval: true,
    analystMayContact: true,
    reason: 'High-risk rating requires documented source of funds before approval.',
    evidenceRef: 'EV-48213-007',
  },
  {
    id: 'itm-04',
    check: 'Tax residency',
    missing: 'CRS self-certification signed by an authorised signatory',
    owner: 'Client',
    ownerName: 'Lena Fischer (Finance)',
    status: 'Rejected',
    requestedOn: '09 Oct 2026',
    dueOn: '16 Oct 2026, 17:00 CET',
    blocksApproval: false,
    analystMayContact: true,
    reason: 'Returned form is unsigned on page 2.',
    evidenceRef: 'EV-48213-002',
  },
  {
    id: 'itm-05',
    check: 'Sanctions screening',
    missing: 'Disposition of potential match on director Ivan Petrescu',
    owner: 'Sanctions desk',
    ownerName: 'Screening team, Frankfurt',
    status: 'Under review',
    requestedOn: '10 Oct 2026',
    dueOn: '19 Oct 2026, 16:00 CET',
    blocksApproval: true,
    analystMayContact: false,
    reason: 'Name match 86%; do not contact the client about screening results.',
    evidenceRef: 'EV-48213-005',
  },
  {
    id: 'itm-06',
    check: 'Expected activity',
    missing: 'Rationale for monthly outbound payments to AED and SGD counterparties',
    owner: 'Relationship banker',
    ownerName: 'Priya Nair',
    status: 'Not requested',
    requestedOn: null,
    dueOn: '18 Oct 2026, 12:00 CET',
    blocksApproval: false,
    analystMayContact: true,
    reason: 'Expected corridors differ from the stated business model.',
    evidenceRef: null,
  },
  {
    id: 'itm-07',
    check: 'Address verification',
    missing: 'Review of proof of registered address (utility bill, 02 Sep 2026)',
    owner: 'Onboarding analyst',
    ownerName: 'Wei Chen',
    status: 'Received',
    requestedOn: '09 Oct 2026',
    dueOn: '16 Oct 2026, 17:00 CET',
    blocksApproval: false,
    analystMayContact: true,
    reason: 'Document received 14 Oct 2026; decision and reason not yet recorded.',
    evidenceRef: 'EV-48213-003',
  },
  {
    id: 'itm-08',
    check: 'High-risk approval',
    missing: 'Second analyst approval of the recorded risk decision',
    owner: 'Second analyst',
