import { useMemo, useState } from "react";
import {
  Banner,
  BannerActions,
  BannerContent,
  Button,
  Card,
  Checkbox,
  Dialog,
  DialogActions,
  DialogContent,
  DialogHeader,
  Divider,
  FlexLayout,
  FlowLayout,
  H1,
  H2,
  H3,
  StackLayout,
  StatusIndicator,
  Table,
  TableContainer,
  TBody,
  TD,
  TH,
  THead,
  TR,
  Text,
} from "@salt-ds/core";
import { CloseIcon } from "@salt-ds/icons";
import {
  asOf,
  currentApprover,
  cutOffs,
  fourEyesThreshold,
  payments,
  type CurrencyCode,
  type Payment,
  type PaymentFlagKind,
} from "./data";

type Decision = "released" | "first-approval" | "rejected";

const flagLabels: Record<PaymentFlagKind, string> = {
  "possible-duplicate": "Possible duplicate",
  "new-beneficiary": "New beneficiary",
  "unusual-amount": "Unusual amount",
  "beneficiary-details-changed": "Beneficiary details changed",
};

const zoneLabel = (tz: string) => (tz === "America/New_York" ? "ET" : "London");

const formatCountdown = (mins: number) => {
  const h = Math.floor(mins / 60);
  const m = mins % 60;
  return h > 0 ? `${h}h ${m}m` : `${m}m`;
};

const maskAccount = (acct: string) => `••••${acct.replace(/\D/g, "").slice(-4)}`;
const maskDebit = (acct: string) => acct.replace(/\*+\s?/g, "••••");

const formatAmount = (currency: CurrencyCode, n: number) =>
  `${currency} ${n.toLocaleString("en-GB", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;

const approvalText = (p: Payment) =>
  p.approvalsRequired === 2
    ? `${p.approvedBy.length} of 2 approvals`
    : "1 approval needed";

const decisionText: Record<Decision, string> = {
  released: "Released",
  "first-approval": "Your approval recorded, awaiting second approver",
  rejected: "Rejected, returned to preparer",
};

const decisionStatus: Record<Decision, "success" | "info" | "error"> = {
  released: "success",
  "first-approval": "info",
  rejected: "error",
};

export default function UrgentPaymentApprovals() {
  const [decisions, setDecisions] = useState<Record<string, Decision>>({});
  const [selected, setSelected] = useState<Set<string>>(new Set());
  const [reviewId, setReviewId] = useState<string | null>(null);
  const [flagChecked, setFlagChecked] = useState(false);
  const [bulkCurrency, setBulkCurrency] = useState<CurrencyCode | null>(null);
  const [message, setMessage] = useState<string | null>(null);

  const orderedCutOffs = useMemo(
    () => [...cutOffs].sort((a, b) => a.minutesRemaining - b.minutesRemaining),
    [],
  );

  const pending = payments.filter((p) => !decisions[p.id]);
  const flaggedPending = pending.filter((p) => p.flags.length > 0);

  const outcomeFor = (p: Payment): Decision =>
    p.approvalsRequired === 2 && p.approvedBy.length === 0 ? "first-approval" : "released";

  const approve = (ids: string[]) => {
    const next = { ...decisions };
    let released = 0;
    let first = 0;
    ids.forEach((id) => {
      const p = payments.find((x) => x.id === id);
      if (!p || !p.canApprove || next[id]) return;
      const outcome = outcomeFor(p);
      next[id] = outcome;
      if (outcome === "released") released += 1;
      else first += 1;
    });
    setDecisions(next);
    setSelected((prev) => {
      const s = new Set(prev);
      ids.forEach((id) => s.delete(id));
      return s;
    });
    const parts: string[] = [];
    if (released) parts.push(`${released} payment${released > 1 ? "s" : ""} released`);
    if (first) parts.push(`${first} approved and sent for second approval`);
    setMessage(parts.join("; ") + ".");
  };

  const reject = (id: string) => {
    setDecisions((d) => ({ ...d, [id]: "rejected" }));
    setSelected((prev) => {
      const s = new Set(prev);
      s.delete(id);
      return s;
    });
    setMessage(`${id} rejected and returned to its preparer.`);
  };

  const toggle = (id: string) =>
    setSelected((prev) => {
      const s = new Set(prev);
      if (s.has(id)) s.delete(id);
      else s.add(id);
      return s;
    });

  const reviewPayment = payments.find((p) => p.id === reviewId) ?? null;
  const openReview = (id: string) => {
    setFlagChecked(false);
    setReviewId(id);
  };
  const closeReview = () => setReviewId(null);

  const bulkItems = bulkCurrency
    ? pending.filter((p) => p.currency === bulkCurrency && selected.has(p.id))
    : [];

  return (
    <StackLayout gap={3}>
      <StackLayout gap={1}>
        <H1>Approvals</H1>
        <Text color="secondary">
          Today's urgent payments for {currentApprover.name}, as of {asOf}. Payments over{" "}
          {fourEyesThreshold} need two approvers.
        </Text>
      </StackLayout>

      {message && (
        <Banner status="success">
          <BannerContent>{message}</BannerContent>
          <BannerActions>
            <Button aria-label="Dismiss" appearance="transparent" onClick={() => setMessage(null)}>
              <CloseIcon aria-hidden />
            </Button>
          </BannerActions>
        </Banner>
      )}

      <FlowLayout gap={2}>
        {orderedCutOffs.map((c) => {
          const list = pending.filter((p) => p.currency === c.currency);
          const flagged = list.filter((p) => p.flags.length > 0).length;
          const urgent = c.minutesRemaining <= 180;
          return (
            <Card key={c.currency} style={{ minWidth: "calc(var(--salt-size-base) * 7)" }}>
              <StackLayout gap={1}>
                <Text styleAs="label" color="secondary">
                  {c.label} · {c.time} {zoneLabel(c.timeZone)}
                </Text>
                <FlexLayout gap={1} align="center">
                  <StatusIndicator status={urgent ? "warning" : "info"} aria-hidden />
                  <Text styleAs="h3">Closes in {formatCountdown(c.minutesRemaining)}</Text>
                </FlexLayout>
                <Text>
                  {list.length} pending · {flagged} flagged
                </Text>
              </StackLayout>
            </Card>
          );
        })}
      </FlowLayout>

      {flaggedPending.length > 0 && (
        <Text>
          {flaggedPending.length} flagged payment{flaggedPending.length > 1 ? "s" : ""} need
          individual review. Routine payments can be released together.
        </Text>
      )}

      {orderedCutOffs.map((c) => {
        const group = payments.filter((p) => p.currency === c.currency);
        const groupPending = group.filter((p) => !decisions[p.id]);
        const flagged = groupPending.filter((p) => p.flags.length > 0);
        const routine = groupPending.filter((p) => p.flags.length === 0);
        const actioned = group.filter((p) => decisions[p.id]);
        const selectable = routine.filter((p) => p.canApprove);
        const selectedHere = selectable.filter((p) => selected.has(p.id));
        const allSelected = selectable.length > 0 && selectedHere.length === selectable.length;
        const someSelected = selectedHere.length > 0 && !allSelected;
        const selectedTotal = selectedHere.reduce((s, p) => s + p.amount, 0);
        const urgent = c.minutesRemaining <= 180;

        return (
          <StackLayout key={c.currency} gap={2}>
            <Divider />
            <FlexLayout justify="space-between" align="center" wrap gap={2}>
              <StackLayout gap={0.5}>
                <H2>
                  {c.currency} payments · cut-off {c.time} {zoneLabel(c.timeZone)}
                </H2>
                <FlexLayout gap={1} align="center">
                  <StatusIndicator status={urgent ? "warning" : "info"} aria-hidden />
                  <Text color="secondary">
                    {urgent ? "Closing soon: " : ""}
                    {formatCountdown(c.minutesRemaining)} left · {groupPending.length} pending ·{" "}
                    {formatAmount(
                      c.currency,
                      groupPending.reduce((s, p) => s + p.amount, 0),
                    )}
                  </Text>
                </FlexLayout>
              </StackLayout>
            </FlexLayout>

            <StackLayout gap={1}>
              <H3>Review first ({flagged.length})</H3>
              {flagged.length === 0 ? (
                <Text color="secondary">No flagged {c.currency} payments pending.</Text>
              ) : (
                <TableContainer>
                  <Table>
                    <caption>Flagged {c.currency} payments needing individual review</caption>
                    <THead>
                      <TR>
                        <TH>Flag</TH>
                        <TH>Beneficiary</TH>
                        <TH>Account</TH>
                        <TH style={{ textAlign: "right" }}>Amount</TH>
                        <TH>Approvals</TH>
                        <TH>Action</TH>
                      </TR>
                    </THead>
                    <TBody>
                      {flagged.map((p) => (
                        <TR key={p.id}>
                          <TD>
                            <StackLayout gap={0.5}>
                              {p.flags.map((f) => (
                                <FlexLayout key={f.kind} gap={1} align="center">
                                  <StatusIndicator status="warning" aria-hidden />
                                  <Text styleAs="label">{flagLabels[f.kind]}</Text>
                                </FlexLayout>
                              ))}
                            </StackLayout>
                          </TD>
                          <TD>
                            <StackLayout gap={0}>
                              <Text>{p.beneficiary}</Text>
                              <Text styleAs="label" color="secondary">
                                {p.type} · {p.reference}
                              </Text>
                            </StackLayout>
                          </TD>
                          <TD>{maskAccount(p.beneficiaryAccount)}</TD>
                          <TD style={{ textAlign: "right" }}>{p.amountFormatted}</TD>
                          <TD>{approvalText(p)}</TD>
                          <TD>
                            <Button sentiment="accented" onClick={() => openReview(p.id)}>
                              Review
                            </Button>
                          </TD>
                        </TR>
                      ))}
                    </TBody>
                  </Table>
                </TableContainer>
              )}
            </StackLayout>

            <StackLayout gap={1}>
              <FlexLayout justify="space-between" align="center" wrap gap={1}>
                <H3>Routine ({routine.length})</H3>
                <FlexLayout gap={1} align="center" wrap>
                  {selectedHere.length > 0 && (
                    <Text color="secondary">
                      {selectedHere.length} selected · {formatAmount(c.currency, selectedTotal)}
                    </Text>
                  )}
                  <Button
                    sentiment="accented"
                    disabled={selectedHere.length === 0}
                    onClick={() => setBulkCurrency(c.currency)}
                  >
                    Release selected ({selectedHere.length})
                  </Button>
                </FlexLayout>
              </FlexLayout>
              {routine.length === 0 ? (
                <Text color="secondary">No routine {c.currency} payments pending.</Text>
              ) : (
                <TableContainer>
                  <Table>
                    <caption>Routine {c.currency} payments</caption>
                    <THead>
                      <TR>
                        <TH>
                          <Checkbox
                            checked={allSelected}
                            indeterminate={someSelected}
                            disabled={selectable.length === 0}
                            inputProps={{ "aria-label": `Select all routine ${c.currency} payments` }}
                            onChange={() =>
                              setSelected((prev) => {
                                const s = new Set(prev);
                                if (allSelected) selectable.forEach((p) => s.delete(p.id));
                                else selectable.forEach((p) => s.add(p.id));
                                return s;
                              })
                            }
                          />
                        </TH>
                        <TH>Beneficiary</TH>
                        <TH>Account</TH>
                        <TH style={{ textAlign: "right" }}>Amount</TH>
                        <TH>Approvals</TH>
                        <TH>Action</TH>
                      </TR>
                    </THead>
                    <TBody>
                      {routine.map((p) => (
                        <TR key={p.id}>
                          <TD>
                            <Checkbox
                              checked={selected.has(p.id)}
                              disabled={!p.canApprove}
                              inputProps={{ "aria-label": `Select ${p.beneficiary}, ${p.amountFormatted}` }}
                              onChange={() => toggle(p.id)}
                            />
                          </TD>
                          <TD>
                            <StackLayout gap={0}>
                              <Text>{p.beneficiary}</Text>
                              <Text styleAs="label" color="secondary">
                                {p.type} · {p.reference}
                              </Text>
                            </StackLayout>
                          </TD>
                          <TD>{maskAccount(p.beneficiaryAccount)}</TD>
                          <TD style={{ textAlign: "right" }}>{p.amountFormatted}</TD>
                          <TD>
                            {p.canApprove ? (
                              approvalText(p)
                            ) : (
                              <FlexLayout gap={1} align="center">
                                <StatusIndicator status="info" aria-hidden />
                                <Text styleAs="label">Prepared by you, needs another approver</Text>
                              </FlexLayout>
                            )}
                          </TD>
                          <TD>
                            <Button appearance="bordered" onClick={() => openReview(p.id)}>
                              Details
                            </Button>
                          </TD>
                        </TR>
                      ))}
                    </TBody>
                  </Table>
                </TableContainer>
              )}
            </StackLayout>

            {actioned.length > 0 && (
              <StackLayout gap={1}>
                <H3>Actioned today ({actioned.length})</H3>
                <TableContainer>
                  <Table>
                    <caption>{c.currency} payments you have actioned</caption>
                    <THead>
                      <TR>
                        <TH>Beneficiary</TH>
                        <TH style={{ textAlign: "right" }}>Amount</TH>
                        <TH>Outcome</TH>
                      </TR>
                    </THead>
                    <TBody>
                      {actioned.map((p) => {
                        const d = decisions[p.id];
                        return (
                          <TR key={p.id}>
                            <TD>{p.beneficiary}</TD>
                            <TD style={{ textAlign: "right" }}>{p.amountFormatted}</TD>
                            <TD>
                              <FlexLayout gap={1} align="center">
                                <StatusIndicator status={decisionStatus[d]} aria-hidden />
                                <Text>{decisionText[d]}</Text>
                              </FlexLayout>
                            </TD>
                          </TR>
                        );
                      })}
                    </TBody>
                  </Table>
                </TableContainer>
              </StackLayout>
            )}
          </StackLayout>
        );
      })}

      <Dialog open={reviewPayment !== null} onOpenChange={(o) => !o && closeReview()} size="medium">
        {reviewPayment && (
          <>
            <DialogHeader header={`Review ${reviewPayment.id}`} />
            <DialogContent>
              <StackLayout gap={2}>
                {reviewPayment.flags.length > 0 && (
                  <Banner status="warning">
                    <BannerContent>
                      <StackLayout gap={0.5}>
                        {reviewPayment.flags.map((f) => (
                          <Text key={f.kind}>
                            <strong>{flagLabels[f.kind]}:</strong> {f.message}
                          </Text>
                        ))}
                      </StackLayout>
                    </BannerContent>
                  </Banner>
                )}
                {!reviewPayment.canApprove && (
                  <Banner status="info">
                    <BannerContent>
                      You prepared this payment, so another approver must release it.
                    </BannerContent>
                  </Banner>
                )}
                <StackLayout gap={1}>
                  {[
                    ["Beneficiary", reviewPayment.beneficiary],
                    ["Beneficiary account", reviewPayment.beneficiaryAccount.replace(/\*+\s?/g, "••••")],
                    ["Bank", `${reviewPayment.beneficiaryBank}, ${reviewPayment.bankCountry}`],
                    ["Amount", reviewPayment.amountFormatted],
                    ["Debit account", maskDebit(reviewPayment.debitAccount)],
                    ["Reference", `${reviewPayment.type} · ${reviewPayment.reference}`],
                    ["Value date", reviewPayment.valueDate],
                    ["Prepared by", `${reviewPayment.preparedBy}, ${reviewPayment.preparedAt} London`],
                    [
                      "Approvals",
                      reviewPayment.approvalsRequired === 2
                        ? `Four-eyes: ${reviewPayment.approvedBy.length} of 2${
                            reviewPayment.approvedBy.length
                              ? ` (approved by ${reviewPayment.approvedBy.join(", ")})`
                              : ""
                          }`
                        : "1 approval needed",
                    ],
                  ].map(([label, value]) => (
                    <FlexLayout key={label} gap={2} wrap>
                      <Text styleAs="label" color="secondary" style={{ minWidth: "calc(var(--salt-size-base) * 5)" }}>
                        {label}
                      </Text>
                      <Text>{value}</Text>
                    </FlexLayout>
                  ))}
                </StackLayout>
                {reviewPayment.canApprove && outcomeFor(reviewPayment) === "first-approval" && (
                  <Text color="secondary">
                    Your approval will be recorded. The payment is released once a second approver
                    signs off before cut-off.
                  </Text>
                )}
                {reviewPayment.canApprove && reviewPayment.flags.length > 0 && (
                  <Checkbox
                    checked={flagChecked}
                    onChange={() => setFlagChecked((v) => !v)}
                    label="I've checked the flagged details against the source documents"
                  />
                )}
              </StackLayout>
            </DialogContent>
            <DialogActions>
              <FlexLayout gap={1} wrap>
                <Button appearance="transparent" onClick={closeReview}>
                  Close
                </Button>
                {reviewPayment.canApprove && (
                  <>
                    <Button
                      appearance="bordered"
                      sentiment="negative"
                      onClick={() => {
                        reject(reviewPayment.id);
                        closeReview();
                      }}
                    >
                      Reject
                    </Button>
                    <Button
                      sentiment="accented"
                      disabled={reviewPayment.flags.length > 0 && !flagChecked}
                      onClick={() => {
                        approve([reviewPayment.id]);
                        closeReview();
                      }}
                    >
                      {outcomeFor(reviewPayment) === "first-approval" ? "Give first approval" : "Approve and release"}
                    </Button>
                  </>
                )}
              </FlexLayout>
            </DialogActions>
          </>
        )}
      </Dialog>

      <Dialog open={bulkCurrency !== null} onOpenChange={(o) => !o && setBulkCurrency(null)} size="small">
        {bulkCurrency && (
          <>
            <DialogHeader header={`Release ${bulkItems.length} ${bulkCurrency} payments?`} />
            <DialogContent>
              <StackLayout gap={1}>
                {bulkItems.map((p) => (
                  <FlexLayout key={p.id} justify="space-between" gap={2}>
                    <Text>
                      {p.beneficiary} · {maskAccount(p.beneficiaryAccount)}
                    </Text>
                    <Text>{p.amountFormatted}</Text>
                  </FlexLayout>
                ))}
                <Divider />
                <FlexLayout justify="space-between" gap={2}>
                  <Text styleAs="label">Total</Text>
                  <Text styleAs="label">
                    {formatAmount(bulkCurrency, bulkItems.reduce((s, p) => s + p.amount, 0))}
                  </Text>
                </FlexLayout>
                {bulkItems.some((p) => outcomeFor(p) === "first-approval") && (
                  <Text color="secondary">
                    Payments over {fourEyesThreshold} will get your first approval and wait for a
                    second approver.
                  </Text>
                )}
              </StackLayout>
            </DialogContent>
            <DialogActions>
              <FlexLayout gap={1}>
                <Button appearance="transparent" onClick={() => setBulkCurrency(null)}>
                  Cancel
                </Button>
                <Button
                  sentiment="accented"
                  onClick={() => {
                    approve(bulkItems.map((p) => p.id));
                    setBulkCurrency(null);
                  }}
                >
                  Release {bulkItems.length}
                </Button>
              </FlexLayout>
            </DialogActions>
          </>
        )}
      </Dialog>
    </StackLayout>
  );
}

