import { useMemo, useState } from "react";
import {
  Banner,
  BannerContent,
  Button,
  Card,
  Dialog,
  DialogActions,
  DialogContent,
  DialogHeader,
  Display3,
  Dropdown,
  FlexLayout,
  FormField,
  FormFieldHelperText,
  FormFieldLabel,
  GridLayout,
  H1,
  H2,
  Input,
  MultilineInput,
  Option,
  StackLayout,
  StatusIndicator,
  Table,
  TableContainer,
  TBody,
  TD,
  TFoot,
  TH,
  THead,
  Text,
  TR,
} from "@salt-ds/core";
import {
  cashAccounts,
  currencyTotals,
  groupSummary,
  sweepReasons,
  type CashAccount,
  type CurrencyCode,
} from "./data";

interface PlannedSweep {
  id: string;
  sourceId: string;
  targetId: string;
  amount: number;
  reasonId: string;
  note: string;
}

const fmt = (ccy: string, n: number) =>
  `${ccy} ${n.toLocaleString("en-GB", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  })}`;

const mask = (m: string) => m.replace(/\*/g, "•");

const fxRate = (ccy: CurrencyCode): number => {
  const t = currencyTotals.find((c) => c.currency === ccy);
  return t ? Number(t.fxRateToGBP) : 1;
};

const accountById = (id: string) => cashAccounts.find((a) => a.id === id);

const accountLabel = (a: CashAccount) =>
  `${a.entity} · ${a.accountName} ${mask(a.maskedNumber)}`;

export default function CashPositionShortfallLadder() {
  const [sweeps, setSweeps] = useState<PlannedSweep[]>([]);
  const [dialogTarget, setDialogTarget] = useState<CashAccount | null>(null);
  const [sourceId, setSourceId] = useState<string>("");
  const [amountText, setAmountText] = useState<string>("");
  const [reasonId, setReasonId] = useState<string>("");
  const [note, setNote] = useState<string>("");
  const [submitted, setSubmitted] = useState(false);
  const [lastMessage, setLastMessage] = useState<string | null>(null);

  const sweptIn = (id: string) =>
    sweeps.filter((s) => s.targetId === id).reduce((t, s) => t + s.amount, 0);
  const sweptOut = (id: string) =>
    sweeps.filter((s) => s.sourceId === id).reduce((t, s) => t + s.amount, 0);

  const availableSurplus = (a: CashAccount) =>
    Math.max(0, a.variance - sweptOut(a.id));

  const ladder = useMemo(
    () =>
      cashAccounts
        .filter((a) => a.status === "shortfall")
        .map((a) => {
          const gap = Math.abs(a.variance);
          const remaining = Math.max(0, gap - sweptIn(a.id));
          return {
            account: a,
            gap,
            remaining,
            gapGbp: gap * fxRate(a.currency),
            remainingGbp: remaining * fxRate(a.currency),
          };
        })
        .sort((x, y) => y.gapGbp - x.gapGbp),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [sweeps],
  );

  const sourcesFor = (a: CashAccount) =>
    cashAccounts.filter(
      (s) => s.currency === a.currency && s.status === "surplus" && s.id !== a.id,
    );

  const totalGapGbp = ladder.reduce((t, r) => t + r.gapGbp, 0);
  const totalRemainingGbp = ladder.reduce((t, r) => t + r.remainingGbp, 0);

  const surplusAccounts = cashAccounts.filter((a) => a.status !== "shortfall");
  const totalSurplusGbp = cashAccounts
    .filter((a) => a.status === "surplus")
    .reduce((t, a) => t + availableSurplus(a) * fxRate(a.currency), 0);

  const shortfallCurrencies = new Set(ladder.map((r) => r.account.currency));

  // Dialog
  const openSweep = (a: CashAccount) => {
    const firstSource = sourcesFor(a).find(
      (s) => !s.viewOnly && availableSurplus(s) > 0,
    );
    const remaining = Math.max(0, Math.abs(a.variance) - sweptIn(a.id));
    const suggested = firstSource
      ? Math.min(remaining, availableSurplus(firstSource))
      : remaining;
    setDialogTarget(a);
    setSourceId(firstSource ? firstSource.id : "");
    setAmountText(suggested ? suggested.toFixed(2) : "");
    setReasonId("");
    setNote("");
    setSubmitted(false);
  };

  const closeDialog = () => setDialogTarget(null);

  const source = sourceId ? accountById(sourceId) : undefined;
  const amount = Number(amountText.replace(/,/g, ""));
  const amountError = !amountText
    ? "Enter an amount"
    : Number.isNaN(amount) || amount <= 0
      ? "Enter an amount greater than zero"
      : source && amount > availableSurplus(source)
        ? `Exceeds available surplus of ${fmt(source.currency, availableSurplus(source))}`
        : null;
  const sourceError = !source ? "Choose a funding source" : null;
  const reasonError = !reasonId ? "An audit reason is required for every sweep" : null;
  const noteError =
    reasonId === "reason-05" && note.trim().length === 0
      ? "Add a note for this reason"
      : null;
  const hasErrors = !!(amountError || sourceError || reasonError || noteError);

  const confirmSweep = () => {
    setSubmitted(true);
    if (hasErrors || !dialogTarget || !source) return;
    setSweeps((prev) => [
      ...prev,
      {
        id: `sw-${prev.length + 1}`,
        sourceId: source.id,
        targetId: dialogTarget.id,
        amount,
        reasonId,
        note,
      },
    ]);
    const reason = sweepReasons.find((r) => r.id === reasonId)?.label ?? "";
    setLastMessage(
      `Sweep of ${fmt(dialogTarget.currency, amount)} from ${source.accountName} ${mask(
        source.maskedNumber,
      )} to ${dialogTarget.accountName} ${mask(dialogTarget.maskedNumber)} queued for the funding desk. Reason: ${reason}.`,
    );
    setDialogTarget(null);
  };

  const removeSweep = (id: string) =>
    setSweeps((prev) => prev.filter((s) => s.id !== id));

  const dialogSources = dialogTarget
    ? sourcesFor(dialogTarget).filter((s) => !s.viewOnly)
    : [];

  return (
    <StackLayout gap={3}>
      <StackLayout gap={1}>
        <H1>Cash position</H1>
        <Text color="secondary">
          Meridian Retail group · Balances as of {groupSummary.asOf} · Reporting
          currency {groupSummary.reportingCurrency}
        </Text>
      </StackLayout>

      <Banner status="info">
        <BannerContent>
          {groupSummary.dataLagNote}. Next sweep cut-off: {groupSummary.nextCutOff}.
        </BannerContent>
      </Banner>

      {lastMessage && (
        <Banner status="success" role="status">
          <BannerContent>{lastMessage}</BannerContent>
        </Banner>
      )}

      <GridLayout columns={{ xs: 1, sm: 2, md: 4 }} gap={2}>
        <Card>
          <StackLayout gap={1}>
            <Text color="secondary">Unfunded shortfall</Text>
            <Display3>{fmt("GBP", totalRemainingGbp)}</Display3>
            <StatusIndicator status="error" />
            <Text>
              {ladder.filter((r) => r.remaining > 0).length} of {ladder.length}{" "}
              accounts below minimum
            </Text>
          </StackLayout>
        </Card>
        <Card>
          <StackLayout gap={1}>
            <Text color="secondary">Sweepable surplus</Text>
            <Display3>{fmt("GBP", totalSurplusGbp)}</Display3>
            <Text color="secondary">Above minimum, after planned sweeps</Text>
          </StackLayout>
        </Card>
        <Card>
          <StackLayout gap={1}>
            <Text color="secondary">Total group cash</Text>
            <Display3>{groupSummary.totalCashFormatted}.00</Display3>
            <Text color="secondary">
              {cashAccounts.length} accounts · {currencyTotals.length} currencies
            </Text>
          </StackLayout>
        </Card>
        <Card>
          <StackLayout gap={1}>
            <Text color="secondary">Next cut-off</Text>
            <Display3>{groupSummary.nextCutOff}</Display3>
            <Text color="secondary">{sweeps.length} sweeps planned today</Text>
          </StackLayout>
        </Card>
      </GridLayout>

      <StackLayout gap={1}>
        <H2>Shortfall ladder</H2>
        <Text color="secondary">
          Accounts below their minimum balance, ranked by gap in GBP. Surplus
          accounts in the same currency are listed as funding sources, so no FX
          is needed.
        </Text>
      </StackLayout>

      <TableContainer>
        <Table>
          <caption>Accounts below minimum balance, ranked by gap in GBP</caption>
          <THead>
            <TR>
              <TH>Rank</TH>
              <TH>Account below minimum</TH>
              <TH style={{ textAlign: "right" }}>Balance / minimum</TH>
              <TH style={{ textAlign: "right" }}>Gap</TH>
              <TH style={{ textAlign: "right" }}>Gap in GBP</TH>
              <TH>Same-currency funding sources</TH>
              <TH>Cut-off</TH>
              <TH>Action</TH>
            </TR>
          </THead>
          <TBody>
            {ladder.map((row, i) => {
              const a = row.account;
              const sources = sourcesFor(a);
              const funded = row.remaining === 0;
              const partly = !funded && row.remaining < row.gap;
              return (
                <TR key={a.id}>
                  <TD>
                    <Text styleAs="h3">{i + 1}</Text>
                  </TD>
                  <TD>
                    <StackLayout gap={0.5}>
                      <Text>
                        <strong>{a.entity}</strong>
                      </Text>
                      <Text color="secondary">
                        {a.accountName} {mask(a.maskedNumber)} · {a.bank}
                      </Text>
                      <Text color="secondary">As of {a.asOf}</Text>
                      {a.viewOnly && (
                        <StatusIndicator status="info" />
                      )}
                      {a.viewOnly && (
                        <Text color="secondary">
                          View-only for you: entity treasurer confirms incoming sweeps
                        </Text>
                      )}
                    </StackLayout>
                  </TD>
                  <TD style={{ textAlign: "right" }}>
                    <StackLayout gap={0.5}>
                      <Text>{a.balanceFormatted}</Text>
                      <Text color="secondary">min {a.minimumTargetFormatted}</Text>
                    </StackLayout>
                  </TD>
                  <TD style={{ textAlign: "right" }}>
                    <StackLayout gap={0.5}>
                      <Text>
                        <strong>{a.varianceFormatted}</strong>
                      </Text>
                      {row.remaining !== row.gap && (
                        <Text color="secondary">
                          Unfunded {fmt(a.currency, row.remaining)}
                        </Text>
                      )}
                    </StackLayout>
                  </TD>
                  <TD style={{ textAlign: "right" }}>
                    <Text>
                      <strong>{fmt("GBP", row.gapGbp)}</strong>
                    </Text>
                    {a.currency !== "GBP" && (
                      <Text color="secondary">@ {fxRate(a.currency).toFixed(4)}</Text>
                    )}
                  </TD>
                  <TD>
                    <StackLayout gap={1}>
                      {sources.length === 0 && (
                        <Text color="secondary">
                          No {a.currency} surplus — needs FX or short-term funding
                        </Text>
                      )}
                      {sources.map((s) => {
                        const avail = availableSurplus(s);
                        const covers = avail >= row.remaining;
                        return (
                          <StackLayout key={s.id} gap={0.5}>
                            <Text>
                              {s.accountName} {mask(s.maskedNumber)}
                            </Text>
                            <Text color="secondary">
                              {s.entity} · surplus {fmt(s.currency, avail)}
                            </Text>
                            <FlexLayout gap={1} align="center">
                              <StatusIndicator
                                status={funded ? "success" : covers ? "success" : "warning"}
                              />
                              <Text>
                                {funded
                                  ? "Gap funded"
                                  : covers
                                    ? "Covers full gap"
                                    : `Covers ${Math.round((avail / row.remaining) * 100)}% of gap`}
                                {s.viewOnly ? " · view-only source" : ""}
                              </Text>
                            </FlexLayout>
                          </StackLayout>
                        );
                      })}
                    </StackLayout>
                  </TD>
                  <TD>{a.sweepCutOff}</TD>
                  <TD>
                    <StackLayout gap={1} align="start">
                      <FlexLayout gap={1} align="center">
                        <StatusIndicator
                          status={funded ? "success" : partly ? "warning" : "error"}
                        />
                        <Text>
                          {funded ? "Funded" : partly ? "Partly funded" : "Unfunded"}
                        </Text>
                      </FlexLayout>
                      {!funded && (
                        <Button
                          sentiment="accented"
                          onClick={() => openSweep(a)}
                          aria-label={`Plan sweep to ${a.entity} ${a.accountName}`}
                        >
                          Plan sweep
                        </Button>
                      )}
                    </StackLayout>
                  </TD>
                </TR>
              );
            })}
          </TBody>
          <TFoot>
            <TR>
              <TD />
              <TD>
                <strong>Total</strong>
              </TD>
              <TD />
              <TD />
              <TD style={{ textAlign: "right" }}>
                <strong>{fmt("GBP", totalGapGbp)}</strong>
              </TD>
              <TD>Unfunded after planned sweeps: {fmt("GBP", totalRemainingGbp)}</TD>
              <TD />
              <TD />
            </TR>
          </TFoot>
        </Table>
      </TableContainer>

      {sweeps.length > 0 && (
        <StackLayout gap={1}>
          <H2>Planned sweeps</H2>
          <TableContainer>
            <Table>
              <caption>Sweeps queued for the funding desk</caption>
              <THead>
                <TR>
                  <TH>From</TH>
                  <TH>To</TH>
                  <TH style={{ textAlign: "right" }}>Amount</TH>
                  <TH>Audit reason</TH>
                  <TH>Action</TH>
                </TR>
              </THead>
              <TBody>
                {sweeps.map((s) => {
                  const from = accountById(s.sourceId);
                  const to = accountById(s.targetId);
                  const reason = sweepReasons.find((r) => r.id === s.reasonId);
                  if (!from || !to) return null;
                  return (
                    <TR key={s.id}>
                      <TD>{accountLabel(from)}</TD>
                      <TD>{accountLabel(to)}</TD>
                      <TD style={{ textAlign: "right" }}>{fmt(from.currency, s.amount)}</TD>
                      <TD>
                        {reason?.label}
                        {s.note ? ` — ${s.note}` : ""}
                      </TD>
                      <TD>
                        <Button
                          appearance="transparent"
                          onClick={() => removeSweep(s.id)}
                          aria-label={`Cancel sweep from ${from.accountName} to ${to.accountName}`}
                        >
                          Cancel
                        </Button>
                      </TD>
                    </TR>
                  );
                })}
              </TBody>
            </Table>
          </TableContainer>
        </StackLayout>
      )}

      <StackLayout gap={1}>
        <H2>Other accounts at or above minimum</H2>
        <Text color="secondary">
          Surpluses in currencies with no shortfall today can be swept to
          concentration accounts.
        </Text>
      </StackLayout>
      <TableContainer>
        <Table>
          <caption>Accounts at or above their minimum balance</caption>
          <THead>
            <TR>
              <TH>Account</TH>
              <TH>Currency</TH>
              <TH style={{ textAlign: "right" }}>Balance</TH>
              <TH style={{ textAlign: "right" }}>Available above minimum</TH>
              <TH style={{ textAlign: "right" }}>In GBP</TH>
              <TH>Status</TH>
              <TH>Cut-off</TH>
            </TR>
          </THead>
          <TBody>
            {[...surplusAccounts]
              .sort(
                (x, y) =>
                  availableSurplus(y) * fxRate(y.currency) -
                  availableSurplus(x) * fxRate(x.currency),
              )
              .map((a) => {
                const avail = availableSurplus(a);
                return (
                  <TR key={a.id}>
                    <TD>
                      <StackLayout gap={0.5}>
                        <Text>{a.entity}</Text>
                        <Text color="secondary">
                          {a.accountName} {mask(a.maskedNumber)} · {a.bank}
                          {a.viewOnly ? " · view-only" : ""}
                        </Text>
                      </StackLayout>
                    </TD>
                    <TD>{a.currency}</TD>
                    <TD style={{ textAlign: "right" }}>{a.balanceFormatted}</TD>
                    <TD style={{ textAlign: "right" }}>{fmt(a.currency, avail)}</TD>
                    <TD style={{ textAlign: "right" }}>
                      {fmt("GBP", avail * fxRate(a.currency))}
                    </TD>
                    <TD>
                      <FlexLayout gap={1} align="center">
                        <StatusIndicator status={a.status === "surplus" ? "success" : "info"} />
                        <Text>
                          {a.status === "surplus"
                            ? shortfallCurrencies.has(a.currency)
                              ? "Surplus · funding source"
                              : "Surplus"
                            : "On target"}
                        </Text>
                      </FlexLayout>
                    </TD>
                    <TD>{a.sweepCutOff}</TD>
                  </TR>
                );
              })}
          </TBody>
        </Table>
      </TableContainer>

      <H2>Position by currency</H2>
      <TableContainer>
        <Table>
          <caption>Group cash by currency with GBP equivalent</caption>
          <THead>
            <TR>
              <TH>Currency</TH>
              <TH style={{ textAlign: "right" }}>Accounts</TH>
              <TH style={{ textAlign: "right" }}>Total balance</TH>
              <TH style={{ textAlign: "right" }}>Net vs minimum</TH>
              <TH style={{ textAlign: "right" }}>FX rate to GBP</TH>
              <TH style={{ textAlign: "right" }}>GBP equivalent</TH>
            </TR>
          </THead>
          <TBody>
            {currencyTotals.map((c) => (
              <TR key={c.currency}>
                <TD>{c.currency}</TD>
                <TD style={{ textAlign: "right" }}>{c.accountCount}</TD>
                <TD style={{ textAlign: "right" }}>{c.totalFormatted}.00</TD>
                <TD style={{ textAlign: "right" }}>{c.netVarianceFormatted}.00</TD>
                <TD style={{ textAlign: "right" }}>{c.fxRateToGBP}</TD>
                <TD style={{ textAlign: "right" }}>{c.gbpEquivalentFormatted}.00</TD>
              </TR>
            ))}
          </TBody>
          <TFoot>
            <TR>
              <TD>
                <strong>Group total</strong>
              </TD>
              <TD style={{ textAlign: "right" }}>{cashAccounts.length}</TD>
              <TD />
              <TD />
              <TD />
              <TD style={{ textAlign: "right" }}>
                <strong>{groupSummary.totalCashFormatted}.00</strong>
              </TD>
            </TR>
          </TFoot>
        </Table>
      </TableContainer>

      <Dialog
        open={dialogTarget !== null}
        onOpenChange={(open) => {
          if (!open) closeDialog();
        }}
        size="medium"
      >
        <DialogHeader header="Plan sweep" />
        <DialogContent>
          {dialogTarget && (
            <StackLayout gap={2}>
              <StackLayout gap={0.5}>
                <Text color="secondary">To</Text>
                <Text>
                  <strong>{accountLabel(dialogTarget)}</strong>
                </Text>
                <Text color="secondary">
                  Unfunded gap{" "}
                  {fmt(
                    dialogTarget.currency,
                    Math.max(0, Math.abs(dialogTarget.variance) - sweptIn(dialogTarget.id)),
                  )}{" "}
                  · cut-off {dialogTarget.sweepCutOff}
                </Text>
                {dialogTarget.viewOnly && (
                  <Text color="secondary">
                    This account is view-only for you. The sweep is debited from
                    the source; the entity treasurer will be notified.
                  </Text>
                )}
              </StackLayout>

              <FormField validationStatus={submitted && sourceError ? "error" : undefined}>
                <FormFieldLabel>From (same-currency surplus)</FormFieldLabel>
                <Dropdown
                  selected={sourceId ? [sourceId] : []}
                  onSelectionChange={(_e, sel) => setSourceId(sel[0] ?? "")}
                  valueToString={(v) => {
                    const s = accountById(v);
                    return s ? `${s.accountName} ${mask(s.maskedNumber)}` : "";
                  }}
                  placeholder="Choose a source account"
                >
                  {dialogSources.map((s) => (
                    <Option value={s.id} key={s.id}>
                      {s.entity} · {s.accountName} {mask(s.maskedNumber)} — available{" "}
                      {fmt(s.currency, availableSurplus(s))}
                    </Option>
                  ))}
                </Dropdown>
                {submitted && sourceError && (
                  <FormFieldHelperText>{sourceError}</FormFieldHelperText>
                )}
                {dialogSources.length === 0 && (
                  <FormFieldHelperText>
                    No sweepable {dialogTarget.currency} surplus. Contact the funding
                    desk for short-term funding.
                  </FormFieldHelperText>
                )}
              </FormField>

              <FormField validationStatus={submitted && amountError ? "error" : undefined}>
                <FormFieldLabel>Amount ({dialogTarget.currency})</FormFieldLabel>
                <Input
                  value={amountText}
                  onChange={(e) => setAmountText((e.target as HTMLInputElement).value)}
                />
                <FormFieldHelperText>
                  {submitted && amountError
                    ? amountError
                    : source
                      ? `Available from source: ${fmt(source.currency, availableSurplus(source))}`
                      : "Enter the amount to sweep"}
                </FormFieldHelperText>
              </FormField>

              <FormField validationStatus={submitted && reasonError ? "error" : undefined}>
                <FormFieldLabel>Audit reason</FormFieldLabel>
                <Dropdown
                  selected={reasonId ? [reasonId] : []}
                  onSelectionChange={(_e, sel) => setReasonId(sel[0] ?? "")}
                  valueToString={(v) => sweepReasons.find((r) => r.id === v)?.label ?? ""}
                  placeholder="Choose a reason"
                >
                  {sweepReasons.map((r) => (
                    <Option value={r.id} key={r.id}>
                      {r.label}
                    </Option>
                  ))}
                </Dropdown>
                <FormFieldHelperText>
                  {submitted && reasonError
                    ? reasonError
                    : "Recorded in the sweep audit trail"}
                </FormFieldHelperText>
              </FormField>

              <FormField validationStatus={submitted && noteError ? "error" : undefined}>
                <FormFieldLabel>
                  Note{reasonId === "reason-05" ? " (required)" : " (optional)"}
                </FormFieldLabel>
                <MultilineInput
                  value={note}
                  onChange={(e) =>
                    setNote((e.target as unknown as HTMLTextAreaElement).value)
                  }
                />
                {submitted && noteError && (
                  <FormFieldHelperText>{noteError}</FormFieldHelperText>
                )}
              </FormField>
            </StackLayout>
          )}
        </DialogContent>
        <DialogActions>
          <FlexLayout gap={1}>
            <Button appearance="bordered" sentiment="accented" onClick={closeDialog}>
              Cancel
            </Button>
            <Button sentiment="accented" onClick={confirmSweep}>
              Queue sweep
            </Button>
          </FlexLayout>
        </DialogActions>
      </Dialog>
    </StackLayout>
  );
}

