export type CurrencyCode = 'GBP' | 'EUR' | 'USD' | 'SEK' | 'PLN' | 'CHF';
export type PositionStatus = 'shortfall' | 'on-target' | 'surplus';

export interface CashAccount {
  readonly id: string;
  readonly entity: string;
  readonly accountName: string;
  readonly maskedNumber: string;
  readonly bank: string;
  readonly currency: CurrencyCode;
  readonly balance: number;
  readonly balanceFormatted: string;
  readonly minimumTarget: number;
  readonly minimumTargetFormatted: string;
  readonly variance: number;
  readonly varianceFormatted: string;
  readonly status: PositionStatus;
  readonly viewOnly: boolean;
  readonly sweepCutOff: string;
  readonly asOf: string;
}

export interface CurrencyTotal {
  readonly currency: CurrencyCode;
  readonly totalFormatted: string;
  readonly netVarianceFormatted: string;
  readonly fxRateToGBP: string;
  readonly gbpEquivalentFormatted: string;
  readonly accountCount: number;
}

export interface GroupSummary {
  readonly asOf: string;
  readonly dataLagNote: string;
  readonly reportingCurrency: CurrencyCode;
  readonly totalCashFormatted: string;
  readonly totalShortfallFormatted: string;
  readonly totalSurplusFormatted: string;
  readonly accountsInShortfall: number;
  readonly nextCutOff: string;
}

export interface SweepReason {
  readonly id: string;
  readonly label: string;
}

export const groupSummary: GroupSummary = {
  asOf: '16 Oct 2026, 08:47 BST',
  dataLagNote: 'Intraday balances may lag by up to 15 minutes',
  reportingCurrency: 'GBP',
  totalCashFormatted: 'GBP 16,743,664',
  totalShortfallFormatted: 'GBP 1,438,450',
  totalSurplusFormatted: 'GBP 9,874,100',
  accountsInShortfall: 3,
  nextCutOff: '14:00 CET'
};

