  { id: 'acc-01', entity: 'Meridian Retail UK Ltd', accountName: 'Main current account', maskedNumber: '****4821', bank: 'Northbridge Bank', currency: 'GBP', balance: 4820000, balanceFormatted: 'GBP 4,820,000.00', minimumTarget: 3000000, minimumTargetFormatted: 'GBP 3,000,000.00', variance: 1820000, varianceFormatted: '+GBP 1,820,000.00', status: 'surplus', viewOnly: false, sweepCutOff: '16:00 BST', asOf: '16 Oct 2026, 08:45 BST' },
