  { id: 'acc-03', entity: 'Meridian Distribution GmbH', accountName: 'Operating account', maskedNumber: '****7705', bank: 'Rheinland Bank AG', currency: 'EUR', balance: 2310500, balanceFormatted: 'EUR 2,310,500.00', minimumTarget: 1500000, minimumTargetFormatted: 'EUR 1,500,000.00', variance: 810500, varianceFormatted: '+EUR 810,500.00', status: 'surplus', viewOnly: false, sweepCutOff: '15:00 CEST', asOf: '16 Oct 2026, 08:41 BST' },
  { id: 'acc-04', entity: 'Meridian France SAS', accountName: 'Store takings account', maskedNumber: '****3092', bank: 'Banque Lumiere', currency: 'EUR', balance: 418250, balanceFormatted: 'EUR 418,250.00', minimumTarget: 900000, minimumTargetFormatted: 'EUR 900,000.00', variance: -481750, varianceFormatted: '-EUR 481,750.00', status: 'shortfall', viewOnly: true, sweepCutOff: '15:00 CEST', asOf: '16 Oct 2026, 08:38 BST' },
  { id: 'acc-05', entity: 'Meridian Iberia SL', accountName: 'Operating account', maskedNumber: '****6618', bank: 'Banco Meseta', currency: 'EUR', balance: 1052000, balanceFormatted: 'EUR 1,052,000.00', minimumTarget: 1000000, minimumTargetFormatted: 'EUR 1,000,000.00', variance: 52000, varianceFormatted: '+EUR 52,000.00', status: 'on-target', viewOnly: false, sweepCutOff: '15:00 CEST', asOf: '16 Oct 2026, 08:41 BST' },
  { id: 'acc-06', entity: 'Meridian Retail US Inc', accountName: 'Concentration account', maskedNumber: '****9140', bank: 'Hudson Trust', currency: 'USD', balance: 6745300, balanceFormatted: 'USD 6,745,300.00', minimumTarget: 4000000, minimumTargetFormatted: 'USD 4,000,000.00', variance: 2745300, varianceFormatted: '+USD 2,745,300.00', status: 'surplus', viewOnly: false, sweepCutOff: '16:00 EDT', asOf: '16 Oct 2026, 08:44 BST' },
  { id: 'acc-07', entity: 'Meridian US Operations LLC', accountName: 'Disbursement account', maskedNumber: '****9152', bank: 'Hudson Trust', currency: 'USD', balance: 1130900, balanceFormatted: 'USD 1,130,900.00', minimumTarget: 1500000, minimumTargetFormatted: 'USD 1,500,000.00', variance: -369100, varianceFormatted: '-USD 369,100.00', status: 'shortfall', viewOnly: false, sweepCutOff: '16:00 EDT', asOf: '16 Oct 2026, 08:44 BST' },
