];

export const currencyTotals: readonly CurrencyTotal[] = [
  { currency: 'GBP', totalFormatted: 'GBP 5,432,400', netVarianceFormatted: '+GBP 1,232,400', fxRateToGBP: '1.0000', gbpEquivalentFormatted: 'GBP 5,432,400', accountCount: 2 },
  { currency: 'EUR', totalFormatted: 'EUR 3,780,750', netVarianceFormatted: '+EUR 380,750', fxRateToGBP: '0.8650', gbpEquivalentFormatted: 'GBP 3,270,349', accountCount: 3 },
  { currency: 'USD', totalFormatted: 'USD 7,876,200', netVarianceFormatted: '+USD 2,376,200', fxRateToGBP: '0.7720', gbpEquivalentFormatted: 'GBP 6,080,427', accountCount: 2 },
  { currency: 'SEK', totalFormatted: 'SEK 8,940,000', netVarianceFormatted: '+SEK 2,940,000', fxRateToGBP: '0.0740', gbpEquivalentFormatted: 'GBP 661,560', accountCount: 1 },
  { currency: 'PLN', totalFormatted: 'PLN 3,120,800', netVarianceFormatted: '+PLN 120,800', fxRateToGBP: '0.2000', gbpEquivalentFormatted: 'GBP 624,160', accountCount: 1 },
  { currency: 'CHF', totalFormatted: 'CHF 745,600', netVarianceFormatted: '+CHF 245,600', fxRateToGBP: '0.9050', gbpEquivalentFormatted: 'GBP 674,768', accountCount: 1 }
];

export const sweepReasons: readonly SweepReason[] = [
  { id: 'reason-01', label: 'Fund payroll shortfall' },
  { id: 'reason-02', label: 'Cover minimum balance breach' },
  { id: 'reason-03', label: 'Sweep surplus to concentration account' },
  { id: 'reason-04', label: 'Avoid overdraft interest' },
  { id: 'reason-05', label: 'Other (note required)' }
];

