import { useMemo, useState, type SyntheticEvent } from "react";
import {
  Banner,
  BannerContent,
  Button,
  Card,
  Dialog,
  DialogActions,
  DialogContent,
  DialogHeader,
  Dropdown,
  FlexLayout,
  FormField,
  FormFieldHelperText,
  FormFieldLabel,
  GridLayout,
  H1,
  H2,
  H3,
  Input,
  Option,
  StackLayout,
  StatusIndicator,
  Table,
  TableContainer,
  TBody,
  TD,
  TH,
  THead,
  Text,
  ToggleButton,
  ToggleButtonGroup,
  TR,
} from "@salt-ds/core";
import {
  accounts,
  currencyPositions,
  fundingOptions,
  positionMeta,
  sweepReasons,
  type CashAccount,
  type CurrencyCode,
  type PositionStatus,
} from "./data";

type Filter = CurrencyCode | "ALL";
type View = "all" | "shortfall";

interface DraftInstruction {
  id: string;
  kind: "Funding" | "Sweep";
  accountId: string;
  accountLabel: string;
  counterparty: string;
  amount: string;
  reason: string;
  createdAt: string;
}

const statusRank: Record<PositionStatus, number> = {
  shortfall: 0,
  surplus: 1,
  "on target": 2,
};

const statusIndicator: Record<PositionStatus, "error" | "info" | "success"> = {
  shortfall: "error",
  surplus: "info",
  "on target": "success",
};

const statusLabel: Record<PositionStatus, string> = {
  shortfall: "Shortfall",
  surplus: "Surplus",
  "on target": "On target",
};

const mask = (n: string) => n.replace(/\*/g, "•");

const fmt = (ccy: CurrencyCode, value: number) =>
  `${ccy} ${value.toLocaleString("en-GB", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  })}`;

const accountLabel = (a: CashAccount) =>
  `${a.entity} · ${a.accountName} ${mask(a.maskedNumber)}`;

function StatusText({ status }: { status: PositionStatus }) {
  return (
    <FlexLayout gap={1} align="center">
      <StatusIndicator status={statusIndicator[status]} aria-hidden />
      <Text>{statusLabel[status]}</Text>
    </FlexLayout>
  );
}

export default function CashPositionBoard() {
  const [filter, setFilter] = useState<Filter>("ALL");
  const [view, setView] = useState<View>("all");
  const [actionAccount, setActionAccount] = useState<CashAccount | null>(null);
  const [counterparty, setCounterparty] = useState<string[]>([]);
  const [amount, setAmount] = useState("");
  const [reason, setReason] = useState<string[]>([]);
  const [submitted, setSubmitted] = useState(false);
  const [drafts, setDrafts] = useState<DraftInstruction[]>([]);
  const [lastDraft, setLastDraft] = useState<DraftInstruction | null>(null);

  const rankedCurrencies = useMemo(() => {
    return currencyPositions
      .map((c) => {
        const ccyAccounts = accounts.filter((a) => a.currency === c.currency);
        const short = ccyAccounts.filter((a) => a.status === "shortfall");
        const gap = short.reduce((s, a) => s + Math.abs(a.variance), 0);
        const rank =
          c.status === "shortfall" ? 0 : short.length > 0 ? 1 : c.status === "surplus" ? 2 : 3;
        return { ...c, shortCount: short.length, gap, rank };
      })
      .sort((a, b) => a.rank - b.rank || b.shortCount - a.shortCount || a.variance - b.variance);
  }, []);

  const shortAccounts = accounts.filter((a) => a.status === "shortfall");
  const shortCurrencies = rankedCurrencies.filter((c) => c.shortCount > 0);
  const earliestShortCutOff = [...shortAccounts].sort((a, b) =>
    a.sweepCutOff.localeCompare(b.sweepCutOff),
  )[0];

  const visibleAccounts = useMemo(() => {
    return accounts
      .filter((a) => filter === "ALL" || a.currency === filter)
      .filter((a) => view === "all" || a.status === "shortfall")
      .slice()
      .sort((a, b) => statusRank[a.status] - statusRank[b.status] || a.variance - b.variance);
  }, [filter, view]);

  const openAction = (account: CashAccount) => {
    setActionAccount(account);
    setCounterparty([]);
    setAmount(
      Math.abs(account.variance).toLocaleString("en-GB", {
        minimumFractionDigits: 2,
        maximumFractionDigits: 2,
      }),
    );
    setReason([]);
    setSubmitted(false);
  };

  const closeAction = () => setActionAccount(null);

  const isFunding = actionAccount?.status === "shortfall";

  const counterpartyOptions = useMemo(() => {
    if (!actionAccount) return [] as { id: string; label: string }[];
    const sameCcy = accounts.filter(
      (a) =>
        a.currency === actionAccount.currency &&
        a.id !== actionAccount.id &&
        a.access === "manage",
    );
    if (isFunding) {
      const fromSurplus = sameCcy
        .filter((a) => a.status === "surplus")
        .map((a) => ({
          id: a.id,
          label: `Sweep from ${accountLabel(a)} (surplus ${a.varianceFormatted})`,
        }));
      const facilities = fundingOptions
        .filter((f) => f.currency === actionAccount.currency)
        .map((f) => ({
          id: f.id,
          label: `${f.label} · up to ${f.maxAmountFormatted} · ${f.indicativeRate} · cut-off ${f.cutOff}`,
        }));
      return [...fromSurplus, ...facilities];
    }
    return sameCcy
      .slice()
      .sort((a, b) => statusRank[a.status] - statusRank[b.status])
      .map((a) => ({
        id: a.id,
        label: `To ${accountLabel(a)} (${statusLabel[a.status].toLowerCase()} ${a.varianceFormatted})`,
      }));
  }, [actionAccount, isFunding]);

  const parsedAmount = parseFloat(amount.replace(/,/g, ""));
  const amountError = !amount || Number.isNaN(parsedAmount) || parsedAmount <= 0;
  const counterpartyError = counterparty.length === 0;
  const reasonError = reason.length === 0;

  const submitAction = () => {
    setSubmitted(true);
    if (!actionAccount || amountError || counterpartyError || reasonError) return;
    const cp = counterpartyOptions.find((o) => o.id === counterparty[0]);
    const draft: DraftInstruction = {
      id: `draft-${drafts.length + 1}`,
      kind: isFunding ? "Funding" : "Sweep",
      accountId: actionAccount.id,
      accountLabel: accountLabel(actionAccount),
      counterparty: cp ? cp.label : "",
      amount: fmt(actionAccount.currency, parsedAmount),
      reason: reason[0],
      createdAt: `${positionMeta.asOfDate}, ${positionMeta.asOfTime}`,
    };
    setDrafts((d) => [draft, ...d]);
    setLastDraft(draft);
    setActionAccount(null);
  };

  const draftedIds = new Set(drafts.map((d) => d.accountId));

  const onViewChange = (event: SyntheticEvent<HTMLButtonElement>) => {
    setView(event.currentTarget.value as View);
  };

  const tableHeading =
    filter === "ALL" ? "Accounts across all currencies" : `Accounts in ${filter}`;

  return (
    <StackLayout gap={3}>
      <StackLayout gap={1}>
        <H1>Cash position</H1>
        <Text color="secondary">
          {positionMeta.groupName} · {positionMeta.entityCount} entities ·{" "}
          {positionMeta.accountCount} accounts · Balances as of {positionMeta.asOfDate},{" "}
          {positionMeta.asOfTime}
        </Text>
      </StackLayout>

      <Banner status="warning">
        <BannerContent>
          {shortAccounts.length} accounts are below target in {shortCurrencies.length}{" "}
          currencies. Earliest cut-off: {earliestShortCutOff?.sweepCutOff} (
          {earliestShortCutOff?.currency}, {earliestShortCutOff?.entity}).{" "}
          {positionMeta.dataLagNote}.
        </BannerContent>
      </Banner>

      {lastDraft && (
        <Banner status="success">
          <BannerContent>
            {lastDraft.kind} instruction drafted for {lastDraft.amount} on{" "}
            {lastDraft.accountLabel}. Reason recorded: {lastDraft.reason}. Send it to the
            funding desk to release.
          </BannerContent>
        </Banner>
      )}

      <StackLayout gap={2}>
        <FlexLayout justify="space-between" align="end" wrap gap={2}>
          <StackLayout gap={0.5}>
            <H2>Position by currency</H2>
            <Text color="secondary">
              Ranked shortfalls first. Select a currency to see the accounts behind it.
            </Text>
          </StackLayout>
          <Button
            appearance={filter === "ALL" ? "solid" : "bordered"}
            sentiment={filter === "ALL" ? "accented" : "neutral"}
            aria-pressed={filter === "ALL"}
            onClick={() => setFilter("ALL")}
          >
            All currencies
          </Button>
        </FlexLayout>

        <GridLayout columns={{ xs: 1, sm: 2, md: 3, lg: 6 }} gap={2}>
          {rankedCurrencies.map((c) => {
            const selected = filter === c.currency;
            const netStatus = c.status;
            return (
              <Card key={c.currency} accent={selected ? "top" : undefined}>
                <StackLayout gap={1}>
                  <FlexLayout justify="space-between" align="center">
                    <H3>{c.currency}</H3>
                    <Text color="secondary" styleAs="label">
                      {c.accountCount} {c.accountCount === 1 ? "account" : "accounts"}
                    </Text>
                  </FlexLayout>
                  {c.shortCount > 0 ? (
                    <StackLayout gap={0.5}>
                      <FlexLayout gap={1} align="center">
                        <StatusIndicator status="error" aria-hidden />
                        <Text>
                          <strong>
                            {c.shortCount} {c.shortCount === 1 ? "account" : "accounts"} short
                          </strong>
                        </Text>
                      </FlexLayout>
                      <Text color="error">Gap {fmt(c.currency, c.gap)}</Text>
                    </StackLayout>
                  ) : (
                    <StackLayout gap={0.5}>
                      <StatusText status={netStatus} />
                      <Text color="secondary">No account gaps</Text>
                    </StackLayout>
                  )}
                  <StackLayout gap={0}>
                    <Text styleAs="label" color="secondary">
                      Net vs target ({statusLabel[netStatus].toLowerCase()})
                    </Text>
                    <Text color={c.variance < 0 ? "error" : "primary"}>
                      {c.varianceFormatted}
                    </Text>
                  </StackLayout>
                  <StackLayout gap={0}>
                    <Text styleAs="label" color="secondary">
                      Available / target
                    </Text>
                    <Text styleAs="label">{c.availableFormatted}</Text>
                    <Text styleAs="label" color="secondary">
                      {c.targetFormatted}
                    </Text>
                  </StackLayout>
                  <Button
                    appearance={selected ? "solid" : "bordered"}
                    sentiment={selected ? "accented" : "neutral"}
                    aria-pressed={selected}
                    onClick={() => setFilter(selected ? "ALL" : c.currency)}
                  >
                    {selected ? "Showing accounts" : "Show accounts"}
                  </Button>
                </StackLayout>
              </Card>
            );
          })}
        </GridLayout>
      </StackLayout>

      <StackLayout gap={2}>
        <FlexLayout justify="space-between" align="end" wrap gap={2}>
          <StackLayout gap={0.5}>
            <H2>{tableHeading}</H2>
            <Text color="secondary">
              Sorted by gap to target, largest shortfall first. View-only accounts can't be
              swept or funded from here.
            </Text>
          </StackLayout>
          <FormField>
            <FormFieldLabel>Show</FormFieldLabel>
            <ToggleButtonGroup value={view} onChange={onViewChange}>
              <ToggleButton value="all">All accounts</ToggleButton>
              <ToggleButton value="shortfall">Shortfalls only</ToggleButton>
            </ToggleButtonGroup>
          </FormField>
        </FlexLayout>

        <TableContainer>
          <Table>
            <caption>
              {tableHeading}, {visibleAccounts.length} shown
            </caption>
            <THead>
              <TR>
                <TH>Status</TH>
                <TH>Entity and account</TH>
                <TH>Bank</TH>
                <TH style={{ textAlign: "right" }}>Available</TH>
                <TH style={{ textAlign: "right" }}>Target</TH>
                <TH style={{ textAlign: "right" }}>Variance</TH>
                <TH>Sweep cut-off</TH>
                <TH>Balance as of</TH>
                <TH>Action</TH>
              </TR>
            </THead>
            <TBody>
              {visibleAccounts.length === 0 && (
                <TR>
                  <TD colSpan={9}>
                    <Text color="secondary">No accounts below target in this currency.</Text>
                  </TD>
                </TR>
              )}
              {visibleAccounts.map((a) => {
                const drafted = draftedIds.has(a.id);
                return (
                  <TR key={a.id}>
                    <TD>
                      <StatusText status={a.status} />
                    </TD>
                    <TD>
                      <StackLayout gap={0}>
                        <Text>{a.entity}</Text>
                        <Text styleAs="label" color="secondary">
                          {a.accountName} {mask(a.maskedNumber)} · {a.currency}
                        </Text>
                      </StackLayout>
                    </TD>
                    <TD>{a.bank}</TD>
                    <TD style={{ textAlign: "right" }}>{a.availableFormatted}</TD>
                    <TD style={{ textAlign: "right" }}>{a.targetFormatted}</TD>
                    <TD style={{ textAlign: "right" }}>
                      <Text color={a.status === "shortfall" ? "error" : "primary"}>
                        {a.varianceFormatted}
                      </Text>
                    </TD>
                    <TD>{a.sweepCutOff}</TD>
                    <TD>
                      <Text styleAs="label" color="secondary">
                        {a.balanceAsOf}
                      </Text>
                    </TD>
                    <TD>
                      {a.access === "view-only" ? (
                        <Text styleAs="label" color="secondary">
                          View only · contact entity treasurer
                        </Text>
                      ) : drafted ? (
                        <FlexLayout gap={1} align="center">
                          <StatusIndicator status="success" aria-hidden />
                          <Text styleAs="label">Instruction drafted</Text>
                        </FlexLayout>
                      ) : a.status === "shortfall" ? (
                        <Button sentiment="accented" onClick={() => openAction(a)}>
                          Fund gap
                        </Button>
                      ) : a.status === "surplus" ? (
                        <Button appearance="bordered" onClick={() => openAction(a)}>
                          Sweep surplus
                        </Button>
                      ) : (
                        <Text styleAs="label" color="secondary">
                          No action needed
                        </Text>
                      )}
                    </TD>
                  </TR>
                );
              })}
            </TBody>
          </Table>
        </TableContainer>
      </StackLayout>

      {drafts.length > 0 && (
        <StackLayout gap={2}>
          <H2>Drafted instructions</H2>
          <TableContainer>
            <Table>
              <caption>Instructions drafted this session, awaiting funding desk</caption>
              <THead>
                <TR>
                  <TH>Type</TH>
                  <TH>Account</TH>
                  <TH>Source or destination</TH>
                  <TH style={{ textAlign: "right" }}>Amount</TH>
                  <TH>Audit reason</TH>
                  <TH>Drafted</TH>
                </TR>
              </THead>
              <TBody>
                {drafts.map((d) => (
                  <TR key={d.id}>
                    <TD>{d.kind}</TD>
                    <TD>{d.accountLabel}</TD>
                    <TD>{d.counterparty}</TD>
                    <TD style={{ textAlign: "right" }}>{d.amount}</TD>
                    <TD>{d.reason}</TD>
                    <TD>{d.createdAt}</TD>
                  </TR>
                ))}
              </TBody>
            </Table>
          </TableContainer>
        </StackLayout>
      )}

      <Dialog
        open={actionAccount !== null}
        onOpenChange={(open) => {
          if (!open) closeAction();
        }}
        size="medium"
      >
        <DialogHeader
          header={isFunding ? "Fund account shortfall" : "Sweep account surplus"}
        />
        <DialogContent>
          {actionAccount && (
            <StackLayout gap={2}>
              <StackLayout gap={0.5}>
                <Text>
                  <strong>{accountLabel(actionAccount)}</strong>
                </Text>
                <Text color="secondary">
                  Available {actionAccount.availableFormatted} · Target{" "}
                  {actionAccount.targetFormatted} · Variance{" "}
                  {actionAccount.varianceFormatted} · Cut-off {actionAccount.sweepCutOff}
                </Text>
              </StackLayout>

              <FormField
                validationStatus={submitted && counterpartyError ? "error" : undefined}
              >
                <FormFieldLabel>
                  {isFunding ? "Funding source" : "Sweep destination"}
                </FormFieldLabel>
                <Dropdown
                  selected={counterparty}
                  onSelectionChange={(_e, value) => setCounterparty(value)}
                  valueToString={(id) =>
                    counterpartyOptions.find((o) => o.id === id)?.label ?? ""
                  }
                >
                  {counterpartyOptions.map((o) => (
                    <Option key={o.id} value={o.id}>
                      {o.label}
                    </Option>
                  ))}
                </Dropdown>
                <FormFieldHelperText>
                  {counterpartyOptions.length === 0
                    ? `No ${actionAccount.currency} source you manage. Raise with the funding desk.`
                    : submitted && counterpartyError
                      ? "Choose where the funds come from or go to."
                      : isFunding
                        ? "Surplus accounts in the same currency are listed before facilities."
                        : "Accounts with shortfalls are listed first."}
                </FormFieldHelperText>
              </FormField>

              <FormField validationStatus={submitted && amountError ? "error" : undefined}>
                <FormFieldLabel>Amount ({actionAccount.currency})</FormFieldLabel>
                <Input
                  value={amount}
                  onChange={(e) =>
                    setAmount((e.target as unknown as HTMLInputElement).value)
                  }
                />
                <FormFieldHelperText>
                  {submitted && amountError
                    ? "Enter an amount greater than zero."
                    : `Prefilled with the gap to target: ${fmt(
                        actionAccount.currency,
                        Math.abs(actionAccount.variance),
                      )}`}
                </FormFieldHelperText>
              </FormField>

              <FormField validationStatus={submitted && reasonError ? "error" : undefined}>
                <FormFieldLabel>Audit reason</FormFieldLabel>
                <Dropdown
                  selected={reason}
                  onSelectionChange={(_e, value) => setReason(value)}
                >
                  {sweepReasons.map((r) => (
                    <Option key={r} value={r} />
                  ))}
                </Dropdown>
                <FormFieldHelperText>
                  {submitted && reasonError
                    ? "Every sweep needs an audit reason."
                    : "Required. It's recorded on the audit trail."}
                </FormFieldHelperText>
              </FormField>
            </StackLayout>
          )}
        </DialogContent>
        <DialogActions>
          <Button appearance="bordered" onClick={closeAction}>
            Cancel
          </Button>
          <Button sentiment="accented" onClick={submitAction}>
            Draft instruction
          </Button>
        </DialogActions>
      </Dialog>
    </StackLayout>
  );
}

