export type CurrencyCode = 'GBP' | 'EUR' | 'USD' | 'CHF' | 'SEK' | 'PLN';
export type PositionStatus = 'shortfall' | 'on target' | 'surplus';
export type AccessLevel = 'manage' | 'view-only';

export interface CashAccount {
  readonly id: string;
  readonly entity: string;
  readonly accountName: string;
  readonly maskedNumber: string;
  readonly bank: string;
  readonly currency: CurrencyCode;
  readonly availableBalance: number;
  readonly availableFormatted: string;
  readonly targetBalance: number;
  readonly targetFormatted: string;
  readonly variance: number;
  readonly varianceFormatted: string;
  readonly status: PositionStatus;
  readonly access: AccessLevel;
  readonly sweepCutOff: string;
  readonly balanceAsOf: string;
}

export interface CurrencyPosition {
  readonly currency: CurrencyCode;
  readonly accountCount: number;
  readonly availableFormatted: string;
  readonly targetFormatted: string;
  readonly variance: number;
  readonly varianceFormatted: string;
  readonly status: PositionStatus;
}

export interface FundingOption {
  readonly id: string;
  readonly label: string;
  readonly currency: CurrencyCode;
  readonly maxAmountFormatted: string;
  readonly indicativeRate: string;
  readonly cutOff: string;
}

export interface PositionMeta {
  readonly asOfDate: string;
  readonly asOfTime: string;
  readonly dataLagNote: string;
  readonly groupName: string;
  readonly entityCount: number;
  readonly accountCount: number;
}

export const positionMeta: PositionMeta = {
  asOfDate: '16 Oct 2026',
  asOfTime: '08:47 BST',
  dataLagNote: 'Intraday balances can lag by up to 15 minutes',
  groupName: 'Meridian Retail Group',
  entityCount: 14,
  accountCount: 23,
};

export const accounts: readonly CashAccount[] = [
  { id: 'acc-001', entity: 'Meridian Retail UK Ltd', accountName: 'Operating', maskedNumber: '****4821', bank: 'Northbridge Bank', currency: 'GBP', availableBalance: 12480000, availableFormatted: 'GBP 12,480,000.00', targetBalance: 8000000, targetFormatted: 'GBP 8,000,000.00', variance: 4480000, varianceFormatted: '+GBP 4,480,000.00', status: 'surplus', access: 'manage', sweepCutOff: '15:30 BST', balanceAsOf: '16 Oct 2026, 08:41 BST' },
  { id: 'acc-002', entity: 'Meridian Retail UK Ltd', accountName: 'Payroll', maskedNumber: '****4833', bank: 'Northbridge Bank', currency: 'GBP', availableBalance: 1215400, availableFormatted: 'GBP 1,215,400.00', targetBalance: 2500000, targetFormatted: 'GBP 2,500,000.00', variance: -1284600, varianceFormatted: '-GBP 1,284,600.00', status: 'shortfall', access: 'manage', sweepCutOff: '15:30 BST', balanceAsOf: '16 Oct 2026, 08:41 BST' },
  { id: 'acc-003', entity: 'Meridian Retail Germany GmbH', accountName: 'Operating', maskedNumber: '****7716', bank: 'Rheinland Bank', currency: 'EUR', availableBalance: 6320750, availableFormatted: 'EUR 6,320,750.00', targetBalance: 4000000, targetFormatted: 'EUR 4,000,000.00', variance: 2320750, varianceFormatted: '+EUR 2,320,750.00', status: 'surplus', access: 'manage', sweepCutOff: '16:00 CEST', balanceAsOf: '16 Oct 2026, 08:38 BST' },
