import { useMemo, useState } from "react";
import {
  Accordion,
  AccordionGroup,
  AccordionHeader,
  AccordionPanel,
  Button,
  Divider,
  FlexLayout,
  H2,
  H3,
  SplitLayout,
  StackLayout,
  StatusIndicator,
  Switch,
  Text,
} from "@salt-ds/core";
import {
  onboardingCase,
  requirements,
  type ActorRole,
  type OnboardingRequirement,
  type RequirementStatus,
} from "./data";

type Status = "error" | "warning" | "info" | "success";

const statusTone: Record<RequirementStatus, Status> = {
  Rejected: "error",
  "Not requested": "warning",
  Requested: "info",
  Received: "info",
  "In review": "info",
  Complete: "success",
};

const contactRule: Record<ActorRole, { tone: Status; text: string }> = {
  Client: { tone: "success", text: "Chase directly: client contact allowed" },
  "Relationship banker": { tone: "info", text: "Chase the banker internally" },
  "Onboarding analyst": { tone: "info", text: "Your action" },
  "Second analyst": {
    tone: "warning",
    text: "Request only once all other evidence is complete",
  },
  "Sanctions screening team": {
    tone: "error",
    text: "Do not contact the client about screening. Follow up with the desk only",
  },
};

const sortItems = (a: OnboardingRequirement, b: OnboardingRequirement) => {
  if (a.blocking !== b.blocking) return a.blocking ? -1 : 1;
  const ac = a.status === "Complete" ? 1 : 0;
  const bc = b.status === "Complete" ? 1 : 0;
  return ac - bc;
};

function RequirementRow({ item }: { item: OnboardingRequirement }) {
  return (
    <StackLayout gap={0.5}>
      <SplitLayout
        align="center"
        startItem={
          <Text>
            <strong>{item.label}</strong>
          </Text>
        }
        endItem={
          <FlexLayout gap={1} align="center">
            {item.blocking && item.status !== "Complete" && (
              <FlexLayout gap={0.5} align="center">
                <StatusIndicator status="error" aria-hidden />
                <Text styleAs="label" color="error">
                  Blocker
                </Text>
              </FlexLayout>
            )}
            <FlexLayout gap={0.5} align="center">
              <StatusIndicator status={statusTone[item.status]} aria-hidden />
              <Text styleAs="label">{item.status}</Text>
            </FlexLayout>
          </FlexLayout>
        }
      />
      <Text styleAs="label" color="secondary">
        {item.id} · {item.category} · {item.ownerName} · Requested{" "}
        {item.requestedOn ?? "not yet"} · Due {item.dueOn}
      </Text>
      <Text>{item.reason}</Text>
      <Text styleAs="label" color="secondary">
        Evidence: {item.evidenceRef ?? "None recorded"}
      </Text>
    </StackLayout>
  );
}

export default function OutstandingItemsByOwner() {
  const [showCompleted, setShowCompleted] = useState(false);
  const [chased, setChased] = useState<Record<string, string>>({});

  const outstanding = requirements.filter((r) => r.status !== "Complete");
  const blockers = outstanding.filter((r) => r.blocking);
  const otherBlockersOpen = blockers.some((r) => r.owner !== "Second analyst");

  const groups = useMemo(() => {
    const map = new Map<ActorRole, OnboardingRequirement[]>();
    requirements.forEach((r) => {
      if (!showCompleted && r.status === "Complete") return;
      const list = map.get(r.owner) ?? [];
      list.push(r);
      map.set(r.owner, list);
    });
    return Array.from(map.entries())
      .map(([owner, items]) => {
        const open = items.filter((i) => i.status !== "Complete");
        return {
          owner,
          items: [...items].sort(sortItems),
          open: open.length,
          blockers: open.filter((i) => i.blocking).length,
          names: Array.from(new Set(items.map((i) => i.ownerName))),
        };
      })
      .sort((a, b) => b.blockers - a.blockers || b.open - a.open);
  }, [showCompleted]);

  const actionFor = (owner: ActorRole) => {
    if (owner === "Onboarding analyst") return null;
    if (owner === "Second analyst") {
      return {
        label: "Request approval",
        disabled: otherBlockersOpen,
        hint: otherBlockersOpen
          ? `Available when the other ${blockers.length - 1} blockers are cleared`
          : undefined,
      };
    }
    if (owner === "Sanctions screening team")
      return { label: "Follow up with desk", disabled: false };
    return { label: "Log chase", disabled: false };
  };

  return (
    <StackLayout gap={3} style={{ maxWidth: "calc(var(--salt-size-base) * 30)" }}>
      <StackLayout gap={1}>
        <H2>Outstanding items by owner</H2>
        <Text color="secondary">
          {onboardingCase.caseId} · {onboardingCase.clientName} ·{" "}
          {onboardingCase.riskRating} risk
        </Text>
        <FlexLayout gap={3} wrap>
          <StackLayout gap={0}>
            <Text styleAs="label" color="secondary">
              Outstanding
            </Text>
            <Text styleAs="h3">{outstanding.length} of {requirements.length}</Text>
          </StackLayout>
          <StackLayout gap={0}>
            <Text styleAs="label" color="secondary">
              Blockers
            </Text>
            <FlexLayout gap={0.5} align="center">
              <StatusIndicator status="error" aria-hidden />
              <Text styleAs="h3">{blockers.length}</Text>
            </FlexLayout>
          </StackLayout>
          <StackLayout gap={0}>
            <Text styleAs="label" color="secondary">
              SLA
            </Text>
            <Text styleAs="h3">
              Day {onboardingCase.slaDay} of {onboardingCase.slaDays}
            </Text>
          </StackLayout>
          <StackLayout gap={0}>
            <Text styleAs="label" color="secondary">
              SLA due
            </Text>
            <Text styleAs="h3">
              {onboardingCase.slaDueOn}, {onboardingCase.cutOff}
            </Text>
          </StackLayout>
        </FlexLayout>
        <Switch
          label="Show completed items"
          checked={showCompleted}
          onChange={(e) => setShowCompleted(e.target.checked)}
        />
      </StackLayout>

      <AccordionGroup>
        {groups.map((g) => {
          const rule = contactRule[g.owner];
          const action = actionFor(g.owner);
          return (
            <Accordion
              key={g.owner}
              value={g.owner}
              defaultExpanded={g.blockers > 0}
            >
              <AccordionHeader>
                <StackLayout gap={0.5}>
                  <SplitLayout
                    align="baseline"
                    startItem={
                      <Text>
                        <strong>{g.owner}</strong>
                      </Text>
                    }
                    endItem={
                      <Text styleAs="label" color={g.blockers > 0 ? "error" : "secondary"}>
                        {g.blockers} blocker{g.blockers === 1 ? "" : "s"} · {g.open} open
                      </Text>
                    }
                  />
                  <Text styleAs="label" color="secondary">
                    {g.names.join(", ")}
                  </Text>
                </StackLayout>
              </AccordionHeader>
              <AccordionPanel>
                <StackLayout gap={2}>
                  <SplitLayout
                    align="center"
                    startItem={
                      <FlexLayout gap={0.5} align="center">
                        <StatusIndicator status={rule.tone} aria-hidden />
                        <Text styleAs="label">{rule.text}</Text>
                      </FlexLayout>
                    }
                    endItem={
                      action &&
                      g.open > 0 && (
                        <StackLayout gap={0.5} align="end">
                          <Button
                            sentiment="accented"
                            appearance="bordered"
                            disabled={action.disabled}
                            onClick={() =>
                              setChased((prev) => ({
                                ...prev,
                                [g.owner]: `${onboardingCase.asOf}, 10:15 BST`,
                              }))
                            }
                          >
                            {action.label}
                          </Button>
                          {action.hint && (
                            <Text styleAs="label" color="secondary">
                              {action.hint}
                            </Text>
                          )}
                          {chased[g.owner] && (
                            <Text styleAs="label" color="secondary">
                              Logged {chased[g.owner]} by {onboardingCase.analyst}
                            </Text>
                          )}
                        </StackLayout>
                      )
                    }
                  />
                  <H3 styleAs="label">
                    {g.items.length} item{g.items.length === 1 ? "" : "s"}
                  </H3>
                  {g.items.map((item, i) => (
                    <StackLayout gap={2} key={item.id}>
                      {i > 0 && <Divider variant="tertiary" />}
                      <RequirementRow item={item} />
                    </StackLayout>
                  ))}
                </StackLayout>
              </AccordionPanel>
            </Accordion>
          );
        })}
      </AccordionGroup>
    </StackLayout>
  );
}

