export type ActorRole = 'Client' | 'Relationship banker' | 'Onboarding analyst' | 'Second analyst' | 'Sanctions screening team';
export type RequirementStatus = 'Not requested' | 'Requested' | 'Received' | 'In review' | 'Rejected' | 'Complete';
export type RequirementCategory = 'Identity' | 'Ownership' | 'Tax' | 'Screening' | 'Approval' | 'Account';

export interface OnboardingRequirement {
  readonly id: string;
  readonly label: string;
  readonly category: RequirementCategory;
  readonly status: RequirementStatus;
  readonly blocking: boolean;
  readonly owner: ActorRole;
  readonly ownerName: string;
  readonly requestedOn: string | null;
  readonly dueOn: string;
  readonly reason: string;
  readonly evidenceRef: string | null;
  readonly clientContactAllowed: boolean;
}

export interface OnboardingCase {
  readonly caseId: string;
  readonly clientName: string;
  readonly riskRating: 'Low' | 'Medium' | 'High';
  readonly requiresSecondApproval: boolean;
  readonly openedOn: string;
  readonly asOf: string;
  readonly slaDays: number;
  readonly slaDay: number;
  readonly slaDueOn: string;
  readonly cutOff: string;
  readonly settlementAccount: string;
  readonly initialDeposit: string;
  readonly analyst: string;
}

