  caseId: 'KYC-2026-04817',
  clientName: 'Halvorsen Marine Logistics Ltd',
  riskRating: 'High',
  requiresSecondApproval: true,
  openedOn: '05 Oct 2026',
  asOf: '14 Oct 2026',
  slaDays: 10,
  slaDay: 8,
  slaDueOn: '16 Oct 2026',
  cutOff: '17:00 BST',
  settlementAccount: 'GB•• •••• •••• 4821',
  initialDeposit: 'GBP 250,000.00',
  analyst: 'Wei Chen'
} as const;

export const requirements: readonly OnboardingRequirement[] = [
  { id: 'REQ-01', label: 'Certified certificate of incorporation', category: 'Identity', status: 'Complete', blocking: false, owner: 'Client', ownerName: 'Ingrid Halvorsen', requestedOn: '06 Oct 2026', dueOn: '12 Oct 2026', reason: 'Certified copy matches registry extract.', evidenceRef: 'EV-88121', clientContactAllowed: true },
  { id: 'REQ-02', label: 'Register of directors and shareholders', category: 'Ownership', status: 'Rejected', blocking: true, owner: 'Client', ownerName: 'Ingrid Halvorsen', requestedOn: '06 Oct 2026', dueOn: '15 Oct 2026', reason: 'Document is unsigned and dated over 12 months ago.', evidenceRef: 'EV-88134', clientContactAllowed: true },
  { id: 'REQ-03', label: 'UBO passport: Magnus Halvorsen (38% holder)', category: 'Identity', status: 'Requested', blocking: true, owner: 'Client', ownerName: 'Magnus Halvorsen', requestedOn: '09 Oct 2026', dueOn: '15 Oct 2026', reason: 'Beneficial owner above 25% threshold must be verified.', evidenceRef: null, clientContactAllowed: true },
  { id: 'REQ-04', label: 'Source of wealth explanation', category: 'Ownership', status: 'Not requested', blocking: true, owner: 'Relationship banker', ownerName: 'Priya Natarajan', requestedOn: null, dueOn: '15 Oct 2026', reason: 'High-risk client; banker to obtain and attest narrative.', evidenceRef: null, clientContactAllowed: true },
  { id: 'REQ-05', label: 'Expected activity and counterparties profile', category: 'Account', status: 'Received', blocking: false, owner: 'Onboarding analyst', ownerName: 'Wei Chen', requestedOn: '07 Oct 2026', dueOn: '15 Oct 2026', reason: 'Received 13 Oct 2026; review against business model.', evidenceRef: 'EV-88160', clientContactAllowed: true },
  { id: 'REQ-06', label: 'Tax residency self-certification (CRS)', category: 'Tax', status: 'Requested', blocking: false, owner: 'Relationship banker', ownerName: 'Priya Natarajan', requestedOn: '10 Oct 2026', dueOn: '16 Oct 2026', reason: 'Form sent via banker; client signature outstanding.', evidenceRef: null, clientContactAllowed: true },
  { id: 'REQ-07', label: 'Sanctions screening: vessel owner match review', category: 'Screening', status: 'In review', blocking: true, owner: 'Sanctions screening team', ownerName: 'Screening Desk EMEA', requestedOn: '08 Oct 2026', dueOn: '15 Oct 2026', reason: 'Potential name match on one vessel owner. Do not contact client.', evidenceRef: 'EV-88149', clientContactAllowed: false },
